import "server-only";
import { db } from "@/lib/db";
import { getSettingBool } from "@/lib/settings";
import { loadRuleSet } from "@/lib/directory-blocklist-db";
import { buildRuleSet, type RuleSet } from "@/lib/directory-blocklist";
import { liveCountsFresh } from "@/lib/directory-liveness";
import { nxeonEntries, filterExternalRows } from "@/lib/server-directory-data";
import { connKey, dedupeEntries, entryKeys, rankEntries, type DirEntry } from "@/lib/server-directory";
import { buildByShortId, buildFacets, buildPage, type DirQuery, type PublicOpts } from "@/lib/directory-query-sql";
import { rollUp, type FacetRow, type Facets } from "@/lib/directory-seo";
import { externalServerId, nxeonServerId } from "@/lib/directory-ids";

/**
 * Database side of the directory aggregate pages (home, games index, game, game + region, detail).
 * SQL pages and counts the third-party set (lib/directory-query-sql.ts); Nxeon-hosted entries (tens)
 * are loaded whole, merged as a pinned set and never paginated against. Every source degrades to
 * "none from there" on error, never a broken page (the `safe()` pattern of server-directory-data).
 *
 * Caching: the facet roll-up is one GROUP BY over the public set, kept in memory for FACET_TTL_MS per
 * process (the ingest refreshes rows a few times a day; counts a minute or two old are fine and are
 * labelled "at the last refresh"). List pages are one indexed query each and are not cached.
 */
const FACET_TTL_MS = 120_000;
const RULES_TTL_MS = 60_000;

const safe = async <T,>(p: Promise<T>, fallback: T): Promise<T> => { try { return await p; } catch { return fallback; } };

type Ctx = { externalOn: boolean; probeOn: boolean; nxeon: DirEntry[]; excludeKeys: string[] };
let ctxCache: { at: number; v: Ctx } | null = null;

/** Flags + Nxeon entries (deduped) + their connection keys, shared by every query on a page. */
export async function directoryContext(): Promise<Ctx> {
  if (ctxCache && Date.now() - ctxCache.at < 30_000) return ctxCache.v;
  const [externalOn, probeOn, raw] = await Promise.all([
    safe(getSettingBool("directory_external_show", false), false),
    safe(getSettingBool("directory_probe_enabled", false), false),
    safe(nxeonEntries(), [] as DirEntry[]),
  ]);
  const nxeon = rankEntries(dedupeEntries(raw).entries).map((e) => ({ ...e, publicId: e.source === "nxeon-paid" ? nxeonServerId(e.game, e.key) : null }));
  const keys = new Set<string>();
  for (const e of raw) for (const k of entryKeys(e)) keys.add(k);
  const v = { externalOn, probeOn, nxeon, excludeKeys: [...keys] };
  ctxCache = { at: Date.now(), v };
  return v;
}

const opts = (c: Ctx): PublicOpts => ({ probeOn: c.probeOn, now: Date.now(), excludeKeys: c.excludeKeys });

let facetCache: { at: number; v: Facets } | null = null;
/** Every count the aggregate pages show: third-party (SQL GROUP BY) plus Nxeon-hosted entries. */
export async function directoryFacets(): Promise<Facets> {
  if (facetCache && Date.now() - facetCache.at < FACET_TTL_MS) return facetCache.v;
  const c = await directoryContext();
  let rows: FacetRow[] = [];
  if (c.externalOn) {
    const q = buildFacets(opts(c));
    rows = await safe(db.$queryRawUnsafe<FacetRow[]>(q.text, ...q.params), []);
  }
  for (const e of c.nxeon) rows.push({ game: e.game, cc: e.country, n: 1, p: e.players ?? 0, newest: null });
  const v = rollUp(rows);
  facetCache = { at: Date.now(), v };
  return v;
}

let rulesCache: { at: number; v: RuleSet } | null = null;
async function rules(): Promise<RuleSet> {
  if (rulesCache && Date.now() - rulesCache.at < RULES_TTL_MS) return rulesCache.v;
  const v = await safe(loadRuleSet().then((r) => r.set), buildRuleSet().set);
  rulesCache = { at: Date.now(), v };
  return v;
}

type Row = {
  id: string; game: string; name: string; host: string; port: number; map: string | null; country: string | null;
  players: number | null; maxPlayers: number | null; version: string | null; attribution: string | null; probeKind: string | null;
  connKey: string; ipKey: string | null; ptrName: string | null; lastSeenAt: Date; lastAliveAt: Date | null; firstSeenAt: Date;
  imageUrl: string | null; description: string | null; source?: string; total?: number;
};

/** A stored third-party row as a directory entry (same mapping as server-directory-data externalEntries). */
export function rowToEntry(r: Row, now = Date.now()): DirEntry {
  return {
    key: `x-${r.id.slice(0, 10)}`, source: "external", nxeon: false, game: r.game,
    name: r.name, tagline: "", description: r.description ?? "",
    imageUrl: r.imageUrl, address: `${r.host}:${r.port}`, host: r.host, port: r.port,
    alsoKeys: r.ipKey ? [r.ipKey] : [],
    players: liveCountsFresh(r, now) ? r.players : null, maxPlayers: r.maxPlayers, country: r.country ? r.country.toUpperCase() : null, region: null, featured: false,
    href: null, websiteUrl: null, seenAt: r.lastSeenAt.getTime(),
    attribution: r.attribution ?? (r.source === "valve" || !r.source ? "steam" : null),
    checkedAt: r.lastAliveAt && r.probeKind !== "listing" ? r.lastAliveAt.getTime() : null,
    publicId: externalServerId(r.game, r.connKey || connKey(r.game, r.host, r.port)),
    map: r.map, firstSeenAt: r.firstSeenAt.getTime(),
  };
}

export type ListResult = { rows: DirEntry[]; total: number; error: boolean };

const LIST_TTL_MS = 60_000;
const LIST_MAX = 300;
const listCache = new Map<string, { at: number; v: ListResult }>();

/**
 * One page of third-party servers for the filters (empty when third-party listing is switched off).
 * Results are kept LIST_TTL_MS per process (bounded LRU-ish map): the home shelves run cross-game
 * sorts (~100 ms at 40k rows without new indexes) and the data only changes when the ingest runs.
 */
export async function listExternal(f: DirQuery): Promise<ListResult> {
  const c = await directoryContext();
  if (!c.externalOn) return { rows: [], total: 0, error: false };
  const key = JSON.stringify([f.game ?? null, f.countries ?? null, f.q ?? null, f.players ?? "any", f.sort ?? "players", f.page ?? 1, c.probeOn]);
  const hit = listCache.get(key);
  if (hit && Date.now() - hit.at < LIST_TTL_MS) return hit.v;
  const v = await listExternalUncached(f, c);
  if (!v.error) {
    if (listCache.size >= LIST_MAX) listCache.delete(listCache.keys().next().value!);
    listCache.set(key, { at: Date.now(), v });
  }
  return v;
}

async function listExternalUncached(f: DirQuery, c: Ctx): Promise<ListResult> {
  const q = buildPage(f, opts(c));
  let raw: Row[];
  try { raw = await db.$queryRawUnsafe<Row[]>(q.text, ...q.params); } catch { return { rows: [], total: 0, error: true }; }
  const total = raw[0]?.total ?? 0;
  const kept = filterExternalRows(raw, await rules());
  const now = Date.now();
  return { rows: kept.map((r) => rowToEntry(r, now)), total, error: false };
}

/** Nxeon-hosted entries for a game (and region countries), ranked. */
export async function nxeonFor(game: string | null, countries?: string[] | null): Promise<DirEntry[]> {
  const c = await directoryContext();
  return c.nxeon.filter((e) => (!game || e.game === game) && (!countries?.length || (!!e.country && countries.includes(e.country.toUpperCase()))));
}

/** Detail lookup by public id: Nxeon-hosted listing first, then the public third-party set. */
export async function findServer(game: string, hash: string): Promise<DirEntry | null> {
  const c = await directoryContext();
  const id = `${game}-${hash}`;
  const nx = c.nxeon.find((e) => e.publicId === id);
  if (nx) return nx;
  if (!c.externalOn) return null;
  const q = buildByShortId(game, hash, opts(c));
  const rows = await safe(db.$queryRawUnsafe<Row[]>(q.text, ...q.params), []);
  const kept = filterExternalRows(rows, await rules());
  return kept[0] ? rowToEntry(kept[0]) : null;
}

/** Test hook: drop the in-process caches. */
export function resetDirectoryCaches() { ctxCache = null; facetCache = null; rulesCache = null; listCache.clear(); }
/**
 * Server directory query builder: PURE (no db, no I/O; unit-tested). Turns the URL-level filters of the
 * public directory into ONE parameterised SQL WHERE over "ExternalServer" (values only ever travel as
 * $n parameters, never spliced into the text), plus the ORDER BY / LIMIT for a page of results.
 *
 * The public set is the same rule set the in-memory loader (lib/server-directory-data.ts externalEntries)
 * applies, moved into SQL so the database pages and counts instead of the page loading a capped top-N:
 *   hidden = false, stored blocklist verdict empty, seen by its source in the last 3 days,
 *   prober OFF: not DEAD / prober ON: ALIVE and answered within ALIVE_VISIBLE_MS,
 *   and not one of Nxeon's own connection keys (those are listed as Nxeon entries instead).
 * The live blocklist re-check stays in code, on the page of rows actually rendered (cheap safety net).
 */
import { ALIVE_VISIBLE_MS, FRESH_COUNT_MS } from "@/lib/directory-liveness";

export const PAGE_SIZE = 24;
/** Deepest page served (24 x 200 = 4,800 rows); deeper ?page= values clamp here. */
export const MAX_PAGE = 200;
export const SEEN_WITHIN_MS = 3 * 86_400_000;
export const MAX_Q_LEN = 60;
export const MIN_Q_LEN = 2;

export type DirSort = "players" | "newest" | "name";
export type PlayersFilter = "any" | "has" | "notfull";

export type DirQuery = {
  game?: string | null;
  /** Upper-case ISO-2 codes (a continent's list or one country). Empty/undefined = everywhere. */
  countries?: string[] | null;
  q?: string | null;
  players?: PlayersFilter;
  sort?: DirSort;
  page?: number;
};

export type BuiltSql = { text: string; params: unknown[] };

export type PublicOpts = { probeOn: boolean; now: number; excludeKeys?: string[] };

/** Escape LIKE wildcards in user text (backslash is the default LIKE escape in Postgres). */
export const likeEscape = (s: string) => s.replace(/[\\%_]/g, (c) => "\\" + c);

/** Normalise free-text search: trimmed, collapsed, bounded; null when too short to be useful. */
export function normQ(raw: unknown): string | null {
  const s = String(raw ?? "").replace(/[\u0000-\u001f\u007f]/g, "").replace(/\s+/g, " ").trim().slice(0, MAX_Q_LEN);
  return s.length >= MIN_Q_LEN ? s : null;
}

/** Fresh-count predicate (players shown as "playing now" only when the newest source is under an hour old). */
export const FRESH_SQL = (nowParam: string, freshParam: string) =>
  `GREATEST("lastSeenAt", COALESCE("lastAliveAt", "lastSeenAt")) >= (${nowParam}::timestamptz - (${freshParam}::int * interval '1 millisecond'))`;

/** WHERE clause (without the keyword) + params for the public set narrowed by `q`. Pure. */
export function buildWhere(f: DirQuery, o: PublicOpts): BuiltSql {
  const params: unknown[] = [];
  const p = (v: unknown) => { params.push(v); return `$${params.length}`; };
  const now = p(new Date(o.now).toISOString());
  const parts: string[] = [
    `"hidden" = false`,
    `"blockedReason" IS NULL`,
    `"lastSeenAt" >= (${now}::timestamptz - (${p(SEEN_WITHIN_MS)}::bigint * interval '1 millisecond'))`,
  ];
  if (o.probeOn) parts.push(`"probeStatus" = 'ALIVE' AND "lastAliveAt" >= (${now}::timestamptz - (${p(ALIVE_VISIBLE_MS)}::bigint * interval '1 millisecond'))`);
  else parts.push(`"probeStatus" <> 'DEAD'`);
  if (o.excludeKeys?.length) {
    const k = p(o.excludeKeys);
    parts.push(`NOT ("connKey" = ANY(${k}::text[]))`, `("ipKey" IS NULL OR NOT ("ipKey" = ANY(${k}::text[])))`);
  }
  if (f.game) parts.push(`"game" = ${p(f.game)}`);
  if (f.countries?.length) parts.push(`upper("country") = ANY(${p(f.countries.map((c) => c.toUpperCase()))}::text[])`);
  const q = normQ(f.q);
  if (q) {
    const lq = likeEscape(q.toLowerCase());
    parts.push(`(lower("name") LIKE ${p(`%${lq}%`)} OR lower("host") LIKE ${p(`${lq}%`)} OR lower(COALESCE("map", '')) LIKE ${p(`%${lq}%`)})`);
  }
  if (f.players === "has" || f.players === "notfull") {
    const fresh = FRESH_SQL(now, p(FRESH_COUNT_MS));
    if (f.players === "has") parts.push(`"players" > 0 AND ${fresh}`);
    else parts.push(`("maxPlayers" IS NULL OR "players" IS NULL OR "players" < "maxPlayers")`);
  }
  return { text: parts.join(" AND "), params };
}

/** ORDER BY. "players" ranks by the count only while it is fresh (a stale count shows "-", so it must not rank first). */
export function orderBy(sort: DirSort | undefined, fresh = "true"): string {
  switch (sort) {
    case "newest": return `"firstSeenAt" DESC, "id" ASC`;
    case "name": return `lower("name") ASC, "id" ASC`;
    default: return `(CASE WHEN ${fresh} THEN "players" END) DESC NULLS LAST, lower("name") ASC, "id" ASC`;
  }
}

export const clampPage = (raw: unknown): number => {
  const n = Math.floor(Number(raw));
  return Number.isFinite(n) && n >= 1 ? Math.min(n, MAX_PAGE) : 1;
};

/** One page of rows + the total (window count, so one round trip). Pure. */
export function buildPage(f: DirQuery, o: PublicOpts, pageSize = PAGE_SIZE): BuiltSql {
  const w = buildWhere(f, o);
  const page = clampPage(f.page ?? 1);
  const fresh = FRESH_SQL("$1", `$${w.params.length + 1}`);
  const params = [...w.params, FRESH_COUNT_MS, pageSize, (page - 1) * pageSize];
  const text = `SELECT "id","game","name","host","port","map","country","players","maxPlayers","version","attribution","probeKind","connKey","ipKey","ptrName","lastSeenAt","lastAliveAt","firstSeenAt","imageUrl","description", count(*) OVER()::int AS "total"`
    + ` FROM "ExternalServer" WHERE ${w.text} ORDER BY ${orderBy(f.sort, fresh)} LIMIT $${params.length - 1} OFFSET $${params.length}`;
  return { text, params };
}

/**
 * Facet roll-up of the whole public set (or one game): rows, fresh players and newest listing per
 * (game, country). One GROUP BY feeds the home page, every game page's region tabs and the sitemap.
 */
export function buildFacets(o: PublicOpts, game?: string | null): BuiltSql {
  const w = buildWhere({ game: game ?? null }, o);
  const fresh = FRESH_SQL("$1", `$${w.params.length + 1}`);
  return {
    text: `SELECT "game", upper("country") AS "cc", count(*)::int AS "n",`
      + ` COALESCE(sum(CASE WHEN ${fresh} THEN GREATEST(COALESCE("players",0),0) ELSE 0 END),0)::int AS "p",`
      + ` max("firstSeenAt") AS "newest" FROM "ExternalServer" WHERE ${w.text} GROUP BY 1,2`,
    params: [...w.params, FRESH_COUNT_MS],
  };
}

/** Rows whose public short id (see shortHash) matches, within one game. */
export function buildByShortId(game: string, hash: string, o: PublicOpts): BuiltSql {
  const w = buildWhere({ game }, o);
  const params = [...w.params, hash];
  return {
    text: `SELECT * FROM "ExternalServer" WHERE ${w.text} AND left(encode(sha256(convert_to("connKey", 'UTF8')), 'hex'), 10) = $${params.length} ORDER BY "lastSeenAt" DESC LIMIT 1`,
    params,
  };
}
import { createHash } from "node:crypto";
import { GAME_FAMILIES } from "@/lib/games";

const isGameFamily = (g: string) => (GAME_FAMILIES as readonly string[]).includes(g);

/**
 * Public ids for server detail pages: `<game>-<10 hex>`. Never an internal cuid or a database row id.
 *  - third-party rows: the first 10 hex of sha256(connKey) (stable across re-ingest: connKey is the
 *    normalised address). The SQL side computes the same value (lib/directory-query-sql.ts buildByShortId).
 *  - Nxeon-hosted listings: sha256("nx:" + the entry's opaque key), so the two can never collide in meaning.
 */
export const shortHash = (s: string) => createHash("sha256").update(s, "utf8").digest("hex").slice(0, 10);
export const externalServerId = (game: string, connKey: string) => `${game}-${shortHash(connKey)}`;
export const nxeonServerId = (game: string, entryKey: string) => `${game}-${shortHash("nx:" + entryKey)}`;

/** Split a detail id into game + hash; null when malformed or the game is unknown. */
export function parseServerId(raw: string): { game: string; hash: string } | null {
  const m = /^([a-z0-9]{2,20})-([0-9a-f]{10})$/.exec(String(raw ?? "").trim().toLowerCase());
  if (!m || !isGameFamily(m[1])) return null;
  return { game: m[1], hash: m[2] };
}
/**
 * Directory region slugs: PURE and client-safe. One table maps the URL segment of
 * /game-servers/directory/<game>/<region> to a continent or an ISO-3166 alpha-2 country.
 *
 *  - continent slugs: europe, asia, north-america, south-america, oceania, africa
 *  - country slugs: the English short name, lower-case and dashed ("united-states", "south-korea")
 *  - aliases (301 to the canonical slug): the lower-case ISO-2 code ("de" -> "germany"), "uk", "usa"
 *  - anything else is unknown (the route 404s)
 *
 * Every country that lib/geo-continent.ts maps to a continent has exactly one slug here, and no
 * country slug collides with a continent slug (both are unit-tested).
 */
import { CONTINENT_LABELS, CONTINENT_ORDER, continentOf, countriesOf, type Continent } from "@/lib/geo-continent";

export const CONTINENT_SLUG: Record<Continent, string> = {
  NA: "north-america", SA: "south-america", EU: "europe", AS: "asia", OC: "oceania", AF: "africa",
};
const CONTINENT_BY_SLUG = new Map<string, Continent>(CONTINENT_ORDER.map((c) => [CONTINENT_SLUG[c], c]));

/** Short English names where Intl's name is long or political-sounding for a URL / heading. */
const NAME_OVERRIDE: Record<string, string> = {
  HK: "Hong Kong", MO: "Macao", KR: "South Korea", KP: "North Korea", RU: "Russia", TW: "Taiwan",
  CZ: "Czechia", PS: "Palestine", MM: "Myanmar", CI: "Ivory Coast", CD: "DR Congo", CG: "Congo",
  VA: "Vatican City", FM: "Micronesia", LA: "Laos", SY: "Syria", IR: "Iran", MD: "Moldova",
  BO: "Bolivia", VE: "Venezuela", TZ: "Tanzania", VN: "Vietnam", BN: "Brunei", XK: "Kosovo",
  US: "United States", GB: "United Kingdom", AE: "United Arab Emirates", BQ: "Caribbean Netherlands",
  SX: "Sint Maarten", MF: "Saint Martin", BL: "Saint Barthelemy", PM: "Saint Pierre and Miquelon",
  SH: "Saint Helena", ST: "Sao Tome and Principe", CW: "Curacao", RE: "Reunion", AX: "Aland Islands",
  TR: "Turkey", SJ: "Svalbard", FK: "Falkland Islands", VI: "US Virgin Islands", VG: "British Virgin Islands",
  KN: "Saint Kitts and Nevis", LC: "Saint Lucia", VC: "Saint Vincent", TC: "Turks and Caicos", MP: "Northern Mariana Islands",
  AS: "American Samoa", WF: "Wallis and Futuna", GS: "South Georgia", EH: "Western Sahara", SZ: "Eswatini",
};

let intl: Intl.DisplayNames | null = null;
try { intl = new Intl.DisplayNames(["en"], { type: "region" }); } catch { intl = null; }

/** "Germany" for "DE" (any case). Unknown codes come back upper-cased. */
export function countryName(code: string): string {
  const cc = code.trim().toUpperCase();
  if (NAME_OVERRIDE[cc]) return NAME_OVERRIDE[cc];
  try { return intl?.of(cc) ?? cc; } catch { return cc; }
}

export const slugify = (s: string) =>
  s.normalize("NFKD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/&/g, " and ").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

const ALL_CC: string[] = CONTINENT_ORDER.flatMap((c) => countriesOf(c));
const SLUG_OF = new Map<string, string>();
const CC_BY_SLUG = new Map<string, string>();
for (const cc of ALL_CC) {
  const s = slugify(countryName(cc));
  SLUG_OF.set(cc, s);
  CC_BY_SLUG.set(s, cc);
}

/** URL slug for a country code, or null for a code outside the table. */
export function countrySlug(code: string | null | undefined): string | null {
  if (!code) return null;
  return SLUG_OF.get(code.trim().toUpperCase()) ?? null;
}
export const continentSlug = (c: Continent) => CONTINENT_SLUG[c];
export const allCountryCodes = (): readonly string[] => ALL_CC;

export type Region =
  | { kind: "continent"; code: Continent; slug: string; label: string }
  | { kind: "country"; code: string; slug: string; label: string; continent: Continent };

export function continentRegion(c: Continent): Region {
  return { kind: "continent", code: c, slug: CONTINENT_SLUG[c], label: CONTINENT_LABELS[c] };
}
export function countryRegion(code: string): Region | null {
  const cc = code.trim().toUpperCase();
  const slug = SLUG_OF.get(cc);
  const cont = continentOf(cc);
  if (!slug || !cont) return null;
  return { kind: "country", code: cc, slug, label: countryName(cc), continent: cont };
}

const ALIASES: Record<string, string> = { uk: "GB", usa: "US", america: "US", "great-britain": "GB", england: "GB", korea: "KR" };

/**
 * Resolve a URL segment. `{ region }` for a canonical slug, `{ redirect }` (the canonical slug) for an
 * alias form (ISO code, different case, "uk"), null for anything unknown.
 */
export function resolveRegionSlug(raw: string): { region: Region } | { redirect: string } | null {
  const s = String(raw ?? "").trim();
  if (!s || s.length > 60) return null;
  const lower = s.toLowerCase();
  const cont = CONTINENT_BY_SLUG.get(lower);
  if (cont) return lower === s ? { region: continentRegion(cont) } : { redirect: lower };
  const cc = CC_BY_SLUG.get(lower);
  if (cc) return lower === s ? { region: countryRegion(cc)! } : { redirect: lower };
  const alias = ALIASES[lower] ?? (/^[a-z]{2}$/.test(lower) && SLUG_OF.has(lower.toUpperCase()) ? lower.toUpperCase() : null);
  if (alias) return { redirect: SLUG_OF.get(alias)! };
  const fuzzy = CC_BY_SLUG.get(slugify(s));
  if (fuzzy) return { redirect: SLUG_OF.get(fuzzy)! };
  return null;
}

/** ISO codes covered by a region (a continent's list, or the one country). Upper-case. */
export function regionCountries(r: Region): string[] {
  return r.kind === "continent" ? countriesOf(r.code) : [r.code];
}

1	/**
2	 * Server directory aggregate pages: PURE rules (no db, no I/O; unit-tested).
3	 *
4	 * Owns: the URL tree, the facet roll-up maths, which pages may be indexed (and so listed in the
5	 * sitemap), canonical URLs, titles/descriptions, the data-derived intro copy, breadcrumbs and the
6	 * ItemList structured data. Copy here states only what the numbers say: no adjectives, no claims.
7	 *
8	 * Index rules (owner, 2026-10-05):
9	 *  - directory home and the all-games index: always indexable (they always have content: every game)
10	 *  - a game page: indexable with >= GAME_INDEX_MIN listings; an empty/thin game page renders
11	 *    (honest empty state + host CTA) but is noindex and not in the sitemap
12	 *  - a game + region page: indexable only with >= REGION_INDEX_MIN listings
13	 *  - page 2+ of a list, and any filtered/searched/sorted variant: noindex,follow, canonical to page 1
14	 *    for filters (page N keeps a self canonical so its links are still crawled)
15	 *  - a server detail page: indexable only for Nxeon-hosted servers; third-party servers noindex,follow
16	 */
17	import { CONTINENT_LABELS, CONTINENT_ORDER, continentOf, type Continent } from "@/lib/geo-continent";
18	import { GAME_FAMILIES } from "@/lib/games";
19	import { continentRegion, countryName, countryRegion, countrySlug, type Region } from "@/lib/directory-regions";
20	
21	export const DIR = "/game-servers/directory";
22	export const GAME_INDEX_MIN = 5;
23	export const REGION_INDEX_MIN = 10;
24	
25	export const dirPath = () => DIR;
26	export const gamesPath = () => `${DIR}/games`;
27	export const gamePath = (game: string) => `${DIR}/${game}`;
28	export const regionPath = (game: string, slug: string) => `${DIR}/${game}/${slug}`;
29	export const serverPath = (id: string) => `${DIR}/server/${id}`;
30	
31	// ── facets ────────────────────────────────────────────────────────────────
32	export type FacetRow = { game: string; cc: string | null; n: number; p: number; newest: Date | null };
33	export type Tally = { n: number; p: number; newest: number };
34	const zero = (): Tally => ({ n: 0, p: 0, newest: 0 });
35	const add = (t: Tally, r: { n: number; p: number; newest: Date | null }) => {
36	  t.n += r.n; t.p += r.p; t.newest = Math.max(t.newest, r.newest ? r.newest.getTime() : 0);
37	};
38	
39	export type GameFacet = Tally & { game: string; countries: Map<string, Tally>; continents: Map<Continent, Tally>; unknown: Tally };
40	export type Facets = { total: Tally; games: Map<string, GameFacet>; countries: Map<string, Tally>; continents: Map<Continent, Tally> };
41	
42	/** Roll the (game, country) GROUP BY rows up into every count the pages show. */
43	export function rollUp(rows: FacetRow[]): Facets {
44	  const out: Facets = { total: zero(), games: new Map(), countries: new Map(), continents: new Map() };
45	  for (const r of rows) {
46	    const cc = r.cc ? r.cc.toUpperCase() : null;
47	    const cont = continentOf(cc);
48	    let g = out.games.get(r.game);
49	    if (!g) { g = { game: r.game, ...zero(), countries: new Map(), continents: new Map(), unknown: zero() }; out.games.set(r.game, g); }
50	    add(g, r); add(out.total, r);
51	    if (cc && cont) {
52	      for (const [m, k] of [[g.countries, cc], [out.countries, cc]] as const) { const t = m.get(k) ?? zero(); add(t, r); m.set(k, t); }
53	      for (const m of [g.continents, out.continents]) { const t = m.get(cont) ?? zero(); add(t, r); m.set(cont, t); }
54	    } else add(g.unknown, r);
55	  }
56	  return out;
57	}
