59	/** The count for one game in one region (0 when absent). */
60	export function regionTally(f: Facets, game: string | null, r: Region): Tally {
61	  const g = game ? f.games.get(game) : null;
62	  if (game && !g) return zero();
63	  const c = r.kind === "continent" ? (g ? g.continents : f.continents).get(r.code) : (g ? g.countries : f.countries).get(r.code);
64	  return c ?? zero();
65	}
