67	/** Continent tabs in display order, only continents with listings. */
68	export function continentTabs(f: Facets, game: string | null): { region: Region; t: Tally }[] {
69	  const g = game ? f.games.get(game) : null;
70	  const src = game ? g?.continents : f.continents;
71	  return CONTINENT_ORDER.filter((c) => (src?.get(c)?.n ?? 0) > 0).map((c) => ({ region: continentRegion(c), t: src!.get(c)! }))
72	    .sort((a, b) => b.t.n - a.t.n);
73	}
74	
75	/** Countries by listings desc, optionally within one continent. */
76	export function topCountries(f: Facets, game: string | null, limit: number, within?: Continent): { region: Region; t: Tally }[] {
77	  const g = game ? f.games.get(game) : null;
78	  const src = game ? g?.countries : f.countries;
79	  if (!src) return [];
80	  return [...src.entries()]
81	    .filter(([cc]) => !within || continentOf(cc) === within)
82	    .map(([cc, t]) => ({ region: countryRegion(cc), t }))
83	    .filter((x): x is { region: Region; t: Tally } => !!x.region)
84	    .sort((a, b) => b.t.n - a.t.n || a.region.label.localeCompare(b.region.label))
85	    .slice(0, limit);
86	}
