150	/** Up to `n` alternative regions to suggest from an empty region page (same continent first, then busiest). */
151	export function nearestAlternatives(f: Facets, game: string, region: Region, n = 3): { region: Region; t: Tally }[] {
152	  const cont = region.kind === "continent" ? region.code : region.continent;
153	  const same = region.kind === "country" ? topCountries(f, game, n + 1, cont).filter((x) => x.region.slug !== region.slug) : [];
154	  const conts = continentTabs(f, game).filter((x) => x.region.slug !== region.slug);
155	  const out: { region: Region; t: Tally }[] = [];
156	  for (const x of [...same, ...(region.kind === "country" ? conts.filter((c) => c.region.kind === "continent" && c.region.code === cont) : []), ...conts]) {
157	    if (out.length >= n) break;
158	    if (!out.some((o) => o.region.slug === x.region.slug)) out.push(x);
159	  }
160	  return out;
161	}
