197	// ── sitemap ───────────────────────────────────────────────────────────────
198	/** Pure part: which aggregate paths to list from a facet roll-up. Used by lib/sitemap-directory.ts. */
199	export function directorySitemapPaths(f: Facets, nxeonIds: string[] = []): { path: string; newest: number }[] {
200	  const out: { path: string; newest: number }[] = [{ path: DIR, newest: f.total.newest }, { path: gamesPath(), newest: f.total.newest }];
201	  for (const game of GAME_FAMILIES) {
202	    const g = f.games.get(game);
203	    if (!g || !indexable({ kind: "game", listings: g.n })) continue;
204	    out.push({ path: gamePath(game), newest: g.newest });
205	    for (const c of CONTINENT_ORDER) {
206	      const t = g.continents.get(c);
207	      if (t && indexable({ kind: "region", listings: t.n })) out.push({ path: regionPath(game, continentRegion(c).slug), newest: t.newest });
208	    }
209	    for (const [cc, t] of g.countries) {
210	      const r = countryRegion(cc);
211	      if (r && indexable({ kind: "region", listings: t.n })) out.push({ path: regionPath(game, r.slug), newest: t.newest });
212	    }
213	  }
214	  for (const id of nxeonIds) out.push({ path: serverPath(id), newest: 0 });
215	  return out;
216	}
