405	export type HubFilters = { q: string | null; players: PlayersFilter; sort: DirSort; page: number };
406	export function readFilters(p: Record<string, string>): HubFilters {
407	  const players = p.players === "has" || p.players === "notfull" ? p.players : "any";
408	  const sort = p.sort === "newest" || p.sort === "name" ? p.sort : "players";
