412	/** Query string for a list URL, keeping only non-default keys (stable order). */
413	export function qs(f: Partial<HubFilters>, extra: Record<string, string | null | undefined> = {}): string {
414	  const u = new URLSearchParams();
415	  for (const [k, v] of Object.entries(extra)) if (v) u.set(k, v);
416	  if (f.q) u.set("q", f.q);
417	  if (f.players && f.players !== "any") u.set("players", f.players);
418	  if (f.sort && f.sort !== "players") u.set("sort", f.sort);
419	  if (f.page && f.page > 1) u.set("page", String(f.page));
420	  const s = u.toString();
421	  return s ? `?${s}` : "";
422	}
