438	function pager(base: string, f: HubFilters, total: number, extra: Record<string, string> = {}): string {
439	  const pages = Math.min(Math.ceil(total / PAGE_SIZE), 200);
440	  if (pages <= 1) return "";
441	  const cur = f.page;
442	  const nums = new Set<number>([1, pages, cur - 1, cur, cur + 1, cur - 2, cur + 2].filter((n) => n >= 1 && n <= pages));
443	  const sorted = [...nums].sort((a, b) => a - b);
444	  const link = (n: number, label: string, rel?: string) => `<a href="${href(base)}${esc(qs({ ...f, page: n }, extra))}"${rel ? ` rel="${rel}"` : ""}${n === cur ? ` aria-current="page"` : ""}>${label}</a>`;
445	  let out = cur > 1 ? link(cur - 1, "Previous", "prev") : "";
446	  let last = 0;
447	  for (const n of sorted) { if (n - last > 1) out += `<span aria-hidden="true">…</span>`; out += link(n, String(n)); last = n; }
448	  if (cur < pages) out += link(cur + 1, "Next", "next");
449	  return `<nav class="dh-pager" aria-label="Pages">${out}</nav>`;
450	}
