521	  const r = resolveRegionSlug(String(p.region ?? ""));
522	  if (!r) notFound();
523	  if ("redirect" in r) permanentRedirect(nxmHref(regionPath(game, r.redirect)));
524	  return { game, region: r.region };
525	}
