"use client";

import { useMemo, useState } from "react";
import Link from "next/link";
import { Icon } from "./Icon";
import { CountryFlag } from "@/components/ui/CountryFlag";
import { filterRows, attributionsForRows, regionOptions, isExternalRow, liveLabel, type DirectoryRow, type RowFilters } from "@/lib/directory-portal";

/* eslint-disable @next/next/no-img-element -- local game key art, outside the optimizer */

/**
 * Browse every server other customers have chosen to publish.
 *
 * Each card leads with the game's own key art, because that is what people
 * actually scan for. Everything under it is real: the connect address its owner
 * published, the region the machine is genuinely in, and — where the game
 * answers a public query at all — how many people are on it right now, read
 * from the server a moment ago rather than from anything we store.
 *
 * A card with no live figure is showing the truth for its game. Twenty-eight of
 * the catalogue's families answer a public query; the rest have no such
 * protocol (see lib/server-query.ts), so those cards say what the game reports
 * instead of drawing a zero that would read as "empty server".
 */

export type { DirectoryRow };

function Pill({ children, tone }: { children: React.ReactNode; tone?: "live" | "free" | "quiet" | "community" }) {
  return (
    <span className={
      "inline-flex items-center gap-1.5 rounded-[6px] border px-2 py-0.5 text-[9.5px] font-bold uppercase tracking-wide " +
      (tone === "live" ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-300"
        : tone === "community" ? "border-cyan-400/45 bg-cyan-400/10 text-cyan-300"
        : tone === "free" ? "border-[#a86bff]/45 bg-[#a86bff]/12 text-[#c4a6ff]"
        : "border-rim-hi bg-well text-tx-faint")
    }>
      {children}
    </span>
  );
}

const SOURCE_LABELS: Record<string, string> = { steam: "Steam", vintagestory: "Vintage Story", truckersmp: "TruckersMP" };
const sourceLabel = (k: string | null | undefined) => (k ? SOURCE_LABELS[k] ?? k : "a public list");

function Card({ row }: { row: DirectoryRow }) {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    void navigator.clipboard?.writeText(row.address);
    setCopied(true);
    setTimeout(() => setCopied(false), 1600);
  };

  const populated = row.online !== null && row.online > 0;
  const ext = isExternalRow(row);
  const fresh = ext ? liveLabel(row) : null;

  return (
    <article data-origin={ext ? "external" : "nxeon"} className={"flex flex-col overflow-hidden rounded-[16px] border " + (ext ? "border-dashed border-rim-hi/70 " : "border-rim-hi ") + "bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))] transition hover:border-brand-400/45"}>
      {/* The game, at a glance.
          nx-dark-island: this thumbnail paints its own fixed near-black scrim
          (bg-[#050d20] plus the rgba overlay below) over the game art so the
          name/game-label text reads regardless of what image sits behind it —
          never the page's theme. Without the island, light mode's generic
          text-white-on-a-light-page fix retargeted that text to dark ink,
          which is invisible against a scrim that stayed dark on purpose. */}
      <div className="nx-dark-island relative h-[116px] overflow-hidden bg-[#050d20]">
        {row.art ? (
          /* Anchored low in the frame. These heroes carry the game's wordmark
             across their top third, and a centred crop in a band this short
             slices it in half — which reads as a broken image, not as art. */
          <img
            src={`/games/art/${row.art}_hero.jpg`}
            alt=""
            className="h-full w-full object-cover opacity-55"
            style={{
              objectPosition: "center 68%",
              WebkitMaskImage: "linear-gradient(180deg, #000 0%, #000 55%, transparent 100%)",
              maskImage: "linear-gradient(180deg, #000 0%, #000 55%, transparent 100%)",
            }}
          />
        ) : (
          <span className="grid h-full w-full place-items-center"><Icon name="gamepad" size={26} /></span>
        )}
        <span aria-hidden className="absolute inset-0"
              style={{ background: "linear-gradient(180deg,rgba(2,7,20,.15),rgba(2,7,20,.85))" }} />

        <div className="absolute inset-x-3 bottom-2.5 flex flex-wrap items-end gap-2">
          <span className="min-w-0 flex-1">
            <span className="block truncate text-[14.5px] font-extrabold leading-tight text-white">{row.name}</span>
            <span className="block truncate text-[11.5px] text-white/65">
              {row.gameLabel}{row.variant ? ` · ${row.variant}` : ""}
            </span>
          </span>
          {ext ? <Pill tone="quiet">Found on {sourceLabel(row.attribution)}</Pill>
            : row.community ? <Pill tone="community">Nxeon community</Pill>
            : row.isFree ? <Pill tone="free">Free</Pill>
            : <Pill tone="community">Hosted on Nxeon</Pill>}
        </div>
      </div>

      <div className="flex flex-1 flex-col gap-2.5 p-3.5">
        {/* The MOTD is the server's OWN current message, straight off the wire —
            worth showing above the owner's stored description because it is what
            a player sees in their game client this second. */}
        {(row.motd || row.description) && (
          <p className="line-clamp-2 text-[12px] leading-relaxed text-tx-dim">{row.motd ?? row.description}</p>
        )}

        <div className="flex flex-wrap items-center gap-x-3.5 gap-y-1.5 text-[11.5px] text-tx-faint">
          {row.online !== null ? (
            <span className={"inline-flex items-center gap-1.5 font-semibold " + (populated ? "text-emerald-300" : "text-tx-dim")}>
              <span className={"h-[6px] w-[6px] rounded-full " + (populated ? "bg-emerald-400" : "bg-slate-500")} />
              {row.onlineMax ? `${row.online} / ${row.onlineMax} playing` : `${row.online} playing`}
            </span>
          ) : row.queryable ? (
            /* The game does answer a query — this server just didn't, which
               usually means it's asleep or stopped. Say that, not "0". */
            <span className="inline-flex items-center gap-1.5">
              <span className="h-[6px] w-[6px] rounded-full bg-slate-600" />
              Didn&apos;t answer{row.slots ? ` · ${row.slots} slots` : ""}
            </span>
          ) : (
            <span title="This game has no public query protocol, so nobody can read a live count from outside — not us either.">
              {row.slots ? `${row.slots} slots` : "No live count for this game"}
            </span>
          )}

          {fresh && fresh.kind !== "none" && (
            <span className={"inline-flex items-center gap-1.5 " + (fresh.kind === "checked" ? "text-emerald-300" : "text-tx-faint")}>
              <span className={"h-[6px] w-[6px] rounded-full " + (fresh.kind === "checked" ? "bg-emerald-400" : "bg-slate-500")} />
              {fresh.kind === "checked" ? "Live" : "Listed"} · {fresh.text}
            </span>
          )}

          {row.map && <span>Map: {row.map}</span>}

          {row.regionLabel && (
            <span className="inline-flex items-center gap-1.5">
              {row.regionCountry && <CountryFlag code={row.regionCountry} size={13} />}
              {row.regionLabel}
            </span>
          )}
        </div>

        {row.community && row.joinHref && (
          <Link href={row.joinHref} className="text-[12px] font-semibold text-brand-300 hover:text-white">
            How to join{row.password ? " (password inside)" : ""} →
          </Link>
        )}
        <button
          type="button"
          onClick={copy}
          title={copied ? "Copied" : `Copy ${row.address}`}
          className="mt-auto flex items-center gap-2 rounded-[10px] border border-rim-hi bg-well px-3 py-2 text-left font-mono text-[12px] text-tx-dim transition hover:border-brand-400/45 hover:text-white"
        >
          <span className="min-w-0 flex-1 truncate">{row.address}</span>
          <Icon name={copied ? "checkcircle" : "copy"} size={12} tone="inherit"
                className={copied ? "flex-none text-emerald-400" : "flex-none opacity-60"} />
        </button>
      </div>
    </article>
  );
}

