export const dynamic = "force-dynamic";

import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { gameSubdomainBase } from "@/lib/game-subdomain-dns";
import { GAME_DISPLAY, GAME_ART_SLUG, type GameFamily } from "@/lib/games";
import { REGION_LABELS, REGION_COUNTRY } from "@/lib/node-regions";
import { queryAll, canQuery } from "@/lib/server-query";
import { ToolsAurora } from "@/components/nx/ToolsAurora";
import { listVisibleFreePublicServers, liveState, connectAddress } from "@/lib/free-public-server";
import { DirectoryView } from "@/components/nx/DirectoryView";
import { externalEntryToRow, sortRows, type DirectoryRow } from "@/lib/directory-portal";
import { loadDirectory } from "@/lib/server-directory-data";

/**
 * The server directory, inside the portal.
 *
 * There WAS a directory — at /game-servers/directory, on the marketing site —
 * and the portal's only relationship to it was a link out to a public page. So
 * a customer browsing servers left the product to do it, came back through the
 * marketing site, and the page they landed on knew nothing about them. This is
 * the same data as a real page in the app, with the things a portal can add
 * that a marketing page can't: the region a server actually runs in, and a live
 * player count queried from the server itself.
 *
 * PRIVACY. These are OTHER customers' servers. A row carries what its owner
 * chose to publish — the name, their description, the connect address — and
 * nothing else. No owner, no internal id, and specifically no raw node IP: a
 * server with no play subdomain is not listed at all, exactly as the marketing
 * directory already decided. The live probe runs server-side against the public
 * address, the same request any player's game client makes.
 *
 * LIVE COUNTS come from lib/server-query.ts, which speaks the three protocols a
 * stranger is allowed to ask: Minecraft's Server List Ping, Bedrock's RakNet
 * ping, and Valve's A2S_INFO. That covers twenty-eight of the catalogue's
 * families; the rest list their slot count and no live figure, because there is
 * no honest way to produce one. A probe that times out is treated the same as
 * one that can't be made — no number, never a zero.
 */

export default async function DirectoryPage() {
  await requireUser();
  const base = await gameSubdomainBase();

  const [paid, free] = await Promise.all([
    db.server.findMany({
      where: {
        publicListing: true, status: "RUNNING", gamePlan: { isNot: null },
        // moderation kill switch (PublicListingMeta.hidden) — no row = visible
        OR: [{ listingMeta: { is: null } }, { listingMeta: { is: { hidden: false } } }],
      },
      select: {
        id: true, name: true, label: true, publicDescription: true, subdomain: true,
        gamePlan: { select: { slots: true, gameFamily: true } },
        osTemplate: { select: { family: true } },
        node: { select: { region: true } },
        gameVariant: true,
      },
      orderBy: { createdAt: "asc" },
    }),
    db.freeMinecraftServer.findMany({
      where: { isPublic: true, status: "READY" },
      select: {
        id: true, name: true, subdomain: true,
        publicTagline: true, publicDescription: true,
        activeGameType: true, activeGameMode: true,
      },
      orderBy: { createdAt: "asc" },
    }),
  ]);

  const rows: DirectoryRow[] = [];

  for (const s of paid) {
    // No play subdomain, no listing — a raw node IP is not ours to publish.
    if (!s.subdomain) continue;
    const family = (s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? "minecraft") as GameFamily;
    rows.push({
      key: `p-${s.id.slice(0, 10)}`,
      name: s.label || s.name,
      description: s.publicDescription,
      address: `${s.subdomain}.${base}`,
      family,
      gameLabel: GAME_DISPLAY[family]?.name ?? family,
      art: GAME_ART_SLUG[family]?.hero ?? null,
      variant: s.gameVariant,
      slots: s.gamePlan?.slots ?? null,
      region: s.node?.region ?? null,
      regionLabel: s.node?.region ? REGION_LABELS[s.node.region] ?? s.node.region : null,
      regionCountry: s.node?.region ? REGION_COUNTRY[s.node.region] ?? null : null,
      isFree: false,
      queryable: canQuery(family),
      online: null,
      onlineMax: null,
      motd: null,
      map: null,
    });
  }

  for (const s of free) {
    rows.push({
      key: `f-${s.id.slice(0, 10)}`,
      name: s.name || s.subdomain,
      description: s.publicDescription || s.publicTagline,
      address: `${s.subdomain}.${base}`,
      family: "minecraft",
      gameLabel: GAME_DISPLAY.minecraft?.name ?? "Minecraft",
      art: GAME_ART_SLUG.minecraft?.hero ?? null,
      variant: s.activeGameType !== "vanilla" ? s.activeGameType : null,
      slots: null,
      /* Every free server is a container on the shared free-tier node, so there
         is no per-server node row to read a region from. Named for what it is
         rather than left blank or, worse, guessed. */
      region: "freemc",
      regionLabel: "Free tier node",
      regionCountry: null,
      isFree: true,
      queryable: true,
      online: null,
      onlineMax: null,
      motd: null,
      map: null,
    });
  }

  /* Nxeon community servers (free, public, shared; admin-managed, LIVE only).
     Their live count is the same real A2S answer the marketing page shows. The
     page route is public, so the join steps live there, not in the portal. */
  const community = await listVisibleFreePublicServers();
  const communityRows: DirectoryRow[] = await Promise.all(community.map(async (c) => {
    const l = await liveState(c, 1200);
    const family = c.game as GameFamily;
    return {
      key: `c-${c.slug}`, name: c.name, description: c.tagline,
      address: connectAddress(c), family, gameLabel: GAME_DISPLAY[family]?.name ?? c.game,
      art: GAME_ART_SLUG[family]?.hero ?? null, variant: null, slots: c.maxPlayers,
      region: c.region, regionLabel: c.region ? REGION_LABELS[c.region] ?? null : null,
      regionCountry: c.region ? REGION_COUNTRY[c.region] ?? null : null,
      isFree: true, queryable: true,
      online: l.state === "online" ? l.players : null,
      onlineMax: l.state === "online" ? l.max ?? c.maxPlayers : null,
      motd: null, map: null, community: true, joinHref: `/free-${c.game}-server`,
      password: c.passwordPolicy === "PUBLISHED" ? c.passwordHint : null,
    } satisfies DirectoryRow;
  }));

  /* One probe per listed server, bounded. Every one of these is a request the
     public internet could make anyway — it is the same packet a player's game
     client sends when it draws its own server list. */
  const live = await queryAll(rows.map((r) => ({ family: r.family, address: r.address })));
  for (const r of rows) {
    const l = live.get(r.address);
    if (!l) continue;
    r.online = l.online;
    r.onlineMax = l.max ?? r.slots;
    r.motd = l.motd;
    r.map = l.map;
  }

  /* Servers that answered, busiest first, then the rest. A directory is for
     finding somewhere with people in it. */
  rows.sort((a, b) => {
    const ao = a.online ?? -1;
    const bo = b.online ?? -1;
    if (ao !== bo) return bo - ao;
    return a.name.localeCompare(b.name);
  });

  /* Public servers found on the games' own lists (ExternalServer), shown with where they were found and when
     we last checked them. loadDirectory applies every rule the marketing page uses: the directory_external_show
     switch, liveness (dead rows never), the other-hosts blocklist and de-duplication against what Nxeon hosts, so
     this page can never show something the public page would hide. Empty table or switch off = no extra rows. */
  const external: DirectoryRow[] = [];
  try {
    const { entries } = await loadDirectory();
    for (const e of entries) {
      const fam = e.game as GameFamily;
      const r = externalEntryToRow(e, { gameLabel: GAME_DISPLAY[fam]?.name ?? e.game, art: GAME_ART_SLUG[fam]?.hero ?? null, queryable: canQuery(e.game) });
      if (r) external.push(r);
    }
  } catch { /* an un-migrated database or a failing source degrades to "none from there" */ }

  return (
    <>
      <ToolsAurora />
      <div className="relative z-[1] mx-auto flex w-full max-w-[1520px] flex-col gap-5">
        <DirectoryView rows={sortRows([...communityRows, ...rows, ...external])} />
      </div>
    </>
  );
}
import type { DirEntry } from "@/lib/server-directory";
import { continentOf, CONTINENT_LABELS, CONTINENT_ORDER, type Continent } from "@/lib/geo-continent";
import { attributionForKey as attributionFor } from "@/lib/directory-attribution";

/**
 * PURE helpers for the customer-portal directory (/dashboard/directory): the row shape, how a directory entry
 * found on a third-party list becomes a row, and the filters. Kept out of the client component so the query and
 * filter rules are unit-tested (test/directory-portal.test.ts).
 */
export type DirectoryRow = {
  key: string;
  name: string;
  description: string | null;
  address: string;
  family: string;
  gameLabel: string;
  art: string | null;
  variant: string | null;
  slots: number | null;
  region: string | null;
  regionLabel: string | null;
  regionCountry: string | null;
  isFree: boolean;
  /** Whether this game answers a public query at all. */
  queryable: boolean;
  online: number | null;
  onlineMax: number | null;
  motd: string | null;
  map: string | null;
  /** Nxeon-operated community server (FreePublicServer): shown first, links to its join page. */
  community?: boolean;
  joinHref?: string | null;
  password?: string | null;
  /** "nxeon" (hosted by Nxeon, the default) or "external" (found on a public list and checked by us). */
  origin?: "nxeon" | "external";
  /** Source attribution key for external rows: "steam" | "vintagestory" | "truckersmp". */
  attribution?: string | null;
  /** ms epoch Nxeon's own direct check last got an answer (external rows). */
  checkedAt?: number | null;
  /** ms epoch the source list last had this row (external rows). */
  seenAt?: number | null;
};

export const isExternalRow = (r: Pick<DirectoryRow, "origin">) => r.origin === "external";

/** Ordinary Intl region names; falls back to the code. */
export function countryName(code: string | null | undefined): string | null {
  if (!code || !/^[A-Za-z]{2}$/.test(code)) return null;
  try { return new Intl.DisplayNames(["en"], { type: "region" }).of(code.toUpperCase()) ?? code.toUpperCase(); } catch { return code.toUpperCase(); }
}

/** A directory entry that came from a third-party source, as a portal card. Only `source: "external"` entries qualify. */
export function externalEntryToRow(e: DirEntry, meta: { gameLabel: string; art: string | null; queryable: boolean }): DirectoryRow | null {
  if (e.source !== "external") return null;
  const cc = e.country && /^[A-Za-z]{2}$/.test(e.country) ? e.country.toUpperCase() : null;
  return {
    key: e.key, name: e.name, description: e.description || null, address: e.address,
    family: e.game, gameLabel: meta.gameLabel, art: meta.art, variant: null, slots: e.maxPlayers,
    region: cc, regionLabel: countryName(cc), regionCountry: cc,
    isFree: false, queryable: meta.queryable,
    online: e.players, onlineMax: e.players !== null ? e.maxPlayers : null,
    motd: null, map: /^Map: (.+)$/.exec(e.description)?.[1] ?? null,
    origin: "external", attribution: e.attribution ?? null, checkedAt: e.checkedAt ?? null, seenAt: e.seenAt,
  };
}

/** The attribution lines the page must show: one per source present among the rows, no duplicates. */
export function attributionsForRows(rows: Pick<DirectoryRow, "attribution">[]): { key: string; text: string; url: string; linkLabel: string }[] {
  const keys = [...new Set(rows.map((r) => r.attribution).filter((k): k is string => !!k))].sort();
  return keys.map((k) => attributionFor(k)).filter((a): a is NonNullable<typeof a> => !!a);
}

export type RowFilters = {
  q?: string; game?: string; region?: string; onlyLive?: boolean;
  /** all | nxeon (hosted by Nxeon) | external (found on public lists) */
  origin?: "all" | "nxeon" | "external";
};

export type RegionOptions = { continents: [string, string][]; places: [string, string][] };

/**
 * What the "All regions" select offers, built only from rows that exist: a continent entry ("cont:EU", only when
 * some row is in it) and the individual places (Nxeon node regions and the countries of third-party rows).
 */
export function regionOptions(rows: Pick<DirectoryRow, "region" | "regionLabel" | "regionCountry">[]): RegionOptions {
  const places = new Map<string, string>();
  const conts = new Set<Continent>();
  for (const r of rows) {
    if (r.region && r.regionLabel) places.set(r.region, r.regionLabel);
    const c = continentOf(r.regionCountry ?? r.region);
    if (c) conts.add(c);
  }
  return {
    continents: CONTINENT_ORDER.filter((c) => conts.has(c)).map((c): [string, string] => [`cont:${c}`, CONTINENT_LABELS[c]]),
    places: [...places.entries()].sort((a, b) => a[1].localeCompare(b[1])),
  };
}

export function filterRows<T extends DirectoryRow>(rows: T[], f: RowFilters): T[] {
  const needle = (f.q ?? "").trim().toLowerCase();
  return rows.filter((r) => {
    if (f.game && f.game !== "all" && r.family !== f.game) return false;
    if (f.region && f.region !== "all") {
      if (f.region.startsWith("cont:")) { if (continentOf(r.regionCountry ?? r.region) !== f.region.slice(5)) return false; }
      else if (r.region !== f.region) return false;
    }
    if (f.onlyLive && !(r.online !== null && r.online > 0)) return false;
    if (f.origin === "nxeon" && isExternalRow(r)) return false;
    if (f.origin === "external" && !isExternalRow(r)) return false;
    if (needle && !`${r.name} ${r.description ?? ""} ${r.motd ?? ""} ${r.address} ${r.gameLabel}`.toLowerCase().includes(needle)) return false;
    return true;
  });
}

/** Servers hosted on Nxeon first (community, then the rest), then external by players; stable by name. */
export function sortRows<T extends DirectoryRow>(rows: T[]): T[] {
  const rank = (r: T) => (r.community ? 0 : isExternalRow(r) ? 2 : 1);
  return [...rows].sort((a, b) => rank(a) - rank(b) || (b.online ?? -1) - (a.online ?? -1) || a.name.localeCompare(b.name));
}

/** "Checked 4 min ago" / "Listed 2 h ago" label for an external card. Never says "live" without our own check. */
export function liveLabel(r: Pick<DirectoryRow, "checkedAt" | "seenAt">, now = Date.now()): { kind: "checked" | "listed" | "none"; text: string } {
  const ago = (t: number) => {
    const m = Math.max(0, Math.round((now - t) / 60_000));
    return m < 1 ? "just now" : m < 60 ? `${m} min ago` : m < 2880 ? `${Math.round(m / 60)} h ago` : `${Math.round(m / 1440)} d ago`;
  };
  if (r.checkedAt) return { kind: "checked", text: `Checked ${ago(r.checkedAt)}` };
  if (r.seenAt) return { kind: "listed", text: `Seen on the list ${ago(r.seenAt)}` };
  return { kind: "none", text: "" };
}

import "server-only";
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getSetting, getSettingBool } from "@/lib/settings";
import { gameSubdomainBase } from "@/lib/game-subdomain-dns";
