/**
 * Database side of the public directory: builds `DirEntry[]` from every source
 * and applies the pure merge rules in lib/server-directory.ts. Each source is
 * read in its own try/catch so an un-migrated table (older staging DB) or a
 * failing source degrades to "none from there", never a broken page.
 *
 * PRIVACY: a paid listing carries the server's name, its owner-written text and
 * its play subdomain — never an owner, an internal id, a root password or a
 * node IP as a DISPLAYED value. (A node ip:port is used internally as a
 * dedupe key only, so a third-party list row for a server we host collapses
 * into our own entry; it is not rendered.)
 */

/** Paid servers that opted in, are running, and were not hidden by moderation. */
export const PAID_LISTING_WHERE: Prisma.ServerWhereInput = {
  publicListing: true,
  status: "RUNNING",
  gamePlan: { isNot: null },
  subdomain: { not: null },
  OR: [{ listingMeta: { is: null } }, { listingMeta: { is: { hidden: false } } }],
};

const safe = async <T,>(p: Promise<T>, fallback: T): Promise<T> => { try { return await p; } catch { return fallback; } };

async function paidEntries(): Promise<DirEntry[]> {
  const base = await gameSubdomainBase();
  const rows = await safe(db.server.findMany({
    where: PAID_LISTING_WHERE,
    select: {
      id: true, name: true, label: true, publicDescription: true, subdomain: true, createdAt: true,
      gamePlan: { select: { slots: true, gameFamily: true } },
      node: { select: { publicIp: true, region: true } },
      portForwards: { select: { publicPort: true } },
      listingMeta: { select: { tagline: true, imageUrl: true, websiteUrl: true, mediaApproved: true, featured: true } },
    },
    orderBy: { createdAt: "asc" },
  }), []);
  return rows.filter((s) => s.subdomain).map((s): DirEntry => {
    const m = s.listingMeta;
    const host = `${s.subdomain}.${base}`;
    const ip = s.node?.publicIp ? normalizeHost(s.node.publicIp) : null;
    return {
      key: `p-${s.id.slice(0, 8)}`, source: "nxeon-paid", nxeon: true,
      game: s.gamePlan?.gameFamily ?? "minecraft",
      name: s.label || s.name, tagline: m?.tagline ?? "", description: s.publicDescription ?? "",
      imageUrl: m?.mediaApproved && m.imageUrl ? m.imageUrl : null,
      address: host, host, port: null,
      alsoKeys: ip ? s.portForwards.map((f) => `${ip}:${f.publicPort}`) : [],
      players: null, maxPlayers: s.gamePlan?.slots ?? null,
      country: s.node?.region && REGION_COUNTRY[s.node.region] ? REGION_COUNTRY[s.node.region].toUpperCase() : null,
      region: s.node?.region ? customerRegionLabel(s.node.region) : null,
      featured: !!m?.featured, href: null,
      websiteUrl: m?.mediaApproved && m.websiteUrl ? m.websiteUrl : null,
      seenAt: null,
    };
  });
}

async function freeMcEntries(): Promise<DirEntry[]> {
  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const rows = await safe(db.freeMinecraftServer.findMany({
    where: { isPublic: true, status: "READY" }, orderBy: { createdAt: "asc" },
    select: { subdomain: true, name: true, activeGameType: true, publicTagline: true, publicDescription: true },
  }), []);
  return rows.map((s): DirEntry => {
    const preset = FREEMC_GAME_TYPES[s.activeGameType] ?? FREEMC_GAME_TYPES.vanilla;
    const host = `${s.subdomain}.${domain}`;
    return {
      key: `f-${s.subdomain}`, source: "nxeon-free", nxeon: true, game: "minecraft",
      name: s.name || s.subdomain, tagline: s.publicTagline ?? "", description: s.publicDescription || preset.description,
      imageUrl: null, address: host, host, port: null, alsoKeys: [],
      players: null, maxPlayers: null, country: null, region: null, featured: false,
      href: `/servers/${s.subdomain}`, websiteUrl: null, seenAt: null,
    };
  });
}

async function communityEntries(): Promise<DirEntry[]> {
  const rows = await listVisibleFreePublicServers();
  return Promise.all(rows.map(async (c): Promise<DirEntry> => {
    const l = await liveState(c, 1200);
    return {
      key: `c-${c.slug}`, source: "nxeon-community", nxeon: true, game: c.game,
      name: c.name, tagline: c.tagline ?? "", description: "Free, public and run by Nxeon. No account needed to join.",
      imageUrl: null, address: connectAddress(c), host: c.host, port: c.port, alsoKeys: [],
      players: l.state === "online" ? l.players : null, maxPlayers: c.maxPlayers,
      country: null, region: c.region ? customerRegionLabel(c.region) : null, featured: true,
      href: `/free-${c.game}-server`, websiteUrl: null, seenAt: l.state === "online" ? l.checkedAt : null,
    };
  }));
}

/** Drops external rows whose connection address shows another game host. Pure; `rules` null = no filtering. */
export function filterExternalRows<T extends { host: string; port: number; ptrName?: string | null }>(rows: T[], rules: RuleSet | null): T[] {
  if (!rules) return rows;
  return rows.filter((r) => !isRowBlocked({ host: r.host, port: r.port, ptrName: r.ptrName ?? null }, rules));
}

/**
 * Liveness filter for stored external rows. Pure. DEAD rows never show. With the prober ON a row must have
 * answered our own direct check in the last 24 h (nothing unverified is presented as live); with it OFF the
 * Steam list alone decides and the card says "seen on the list", never "checked".
 */
export function filterLiveRows<T extends { probeStatus: string; lastAliveAt: Date | null; lastSeenAt: Date }>(rows: T[], probeOn: boolean, now = Date.now()): T[] {
  return rows.filter((r) => isRowPublic(r, { probeOn, now }));
}

/** Most third-party rows one directory load returns, shared fairly between continents (see balanceByContinent). */
export const EXTERNAL_TOTAL = 1000;
/** Raw rows read per continent bucket before the blocklist/liveness filters (headroom so filtering still leaves a fair share). */
export const EXTERNAL_FETCH_PER_BUCKET = 400;

/** Players desc (unknown last), then name: the order the directory has always shown. Pure. */
export function byPlayersThenName<T extends { players: number | null; name: string }>(rows: T[]): T[] {
  return [...rows].sort((a, b) => (b.players ?? -1) - (a.players ?? -1) || a.name.localeCompare(b.name));
}

/** Region-balanced pick of external rows: best-first order is kept, but every continent present gets a fair share. Pure. */
export function pickBalancedExternal<T extends { players: number | null; name: string; country: string | null }>(rows: T[], total = EXTERNAL_TOTAL): T[] {
  return balanceByContinent(byPlayersThenName(rows), (r) => r.country, total);
}

async function externalEntries(game?: string): Promise<DirEntry[]> {
  if (!(await safe(getSettingBool("directory_external_show", false), false))) return [];
  const probeOn = await safe(getSettingBool("directory_probe_enabled", false), false);
  const base = { hidden: false, blockedReason: null, probeStatus: probeOn ? "ALIVE" : { not: "DEAD" }, lastSeenAt: { gte: new Date(Date.now() - 3 * 86_400_000) }, ...(game ? { game } : {}) } satisfies Prisma.ExternalServerWhereInput;
  const orderBy: Prisma.ExternalServerOrderByWithRelationInput[] = [{ players: { sort: "desc", nulls: "last" } }, { name: "asc" }];
  // One query per continent (by the stored ISO-2 country) plus one for rows with no/unknown country. A single
  // "top N by players" query is all one continent, because the Steam list answers nearest-to-us first.
  const known = CONTINENT_ORDER.flatMap((c) => countriesOf(c));
  const withBoth = (c: Continent) => countriesOf(c).flatMap((x) => [x, x.toLowerCase()]);
  const buckets: Prisma.ExternalServerWhereInput[] = [
    ...CONTINENT_ORDER.map((c) => ({ country: { in: withBoth(c) } })),
    { OR: [{ country: null }, { country: { notIn: known.flatMap((x) => [x, x.toLowerCase()]) } }] },
  ];
  const parts = await Promise.all(buckets.map((b) => safe(db.externalServer.findMany({
    where: { ...base, ...b }, orderBy, take: EXTERNAL_FETCH_PER_BUCKET,
  }), [])));
  const rawRows = parts.flat();
  // Competitor-host blocklist, re-run on every read against the CURRENT rules: a rule an admin just
  // added hides already-ingested rows at once, with no re-ingest. (blockedReason: null above is the
  // stored verdict; this is the live one. No network: PTR names were stored at ingest time.)
  const rules = await safe(loadRuleSet().then((r) => r.set), buildRuleSet().set); // default list still applies if settings can't be read
  const now = Date.now();
  const rows = pickBalancedExternal(filterLiveRows(filterExternalRows(rawRows, rules), probeOn, now));
  return rows.map((r): DirEntry => ({
    key: `x-${r.id.slice(0, 10)}`, source: "external", nxeon: false, game: r.game,
    name: r.name, tagline: "", description: r.description ?? (r.map ? `Map: ${r.map}` : ""),
    imageUrl: r.imageUrl, address: `${r.host}:${r.port}`, host: r.host, port: r.port,
    alsoKeys: r.ipKey ? [r.ipKey] : [],
    // A count is only shown as "playing now" while its newest source is under an hour old.
    players: liveCountsFresh(r, now) ? r.players : null, maxPlayers: r.maxPlayers, country: r.country, region: null, featured: false,
    href: null, websiteUrl: null, seenAt: r.lastSeenAt.getTime(),
    attribution: r.attribution ?? (r.source === "valve" ? "steam" : null), // "Checked" means OUR direct query answered; a listing source's heartbeat is not that, so those rows say "seen on the list".
    checkedAt: r.lastAliveAt && r.probeKind !== "listing" ? r.lastAliveAt.getTime() : null,
  }));
}

/** Every Nxeon-hosted entry (all games), before dedupe. Also used by the ingester to avoid re-listing our own servers. */
export async function nxeonEntries(): Promise<DirEntry[]> {
  const [paid, free, comm] = await Promise.all([paidEntries(), freeMcEntries(), communityEntries()]);
  return [...paid, ...free, ...comm];
}

/** The ip:port / host:port keys of everything Nxeon hosts (for ingest-time dedupe). */
export async function nxeonConnectionKeys(): Promise<Set<string>> {
  const out = new Set<string>();
  for (const e of await nxeonEntries()) {
    out.add(connKey(e.game, e.host, e.port));
    for (const k of e.alsoKeys) out.add(k);
  }
  return out;
}

/** Merged, deduplicated, ranked directory. `game` narrows to one family. */
export async function loadDirectory(opts: { game?: string } = {}): Promise<{ entries: DirEntry[]; dropped: number }> {
  const [nx, ext] = await Promise.all([nxeonEntries(), externalEntries(opts.game)]);
  const all = [...nx, ...ext].filter((e) => !opts.game || e.game === opts.game);
  const { entries, dropped } = dedupeEntries(all);
  return { entries: rankEntries(entries), dropped };
}
/**
 * Public server directory — PURE core (no db, no I/O; unit-tested).
 *
 * The directory merges four sources into one list of `DirEntry`:
 *   nxeon-paid       a customer's paid game server that opted in (Server.publicListing)
 *   nxeon-free       a free Minecraft server whose owner made it public
 *   nxeon-community  an Nxeon-run free public server (FreePublicServer)
 *   external         a public server found on a third-party list (ExternalServer,
 *                    ingested from the Steam master list when an admin enabled it)
 *
 * Rules this file owns (growth batch G6, seo-026 owner brief):
 *  1. NO DUPLICATES by connection detail. A connection is a domain or an IP
 *     with an optional port; a missing port means the game's default port, so
 *     `play.x.com`, `play.x.com:25565` and `PLAY.X.COM.` are one server, and so
 *     are `1.2.3.4` and `1.2.3.4:25565` for Minecraft. Entries also carry
 *     SECONDARY keys (an Nxeon server's real node ip:port) so a Valve-list row
 *     for a server we host collapses into our own entry. Two different ports on
 *     one IP are two servers (hosting companies run dozens per IP).
 *  2. Which duplicate survives: Nxeon-hosted beats external; then the one with
 *     an image; then the better-described one; then the most recently seen.
 *     Among external duplicates the survivor inherits a missing image /
 *     description from the losers ("pull whatever you can"); an Nxeon entry is
 *     never edited by third-party data.
 *  3. Entries WITH an image come first, then Nxeon-hosted, then busiest.
 *  4. Indexing (seo-025): a game page is only indexable when enough real,
 *     described, recently-seen servers back it; empty/new ones are noindex.
 */

export type DirSource = "nxeon-paid" | "nxeon-free" | "nxeon-community" | "external";

export type DirEntry = {
  /** Opaque, stable React/DOM key — never a database id. */
  key: string;
  source: DirSource;
  /** Hosted on Nxeon: gets the Nxeon badge. */
  nxeon: boolean;
  /** lib/games.ts GameFamily key. */
  game: string;
  name: string;
  tagline: string;
  description: string;
  /** An https image that is safe to render (owner-approved or first-party). Null otherwise. */
  imageUrl: string | null;
  /** What a player types to join (domain[:port] for Nxeon; ip:port is already public for external). */
  address: string;
  /** Primary dedupe address. */
  host: string;
  port: number | null;
  /** Secondary dedupe addresses (never displayed), e.g. the node ip:port behind a subdomain. */
  alsoKeys: string[];
  players: number | null;
  maxPlayers: number | null;
  country: string | null;
  region: string | null;
  featured: boolean;
  /** Internal page for this server, if it has one. */
  href: string | null;
  /** Owner-supplied website (approved only). Render rel="ugc nofollow noopener". */
  websiteUrl: string | null;
  /** ms epoch the live numbers/entry were last confirmed. */
  seenAt: number | null;
  /** Attribution this entry's data requires on any page that shows it ("steam" = Valve's terms; a provider key such as "vintagestory" or "truckersmp" otherwise). */
  attribution?: string | null;
  /** ms epoch Nxeon's own direct check last got an answer from the server (external rows only). */
  checkedAt?: number | null;
  /** Public detail-page id (lib/directory-ids.ts), when the entry has a directory detail page. */
  publicId?: string | null;
  /** Map name as the source reported it (third-party rows), shown as a chip, never as a sentence. */
  map?: string | null;
  /** ms epoch the directory first saw this server (third-party rows). */
  firstSeenAt?: number | null;
};

/** Default join port per game, so `host` and `host:default` are one connection. */
export const DEFAULT_PORT: Record<string, number> = {
  minecraft: 25565, bedrock: 19132, valheim: 2456, rust: 28015, cs2: 27015, tf2: 27015, gmod: 27015,
  l4d2: 27015, cs16: 27015, projectzomboid: 16261, terraria: 7777, ark: 7777, arkasa: 7777, palworld: 8211,
  corekeeper: 0, vrising: 9876, enshrouded: 15637, factorio: 34197, conan: 7777, unturned: 27015,
  sdtd: 26900, satisfactory: 7777, dayz: 2302, squad: 7787, mordhau: 7777,
};

const IPV4 = /^\d{1,3}(?:\.\d{1,3}){3}$/;
export const isIpv4 = (h: string) => IPV4.test(h) && h.split(".").every((n) => Number(n) <= 255);

/** Lowercase, trim, drop a trailing dot, drop IPv4 leading zeros. */
export function normalizeHost(raw: string): string {
  let h = String(raw ?? "").trim().toLowerCase().replace(/\.$/, "");
  if (isIpv4(h)) h = h.split(".").map((n) => String(Number(n))).join(".");
  return h;
}

/** Canonical dedupe key for a connection. `port` null/0 = the game's default. */
export function connKey(game: string, host: string, port: number | null | undefined): string {
  const h = normalizeHost(host);
  const p = port && port > 0 ? port : DEFAULT_PORT[game] ?? 0;
  return `${h}:${p}`;
}

/**
 * Parse a connection string a person or a source typed: `host`, `host:port`,
 * `ip:port`, optionally with a `scheme://` or trailing path. Returns null when
 * it is not a plausible host. IPv6 is not listed (not joinable in these games).
 */
export function parseConnection(raw: string): { host: string; port: number | null } | null {
  let s = String(raw ?? "").trim();
  if (!s || s.length > 255) return null;
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//i, "").replace(/[/?#].*$/, "");
  const m = /^([^:\s]+)(?::(\d{1,5}))?$/.exec(s);
  if (!m) return null;
  const host = normalizeHost(m[1]);
  const port = m[2] ? Number(m[2]) : null;
  if (port != null && (port < 1 || port > 65535)) return null;
  const domain = /^(?=.{3,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/.test(host);
  if (!domain && !isIpv4(host)) return null;
  return { host, port };
}

const imageScore = (e: DirEntry) => (e.imageUrl ? 1 : 0);
const richness = (e: DirEntry) => e.description.length + e.tagline.length;

/**
 * Directory source adapters (v2). A provider turns ONE public, permitted source into `ProviderCandidate`s;
 * everything shared (gates, rate limit, breaker, dedupe, blocklist, upsert, prune, liveness) is in
 * lib/directory-ingest/provider-run.ts and is the same for every source. Steam keeps its own proven path
 * (valve.ts / run.ts / sweep.ts) and is described in the registry only for attribution and docs.
 *
 * Every provider is default OFF (Setting `directory_src_<key>_enabled`) and, like Steam, cannot run until
 * somebody has recorded that they read the source's terms (`directory_src_<key>_reviewed_by`).
 */

/** How a row's liveness is checked. `listing` = the source's own heartbeat list is the evidence (no packets from us). */
export type ProbeKind = "a2s" | "slp" | "raknet" | "listing";

export type ProviderCandidate = {
  sourceKey: string;
  game: string;
  name: string;
  host: string;
  ip: string | null;
  port: number;
  queryPort: number | null;
  map: string | null;
  players: number | null;
  maxPlayers: number | null;
  version: string | null;
  tags: string[];
  country: string | null;
  connKey: string;
  ipKey: string | null;
  /** The source itself says this server is up right now (listing providers). null = unknown, probe decides. */
  alive: boolean | null;
};

export type ProviderAttribution = {
  /** Stored on ExternalServer.attribution and used to pick the footer block. */
  key: string;
  /** Plain sentence shown on every page that lists rows from this source (never claims endorsement). */
  text: string;
  url: string;
  linkLabel: string;
};

export type FetchContext = {
  fetchImpl?: typeof fetch;
  /** ETag from the previous successful run, sent as If-None-Match. */
  etag?: string | null;
};

export type FetchResult = { candidates: ProviderCandidate[]; notModified?: boolean; etag?: string | null; requests: number };

export type DirectoryProvider = {
  key: string;
  label: string;
  games: readonly string[];
  /** Minutes between refreshes (the source's own caching and politeness decide this, not our appetite). */
  intervalMin: number;
  /** Rows not listed by the source for this many days are removed. */
  pruneAfterDays: number;
  termsUrl: string;
  attribution: ProviderAttribution;
  /** Hard ceiling on our requests per UTC day to this source. */
  dailyCallCap: number;
  fetch(ctx: FetchContext): Promise<FetchResult>;
  probeKindFor(game: string): ProbeKind | null;
};

export class ProviderFetchError extends Error {
  constructor(message: string, readonly status?: number, readonly retryAfterSec?: number) { super(message); }
}

export const enableSettingFor = (key: string) => `directory_src_${key}_enabled`;
export const reviewedSettingFor = (key: string) => `directory_src_${key}_reviewed_by`;
import type { DirectoryProvider, ProviderAttribution } from "./types";
import { vintageStoryProvider } from "./vintagestory";
import { truckersMpProvider } from "./truckersmp";
import { attributionForKey } from "@/lib/directory-attribution";

/** Every non-Steam adapter. Adding a source = one file in this folder + one line here + a row in docs/DIRECTORY-SOURCES.md. */
export const PROVIDERS: readonly DirectoryProvider[] = [vintageStoryProvider, truckersMpProvider];

export const providerByKey = (key: string): DirectoryProvider | undefined => PROVIDERS.find((p) => p.key === key);

/** Attribution for any `ExternalServer.attribution` value (Steam's own block is richer: see steamAttributionHtml). */
export function attributionFor(key: string | null | undefined): ProviderAttribution | null {
  return attributionForKey(key) ?? providerByKey(key ?? "")?.attribution ?? null;
}

/** Liveness protocol per family (see probe-kind.ts). */
export { probeKindForGame } from "./probe-kind";

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

/** Footer block for a non-Steam source: its sentence plus a normal followed link to the source's site. */
export function providerAttributionHtml(key: string): string {
  const a = attributionFor(key);
  if (!a || key === "steam") return "";
  return `<aside class="dr-attrib" aria-label="${esc(a.linkLabel)} attribution" data-attrib="${esc(a.key)}"><p>${esc(a.text)} <a href="${esc(a.url)}" rel="noopener">${esc(a.linkLabel)}</a></p></aside>`;
}
import { cleanText, connKey, isIpv4, normalizeHost } from "@/lib/server-directory";
import { cleanServerName } from "../valve";
import { isPublicIpv4, isProbeablePort } from "@/lib/directory-liveness";
import { politeGetJson } from "./http";
import { VINTAGESTORY_ATTRIBUTION } from "@/lib/directory-attribution";
import type { DirectoryProvider, FetchContext, FetchResult, ProviderCandidate } from "./types";

/**
 * Vintage Story official master list: the same JSON the game client calls (servers opt in with
 * `AdvertiseServer` in their config). No key, no login, robots.txt is empty. The wiki documents the setting but
 * not the endpoint or any terms, so the source is AMBER: default OFF, and the owner records who asked the
 * developers / read their position before turning it on (docs/DIRECTORY-SOURCES.md).
 *
 * Verified live 2026-10-04: HTTP 200, ~4.5 MB, ~2,460 rows, `Cache-Control: max-age=300`, ETag. Fields:
 * serverName, serverIP "ip:port" | "host:port" | "[v6]:port", playstyle{id}, mods[], maxPlayers (string), players,
 * gameVersion, hasPassword, whitelisted, gameDescription. We poll once per 30 minutes with If-None-Match.
 *
 * Only servers anyone can join are listed: password-protected and whitelisted rows are dropped (about 70% of the
 * list), so the directory never advertises a server a visitor cannot enter. Mod ids and descriptions are not stored.
 */
export const VINTAGESTORY_URL = "https://masterserver.vintagestory.at/api/v1/servers/list";

export type VsRaw = {
  serverName?: unknown; serverIP?: unknown; playstyle?: { id?: unknown } | null; maxPlayers?: unknown; players?: unknown;
  gameVersion?: unknown; hasPassword?: unknown; whitelisted?: unknown;
};

const toInt = (v: unknown): number | null => {
  const n = typeof v === "string" ? Number(v.trim()) : typeof v === "number" ? v : NaN;
  return Number.isFinite(n) && n >= 0 && n <= 1_000_000 ? Math.floor(n) : null;
};

/** "ip:port" | "host.name:port". IPv6 literals are skipped (our probes and dedupe are IPv4/hostname only). */
export function parseVsAddress(raw: unknown): { host: string; ip: string | null; port: number } | null {
  const m = /^([A-Za-z0-9.-]{1,253}):(\d{1,5})$/.exec(String(raw ?? "").trim());
  if (!m) return null;
  const host = normalizeHost(m[1]);
  const port = Number(m[2]);
  if (!(port >= 1 && port <= 65535) || !isProbeablePort(port)) return null;
  if (isIpv4(host)) return isPublicIpv4(host) ? { host, ip: host, port } : null;
  if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(host) || /^(localhost|.*\.local|.*\.internal)$/.test(host)) return null;
  return { host, ip: null, port };
}

export function parseVsRow(r: VsRaw): ProviderCandidate | null {
  if (r.hasPassword !== false || r.whitelisted !== false) return null; // only open servers
  const addr = parseVsAddress(r.serverIP);
  if (!addr) return null;
  const name = cleanServerName(r.serverName);
  if (!name) return null;
  const max = toInt(r.maxPlayers), players = toInt(r.players);
  if (max !== null && players !== null && (max === 0 || players > max || max > 1000)) return null; // spoofed or implausible counts
  const style = cleanText(r.playstyle?.id, 24);
  const key = connKey("vintagestory", addr.host, addr.port);
  return {
    sourceKey: `${addr.host}:${addr.port}`, game: "vintagestory", name, host: addr.host, ip: addr.ip, port: addr.port, queryPort: null,
    map: null, players, maxPlayers: max, version: cleanText(r.gameVersion, 24), tags: style ? [style] : [], country: null,
    connKey: key, ipKey: addr.ip ? key : null, alive: true, // listed on the master = it heartbeated recently
  };
}

export function parseVsResponse(json: unknown): ProviderCandidate[] {
  const rows = (json as { data?: VsRaw[] } | null)?.data;
  if (!Array.isArray(rows)) return [];
  const seen = new Set<string>();
  const out: ProviderCandidate[] = [];
  for (const r of rows) {
    const c = parseVsRow(r);
    if (!c || seen.has(c.sourceKey)) continue;
    seen.add(c.sourceKey);
    out.push(c);
  }
  return out;
}

export const vintageStoryProvider: DirectoryProvider = {
  key: "vintagestory", label: "Vintage Story master list", games: ["vintagestory"],
  intervalMin: 30, pruneAfterDays: 1, dailyCallCap: 96,
  termsUrl: "https://wiki.vintagestory.at/Server_Config",
  attribution: VINTAGESTORY_ATTRIBUTION,
  probeKindFor: () => "listing",
  async fetch(ctx: FetchContext): Promise<FetchResult> {
