import { ProviderFetchError } from "./types";

/**
 * One polite JSON GET. An honest User-Agent that says who we are and how to reach us, a timeout, a body-size
 * ceiling (never buffer an unbounded answer), ETag revalidation so an unchanged list costs a 304, and a
 * ProviderFetchError carrying the HTTP status and Retry-After so the shared breaker can react. It never
 * retries by itself: retry/backoff is the scheduler's job (a failure backs the whole source off).
 */
export const DIRECTORY_UA = "NxeonDirectory/2.0 (+https://nxeon.cloud/game-servers/directory; abuse@nxeon.cloud)";

export async function politeGetJson(url: string, opts: { fetchImpl?: typeof fetch; etag?: string | null; timeoutMs?: number; maxBytes?: number } = {}): Promise<{ json: unknown; etag: string | null; notModified: boolean }> {
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), opts.timeoutMs ?? 60_000);
  try {
    const headers: Record<string, string> = { accept: "application/json", "user-agent": DIRECTORY_UA };
    if (opts.etag) headers["if-none-match"] = opts.etag;
    const res = await (opts.fetchImpl ?? fetch)(url, { signal: ctl.signal, headers });
    if (res.status === 304) return { json: null, etag: opts.etag ?? null, notModified: true };
    if (!res.ok) {
      const ra = Number(res.headers?.get?.("retry-after"));
      throw new ProviderFetchError(`answered HTTP ${res.status}`, res.status, Number.isFinite(ra) && ra > 0 ? ra : undefined);
    }
    const text = await res.text();
    if (text.length > (opts.maxBytes ?? 25_000_000)) throw new ProviderFetchError("answer too large");
    let json: unknown;
    try { json = JSON.parse(text); } catch { throw new ProviderFetchError("answer was not JSON"); }
    return { json, etag: res.headers?.get?.("etag") ?? null, notModified: false };
  } catch (e) {
    if (e instanceof ProviderFetchError) throw e;
    throw new ProviderFetchError(e instanceof Error && e.name === "AbortError" ? "request timed out" : "request failed");
  } finally {
    clearTimeout(t);
  }
}
import { QUERY_PROTOCOL } from "@/lib/server-query";
import type { GameFamily } from "@/lib/games";
import type { ProbeKind } from "./types";

/**
 * The right liveness protocol per game family, for rows whose address we were given.
 *   a2s     Valve's A2S_INFO on the query port (every Source / Steam-networking dedicated server)
 *   slp     Minecraft Java Server List Ping (TCP)
 *   raknet  Minecraft Bedrock unconnected ping (UDP)
 *   listing the source's own heartbeat list is the evidence (TruckersMP, Vintage Story master)
 * null = no honest check exists: such a row is shown "seen on the list" with a short TTL, never "online".
 */
export function probeKindForGame(game: string): ProbeKind | null {
  if (game === "ets2" || game === "ats") return "listing";
  if (game === "vintagestory") return "listing";
  const p = QUERY_PROTOCOL[game as GameFamily];
  if (p === "mc-java") return "slp";
  if (p === "bedrock") return "raknet";
  if (p === "a2s") return "a2s";
  return null;
}
import { judgeCandidates, splitDuplicates, type PtrCache } from "./run";
import { isSuspiciousShrink } from "./schedule";
import { countryFromIp } from "@/lib/geo-ip";
import type { RuleSet } from "@/lib/directory-blocklist";
import type { ReverseFn } from "./ptr";
import type { DirectoryProvider, ProviderCandidate } from "./providers/types";

/**
 * The shared, PURE half of a provider run: candidates in, a write plan out. No database, no network (reverse DNS
 * is injected), so it is unit-tested with fakes (test/directory-providers.test.ts). provider-run.ts executes the plan.
 *
 * Order of rules, the same for every source:
 *   1. drop anything colliding with a server Nxeon hosts, or already held by ANOTHER source (the directory
 *      shows one row per connection; Steam's A2S-verified row wins over a later listing)
 *   2. competitor-host blocklist (rows are stored with a verdict, never silently lost)
 *   3. country from the local geoip database when the source gives none (no network)
 *   4. a list that shrank sharply against what we hold is "suspicious": refresh, prune nothing
 */
export type ExistingRow = { id: string; sourceKey: string; host: string; ptrName: string | null; ptrCheckedAt: Date | null; lastSeenAt: Date };

export type PlannedWrite = { create: boolean; sourceKey: string; data: Record<string, unknown> };

export type ProviderPlan = {
  writes: PlannedWrite[];
  duplicates: number;
  blocked: number;
  suspicious: boolean;
  /** Delete rows of this source not seen since this instant (null = prune nothing this run). */
  pruneBefore: Date | null;
  /** Delete rows of this source whose connection now collides with a server Nxeon hosts. */
  dropKeys: string[];
};

export async function buildProviderPlan(i: {
  provider: DirectoryProvider; candidates: ProviderCandidate[]; existing: ExistingRow[];
  nxeonKeys: Set<string>; otherSourceKeys: Set<string>; rules: RuleSet; now: Date; reverse?: ReverseFn;
}): Promise<ProviderPlan> {
  const { provider, now } = i;
  const taken = new Set([...i.nxeonKeys, ...i.otherSourceKeys]);
  const { keep, dup } = splitDuplicates(i.candidates, taken);
  const cache: PtrCache = new Map(i.existing.map((r) => [r.host, { ptrName: r.ptrName, checkedAt: r.ptrCheckedAt }]));
  const judged = await judgeCandidates(keep, i.rules, cache, { reverse: i.reverse, now });
  const existing = new Set(i.existing.map((r) => r.sourceKey));
  const writes: PlannedWrite[] = judged.map(({ cand: c, ptrName, ptrCheckedAt, blockedReason, blockedRule }) => {
    const alive = c.alive === true;
    const data: Record<string, unknown> = {
      blockedReason, blockedRule, ptrName, ptrCheckedAt, source: provider.key, attribution: provider.attribution.key,
      probeKind: provider.probeKindFor(c.game),
      game: c.game, name: c.name, host: c.host, ip: c.ip, port: c.port, queryPort: c.queryPort, map: c.map,
      country: c.country ?? (c.ip ? countryFromIp(c.ip) : null),
      players: c.players, maxPlayers: c.maxPlayers, version: c.version, tags: c.tags,
      connKey: c.connKey, ipKey: c.ipKey, lastSeenAt: now,
    };
    // A listing source's own heartbeat is the liveness evidence: listed + up = ALIVE now; listed + down = DEAD (hidden).
    if (provider.probeKindFor(c.game) === "listing") {
      Object.assign(data, alive ? { probeStatus: "ALIVE", lastAliveAt: now, consecutiveFails: 0 } : { probeStatus: "DEAD" });
    }
    return { create: !existing.has(c.sourceKey), sourceKey: c.sourceKey, data };
  });
  const previous = i.existing.filter((r) => now.getTime() - r.lastSeenAt.getTime() < 86_400_000).length;
  const suspicious = isSuspiciousShrink(previous, keep.length);
  return {
    writes, duplicates: dup, blocked: judged.filter((j) => j.blockedReason).length, suspicious,
    pruneBefore: suspicious ? null : new Date(now.getTime() - provider.pruneAfterDays * 86_400_000),
    dropKeys: [...i.nxeonKeys],
  };
}
import { db } from "@/lib/db";
import { getSettingBool, getSetting, setSetting } from "@/lib/settings";
import { nxeonConnectionKeys } from "@/lib/server-directory-data";
import { loadRuleSet } from "@/lib/directory-blocklist-db";
import { ensureSource, redactKey } from "./sweep";
import { backoffMs, breakerDecision, callsRemaining, dayKey } from "./schedule";
import { buildProviderPlan, type ProviderPlan } from "./provider-plan";
import { PROVIDERS } from "./providers/registry";
import { enableSettingFor, reviewedSettingFor, ProviderFetchError, type DirectoryProvider } from "./providers/types";
import type { ReverseFn } from "./ptr";

/**
 * The scheduled run for the non-Steam sources (worker/directory.ts calls `directoryProviderTick` every few
 * minutes). Per source, in a pinned order (providerGate), it decides whether it may run; then makes the
 * source's ONE request (its own interval, daily cap, If-None-Match), turns the answer into a plan
 * (provider-plan.ts) and writes it. Failures back off exponentially, repeated failures open a six hour breaker,
 * and a 401/403 opens it AND switches that source off. State lives in DirectorySource(<key>), so restarts resume.
 */
const CLAIM_MS = 10 * 60_000;

export type ProviderSkip = "kill-switch" | "disabled" | "not-reviewed" | "circuit-open" | "backoff" | "budget" | "running" | "not-due";

/** The order in which a provider decides not to run. Pure, so the order is pinned by tests. */
export function providerGate(i: {
  envKill: boolean; ingestOn: boolean; enabled: boolean; reviewedBy: string;
  circuitOpenUntil: Date | null; nextAttemptAt: Date | null; runningUntil: Date | null; lastOkAt: Date | null; lastRunAt: Date | null;
  remainingCalls: number; intervalMin: number; runRequested: boolean; now: number;
}): ProviderSkip | null {
  if (i.envKill) return "kill-switch";
  if (!i.ingestOn || !i.enabled) return "disabled";
  if (!i.reviewedBy.trim()) return "not-reviewed";
  if (i.runningUntil && i.runningUntil.getTime() > i.now) return "running";
  if (i.circuitOpenUntil && i.circuitOpenUntil.getTime() > i.now) return "circuit-open";
  if (i.nextAttemptAt && i.nextAttemptAt.getTime() > i.now) return "backoff";
  if (i.remainingCalls <= 0) return "budget";
  const last = Math.max(i.lastOkAt?.getTime() ?? 0, 0);
  if (!i.runRequested && last && i.now - last < i.intervalMin * 60_000) return "not-due";
  return null;
}

export type ProviderRunResult = { key: string; fetched: number; inserted: number; updated: number; duplicates: number; pruned: number; blocked: number; suspicious: boolean; notModified: boolean };

async function applyPlan(provider: DirectoryProvider, plan: ProviderPlan, now: Date): Promise<{ inserted: number; updated: number; pruned: number }> {
  let inserted = 0, updated = 0;
  for (let i = 0; i < plan.writes.length; i += 100) {
    await db.$transaction(plan.writes.slice(i, i + 100).map((w) => {
      if (w.create) inserted++; else updated++;
      const { source: _s, ...update } = w.data;
      return db.externalServer.upsert({
        where: { source_sourceKey: { source: provider.key, sourceKey: w.sourceKey } },
        create: { sourceKey: w.sourceKey, ...(w.data as object) } as never, update: update as never,
      });
    }));
  }
  const gone = await db.externalServer.deleteMany({
    where: {
      source: provider.key,
      OR: [...(plan.pruneBefore ? [{ lastSeenAt: { lt: plan.pruneBefore } }] : []), ...(plan.dropKeys.length ? [{ connKey: { in: plan.dropKeys } }] : [])],
    },
  });
  void now;
  return { inserted, updated, pruned: gone.count };
}

/** One fetch + write for one provider. Throws on a failed fetch; the caller owns breaker/backoff bookkeeping. */
export async function runProvider(provider: DirectoryProvider, opts: { etag?: string | null; fetchImpl?: typeof fetch; reverse?: ReverseFn; trigger?: "worker" | "admin" | "cli"; now?: Date } = {}): Promise<ProviderRunResult & { etag: string | null; requests: number }> {
  const now = opts.now ?? new Date();
  const run = await db.directoryIngestRun.create({ data: { source: provider.key, game: provider.games.join(","), trigger: opts.trigger ?? "worker", status: "error" } });
  try {
    const r = await provider.fetch({ fetchImpl: opts.fetchImpl, etag: opts.etag });
    if (r.notModified) {
      // Unchanged list: keep the rows we hold alive (their listing is still current) without re-writing them.
      await db.externalServer.updateMany({ where: { source: provider.key }, data: { lastSeenAt: now } });
      await db.directoryIngestRun.update({ where: { id: run.id }, data: { finishedAt: new Date(), status: "ok", note: "not modified (304)", error: null } });
      return { key: provider.key, fetched: 0, inserted: 0, updated: 0, duplicates: 0, pruned: 0, blocked: 0, suspicious: false, notModified: true, etag: r.etag ?? opts.etag ?? null, requests: r.requests };
    }
    const [nxeonKeys, existing, others] = await Promise.all([
      nxeonConnectionKeys(),
      db.externalServer.findMany({ where: { source: provider.key }, select: { id: true, sourceKey: true, host: true, ptrName: true, ptrCheckedAt: true, lastSeenAt: true } }),
      db.externalServer.findMany({ where: { source: { not: provider.key } }, select: { connKey: true, ipKey: true } }),
    ]);
    const otherSourceKeys = new Set(others.flatMap((o) => [o.connKey, ...(o.ipKey ? [o.ipKey] : [])]));
    const { set } = await loadRuleSet();
    const plan = await buildProviderPlan({ provider, candidates: r.candidates, existing, nxeonKeys, otherSourceKeys, rules: set, now, reverse: opts.reverse });
    const w = await applyPlan(provider, plan, now);
    await db.directoryIngestRun.update({
      where: { id: run.id },
      data: {
        finishedAt: new Date(), fetched: r.candidates.length, inserted: w.inserted, updated: w.updated, duplicates: plan.duplicates, pruned: w.pruned, blocked: plan.blocked,
        status: plan.suspicious ? "suspicious" : "ok",
        note: plan.suspicious ? "List shrank sharply: kept old rows, pruned nothing." : null, error: null,
      },
    });
    return { key: provider.key, fetched: r.candidates.length, inserted: w.inserted, updated: w.updated, duplicates: plan.duplicates, pruned: w.pruned, blocked: plan.blocked, suspicious: plan.suspicious, notModified: false, etag: r.etag ?? null, requests: r.requests };
  } catch (e) {
    const msg = e instanceof Error ? e.message : "ingest failed";
    await db.directoryIngestRun.update({ where: { id: run.id }, data: { finishedAt: new Date(), status: "error", error: redactKey(msg, undefined) } }).catch(() => {});
    throw e;
  }
}

export type ProviderTickReport = { key: string; skipped?: ProviderSkip; result?: ProviderRunResult; error?: string; disabled?: boolean };

export async function directoryProviderTick(opts: { now?: number; fetchImpl?: typeof fetch; envKill?: boolean; providers?: readonly DirectoryProvider[]; reverse?: ReverseFn } = {}): Promise<ProviderTickReport[]> {
  const now = opts.now ?? Date.now();
  const envKill = opts.envKill ?? process.env.DIRECTORY_SWEEP_DISABLED === "1";
  const ingestOn = await getSettingBool("directory_ingest_enabled", false);
  const out: ProviderTickReport[] = [];
  for (const p of opts.providers ?? PROVIDERS) {
    // Cheap exits first: a source that is switched off costs no database writes at all.
    const enabled = await getSettingBool(enableSettingFor(p.key), false);
    if (!enabled || envKill || !ingestOn) { out.push({ key: p.key, skipped: envKill ? "kill-switch" : "disabled" }); continue; }
    const reviewedBy = await getSetting(reviewedSettingFor(p.key), "");
    const src = await ensureSource(p.key);
    const skip = providerGate({
      envKill, ingestOn, enabled, reviewedBy, circuitOpenUntil: src.circuitOpenUntil, nextAttemptAt: src.nextAttemptAt, runningUntil: src.runningUntil,
      lastOkAt: src.lastOkAt, lastRunAt: src.lastRunAt, remainingCalls: callsRemaining(src, now, p.dailyCallCap), intervalMin: p.intervalMin, runRequested: src.runRequested, now,
    });
    if (skip) { out.push({ key: p.key, skipped: skip }); continue; }
    const claimed = await db.directorySource.updateMany({
      where: { key: p.key, OR: [{ runningUntil: null }, { runningUntil: { lt: new Date(now) } }] },
      data: { runningUntil: new Date(now + CLAIM_MS) },
    });
    if (!claimed.count) { out.push({ key: p.key, skipped: "running" }); continue; }
    const prevStats = (src.stats ?? {}) as { etag?: string | null };
    let errors = src.consecutiveErrors, lastOkAt = src.lastOkAt, lastError = src.lastError, lastErrorAt = src.lastErrorAt;
    let circuit: Date | null = null, next: Date | null = null, etag = prevStats.etag ?? null;
    const callsDay = dayKey(now);
    const callsToday = (src.callsDay === callsDay ? src.callsToday : 0) + 1; // counted BEFORE the call
    const rep: ProviderTickReport = { key: p.key };
    try {
      const r = await runProvider(p, { etag, fetchImpl: opts.fetchImpl, reverse: opts.reverse, trigger: src.runRequested ? "admin" : "worker", now: new Date(now) });
      etag = r.etag; errors = 0; lastOkAt = new Date(now); lastError = null; lastErrorAt = null;
      rep.result = r;
    } catch (e) {
      const status = e instanceof ProviderFetchError ? e.status : undefined;
      const msg = redactKey(e instanceof Error ? e.message : "fetch failed", undefined);
      errors += 1; lastError = msg; lastErrorAt = new Date(now); rep.error = msg;
      const b = breakerDecision(errors, status);
      next = new Date(now + backoffMs(errors, e instanceof ProviderFetchError ? e.retryAfterSec : undefined));
      if (b.open) circuit = new Date(now + b.openMs);
      if (b.disable) { await setSetting(enableSettingFor(p.key), "false"); rep.disabled = true; console.error(`[directory] ${p.key} answered HTTP ${status}: source switched OFF. Read ${p.termsUrl} before turning it back on.`); }
    } finally {
      await db.directorySource.update({
        where: { key: p.key },
        data: {
          runningUntil: null, runRequested: false, lastRunAt: new Date(now), lastOkAt, lastError, lastErrorAt, consecutiveErrors: errors,
          circuitOpenUntil: circuit ?? (errors === 0 ? null : src.circuitOpenUntil), nextAttemptAt: next, callsDay, callsToday,
          stats: { etag, fetched: rep.result?.fetched ?? null, notModified: rep.result?.notModified ?? false, inserted: rep.result?.inserted ?? null, blocked: rep.result?.blocked ?? null },
        },
      });
    }
    out.push(rep);
  }
  return out;
}
/**
 * Source attribution for the public server directory. PURE DATA, no Node imports, so client components
 * (components/nx/DirectoryView.tsx via lib/directory-portal.ts) can use it without pulling server-only
 * code into the browser bundle. The Steam module and each provider adapter import their text from here,
