import { mcJavaPing, bedrockPing, type LiveStatus } from "@/lib/server-query";
import type { ProbeOutcome } from "@/lib/directory-liveness";
import type { ProbeKind } from "./providers/types";

/**
 * One liveness check, protocol chosen per row (probe-kind.ts). A2S for Source / Steam-networking servers, Server List
 * Ping for Minecraft Java, RakNet unconnected ping for Bedrock: each is the game's own public status request, sent
 * once per due row. Player NAMES are never requested or read (Minecraft's SLP `sample` is ignored; server-query's
 * parser does not return it). Pingers are injectable so tests never touch the network.
 */
export type Pinger = (host: string, port: number) => Promise<LiveStatus | null>;

export async function probeByKind(
  kind: ProbeKind | null, target: { ip: string; port: number; game: string },
  deps: { transport?: A2sTransport; slp?: Pinger; raknet?: Pinger; now?: () => number } = {},
): Promise<ProbeOutcome> {
  const now = deps.now ?? (() => Date.now());
  if (kind === null || kind === "a2s") {
    const r = await probeA2s(target, { transport: deps.transport, now });
    return r.alive ? { alive: true, rttMs: r.rttMs, players: r.players, maxPlayers: r.maxPlayers, viaSplit: r.viaSplit } : { alive: false, reason: r.reason };
  }
  if (kind === "slp" || kind === "raknet") {
    const ping = kind === "slp" ? (deps.slp ?? mcJavaPing) : (deps.raknet ?? bedrockPing);
    const t0 = now();
    let s: LiveStatus | null = null;
    try { s = await ping(target.ip, target.port); } catch { s = null; }
    if (!s) return { alive: false, reason: "timeout" };
    const max = s.max ?? 0;
    if ((max > 0 && s.online > max) || max > 10_000_000) return { alive: false, reason: "implausible" };
    return { alive: true, rttMs: Math.max(0, now() - t0), players: s.online, maxPlayers: max, viaSplit: max <= 0 };
  }
  return { alive: false, reason: "no-probe" }; // "listing": the source's heartbeat is the evidence, we send nothing
}

