 *
 * WHY THIS EXISTS. The directory needs a live player count, and the only source
 * we had was `PlayerSession`, written by worker/game-control.ts's RCON sweep —
 * which covers three families out of forty-six, because everything else has
 * `rcon: "none"`. A directory that says "0 players" for forty-three games isn't
 * a directory. These are the protocols a server answers to ANYONE, with no
 * credentials, which is exactly what a public listing needs.
 *
 * WHICH GAMES CAN BE LISTED — the question this module answers concretely:
 *
 *   mc-java   Minecraft Java's Server List Ping. A TCP handshake plus a status
 *             request; the reply is the same JSON a vanilla client shows in its
 *             server list. Unauthenticated by design.
 *   bedrock   Minecraft Bedrock's RakNet "unconnected ping". One UDP datagram,
 *             and the reply is a semicolon-delimited MOTD string carrying the
 *             player counts.
 *   a2s       Valve's A2S_INFO. One UDP datagram to the game's query port. Since
 *             2020 the server usually replies with a challenge first and the
 *             query has to be re-sent with it — handled below. Every Source
 *             engine title speaks it, and so does every Steam-networking
 *             dedicated server, which is most of the survival catalogue.
 *   null      No public query protocol exists, or none we have evidence for.
 *             Those servers list with their slot count and no live figure.
 *
 * The A2S entries are the interesting ones. Three of them are proven on our own
 * running servers — Garry's Mod, 7 Days to Die and Enshrouded each answered a
 * real A2S_INFO datagram with `ff ff ff ff 41` (S2C_CHALLENGE) during the port
 * audits documented in lib/games.ts's GAME_JOIN_PORT_OVERRIDE. The rest are
 * marked from what engine the server runs. That inference can be wrong, and the
 * cost of being wrong is deliberately nil: a probe that gets no answer yields
 * null and the row shows no live count. It can never display a made-up number.
 *
 * THE PORT is `joinPortFor()` — the port a player's own client connects on, not
 * GAME_PORT, which is a health-check map that points at RCON for eight
 * families. Getting this wrong is the exact bug that shipped RCON ports to
 * customers as connect addresses; the comment on GAME_JOIN_PORT_OVERRIDE tells
 * that story. For the Source lineage the query and game ports are the same
 * number, which is why one port is enough here.
 */

export type QueryProtocol = "mc-java" | "bedrock" | "a2s";

export type LiveStatus = {
  online: number;
  max: number | null;
  /** The server's own MOTD/name, when the protocol carries one. */
  motd: string | null;
  /** Current map, where the protocol reports it. */
  map: string | null;
};

/** Per family: the protocol a stranger can query it with, or null for none. */
export const QUERY_PROTOCOL: Partial<Record<GameFamily, QueryProtocol>> = {
  // Minecraft's two editions, each with its own protocol.
  minecraft: "mc-java",
  bedrock: "bedrock",

  // Source engine — A2S is native, and proven on our own Garry's Mod server.
  cs2: "a2s",
  gmod: "a2s",
  tf2: "a2s",
  l4d2: "a2s",

  // Steam-networking dedicated servers. Each of these registers with Steam's
  // master server list, which requires answering A2S_INFO.
  ark: "a2s",
  arkasa: "a2s",
  rust: "a2s",
  valheim: "a2s",
  vrising: "a2s",
  projectzomboid: "a2s",
  conan: "a2s",
  unturned: "a2s",
  theforest: "a2s",
  sonsoftheforest: "a2s",
  sdtd: "a2s",          // proven live — see the module comment
  enshrouded: "a2s",    // proven live — its queryPort IS its only port
  palworld: "a2s",
  soulmask: "a2s",
  sunkenland: "a2s",
  abioticfactor: "a2s",
  corekeeper: "a2s",
  icarus: "a2s",
  squad: "a2s",
  kf2: "a2s",
  sandstorm: "a2s",
  mordhau: "a2s",
  eco: "a2s",
  barotrauma: "a2s",

  /* Deliberately absent, because no public query protocol exists for them:
     terraria (vanilla and tModLoader expose nothing to a stranger), factorio
     (its multiplayer browser goes through Wube's own matchmaking service, not a
     direct server query), satisfactory (its server API is HTTPS with a bearer
     token), dst, vintagestory, necesse, spaceengineers, empyrion, theisle,
     stationeers, nightingale, dragonwilds, schedule1 and the Plutonium
     families. Those list with their slot count and no live figure — which is
     the honest answer, not a zero. */
};

/** Can a directory show a live count for this game at all? */
export function canQuery(family: string): boolean {
  return QUERY_PROTOCOL[family as GameFamily] !== undefined;
}

/* ── transport helpers ────────────────────────────────────────────────────
   Every probe is bounded and every socket is closed on both paths. A directory
   page waits on these, so a server that accepts a connection and then says
   nothing must not hold the page open. */

const TIMEOUT_MS = 1800;

function udpQuery(host: string, port: number, payloads: Buffer[], onReply: (b: Buffer, send: (p: Buffer) => void) => LiveStatus | null): Promise<LiveStatus | null> {
  return new Promise((resolve) => {
    const sock = dgram.createSocket("udp4");
    let settled = false;
    const done = (v: LiveStatus | null) => {
      if (settled) return;
      settled = true;
      try { sock.close(); } catch { /* already closed */ }
      resolve(v);
    };
    const timer = setTimeout(() => done(null), TIMEOUT_MS);
    timer.unref?.();

    const send = (p: Buffer) => sock.send(p, port, host, (e) => { if (e) done(null); });

    sock.on("error", () => done(null));
    sock.on("message", (msg) => {
      try {
        const out = onReply(msg, send);
        if (out) { clearTimeout(timer); done(out); }
        // A null return means "that was a challenge, I've re-sent" — keep waiting.
      } catch {

      } catch {
        done(null);
      }
    });
    for (const p of payloads) send(p);
  });
}

/* ── Minecraft Java: Server List Ping ─────────────────────────────────── */

function varInt(n: number): Buffer {
  const out: number[] = [];
  let v = n;
  do {
    let b = v & 0x7f;
    v >>>= 7;
    if (v !== 0) b |= 0x80;
    out.push(b);
  } while (v !== 0);
  return Buffer.from(out);
}

function readVarInt(buf: Buffer, at: number): { value: number; size: number } | null {
  let value = 0;
  let size = 0;
  for (;;) {
    if (at + size >= buf.length) return null;
    const b = buf[at + size];
    value |= (b & 0x7f) << (7 * size);
    size++;
    if ((b & 0x80) === 0) return { value, size };
    if (size > 5) return null;
  }
}

function packet(id: number, body: Buffer): Buffer {
  const payload = Buffer.concat([varInt(id), body]);
  return Buffer.concat([varInt(payload.length), payload]);
}

export function mcJavaPing(host: string, port: number): Promise<LiveStatus | null> {
  return new Promise((resolve) => {
    const sock = net.createConnection({ host, port });
    let settled = false;
    let chunks = Buffer.alloc(0);
    const done = (v: LiveStatus | null) => {
      if (settled) return;
      settled = true;
      sock.destroy();
      resolve(v);
    };
    sock.setTimeout(TIMEOUT_MS);
    sock.on("timeout", () => done(null));
    sock.on("error", () => done(null));

    sock.on("connect", () => {
      const hostBuf = Buffer.from(host, "utf8");
      const handshake = Buffer.concat([
        // Protocol version. Any value is accepted for a STATUS handshake — the
        // server answers the ping regardless of whether it would let that
        // version actually log in — so this is pinned rather than negotiated.
        varInt(47),
        varInt(hostBuf.length), hostBuf,
        Buffer.from([(port >> 8) & 0xff, port & 0xff]),
        varInt(1),                                // next state: status
      ]);
      sock.write(packet(0x00, handshake));
      sock.write(packet(0x00, Buffer.alloc(0)));  // status request
    });

    sock.on("data", (d) => {
      chunks = Buffer.concat([chunks, d]);
      const len = readVarInt(chunks, 0);
      if (!len) return;
      if (chunks.length < len.size + len.value) return;  // still arriving

      let at = len.size;
      const id = readVarInt(chunks, at);
      if (!id || id.value !== 0x00) return done(null);
      at += id.size;
      const strLen = readVarInt(chunks, at);
      if (!strLen) return done(null);
      at += strLen.size;

      try {
        const json = JSON.parse(chunks.subarray(at, at + strLen.value).toString("utf8")) as {
          players?: { online?: number; max?: number };
          description?: unknown;
        };
        done({
          online: json.players?.online ?? 0,
          max: json.players?.max ?? null,
          motd: flattenMotd(json.description),
          map: null,
        });
      } catch {
        done(null);
      }
    });
  });
}

/** A Java MOTD is a string, or a nested chat component. Flatten either. */
function flattenMotd(d: unknown): string | null {
  if (typeof d === "string") return d.replace(/§./g, "").trim() || null;
  if (d && typeof d === "object") {
    const o = d as { text?: string; extra?: unknown[] };
    const parts = [o.text ?? "", ...(o.extra ?? []).map(flattenMotd).filter(Boolean)];
    const s = parts.join("").replace(/§./g, "").trim();
    return s || null;
  }
  return null;
}

/* ── Minecraft Bedrock: RakNet unconnected ping ───────────────────────── */

const RAKNET_MAGIC = Buffer.from("00ffff00fefefefefdfdfdfd12345678", "hex");

export function bedrockPing(host: string, port: number): Promise<LiveStatus | null> {
  const ping = Buffer.concat([
    Buffer.from([0x01]),                 // ID_UNCONNECTED_PING
    Buffer.alloc(8),                     // client time — zeros are accepted
    RAKNET_MAGIC,
    Buffer.alloc(8),                     // client GUID
  ]);
  return udpQuery(host, port, [ping], (msg) => {
    if (msg[0] !== 0x1c) return null;    // not ID_UNCONNECTED_PONG
    // 1 + 8 (time) + 8 (guid) + 16 (magic) + 2 (string length), then the MOTD
    const motd = msg.subarray(35).toString("utf8");
    const f = motd.split(";");
    // MCPE;<motd>;<proto>;<version>;<online>;<max>;…
    const online = Number(f[4]);
    const max = Number(f[5]);
    if (!Number.isFinite(online)) return null;
    return {
      online,
      max: Number.isFinite(max) ? max : null,
      motd: (f[1] || "").trim() || null,
      map: null,
    };
  });
}

/* ── Valve A2S_INFO ───────────────────────────────────────────────────── */

const A2S_HEADER = Buffer.from([0xff, 0xff, 0xff, 0xff]);
const A2S_INFO_BODY = Buffer.concat([
  Buffer.from([0x54]),                            // 'T'
  Buffer.from("Source Engine Query\0", "ascii"),
]);

function cstring(buf: Buffer, at: number): { value: string; next: number } {
  const end = buf.indexOf(0, at);
  const stop = end === -1 ? buf.length : end;
  return { value: buf.subarray(at, stop).toString("utf8"), next: stop + 1 };
}

export function a2sInfo(host: string, port: number): Promise<LiveStatus | null> {
  const query = Buffer.concat([A2S_HEADER, A2S_INFO_BODY]);
  return udpQuery(host, port, [query], (msg, send) => {
    if (msg.length < 5) return null;

    /* Since 2020 most servers answer the first A2S_INFO with a challenge
       (`ff ff ff ff 41 <4 bytes>`) and only answer for real once the query is
       re-sent with those four bytes appended. That is the `ff ff ff ff 41` the
       port audits in lib/games.ts saw from our own servers. */
    if (msg[4] === 0x41) {
      send(Buffer.concat([query, msg.subarray(5, 9)]));
      return null;                                  // keep waiting for the real reply
    }
    if (msg[4] !== 0x49) return null;               // not S2A_INFO

    let at = 5;
    at += 1;                                        // protocol byte
    const name = cstring(msg, at); at = name.next;
    const map = cstring(msg, at); at = map.next;
    const folder = cstring(msg, at); at = folder.next;
    const game = cstring(msg, at); at = game.next;
    at += 2;                                        // Steam app id
    if (at + 1 >= msg.length) return null;
    const players = msg[at];
    const maxPlayers = msg[at + 1];

    return {
      online: players,
      // 255 is A2S's "unset" sentinel, not a real slot count.
      max: maxPlayers === 255 ? null : maxPlayers,
      motd: name.value.trim() || null,
      map: map.value.trim() || null,
    };
  });
}

/* ── the one entry point ──────────────────────────────────────────────── */

/**
 * Ask a listed server who's on it. Resolves to null for anything we can't ask,
 * can't reach, or that answers with something we don't understand — the caller
 * shows a slot count and no live figure in that case, never a zero.
 *
 * `address` is the customer-facing connect address, "host" or "host:port".
 */
export async function queryLive(family: string, address: string): Promise<LiveStatus | null> {
  const protocol = QUERY_PROTOCOL[family as GameFamily];
  if (!protocol) return null;

  const cut = address.lastIndexOf(":");
  const hasPort = cut > 0 && /^\d+$/.test(address.slice(cut + 1));
  const host = hasPort ? address.slice(0, cut) : address;
  const port = hasPort ? Number(address.slice(cut + 1)) : joinPortFor(family as GameFamily).port;
  if (!host || !port) return null;

  try {
    if (protocol === "mc-java") return await mcJavaPing(host, port);
    if (protocol === "bedrock") return await bedrockPing(host, port);
    return await a2sInfo(host, port);
  } catch {
    return null;
  }
}

/**
 * Probe many servers at once, with a cap on how many sockets are open.
 * Unbounded `Promise.all` over a directory of a few hundred rows would open a
 * few hundred sockets in one tick.
 */
export async function queryAll<T extends { family: string; address: string }>(
  rows: T[],
  concurrency = 12,
): Promise<Map<string, LiveStatus>> {
  const out = new Map<string, LiveStatus>();
  const queue = rows.filter((r) => canQuery(r.family));
  let i = 0;

  const worker = async () => {
    for (;;) {
      const n = i++;
      if (n >= queue.length) return;
      const row = queue[n];
      const live = await queryLive(row.family, row.address);
      if (live) out.set(row.address, live);
    }
  };

  await Promise.all(Array.from({ length: Math.min(concurrency, queue.length) }, worker));
  return out;
}

