/**
 * Server directory: PURE, client-safe view rules shared by BOTH skins of the directory
 *   - the public marketing pages (app/nxm/_data/directory-hub.ts, HTML strings)
 *   - the customer portal (app/dashboard/directory/**, React)
 * so URL state, the factual fallback line and the pager maths are one implementation, not two.
 * No db, no Node imports (the portal's client components import this file).
 */
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { countryName } from "@/lib/directory-regions";
import { clampPage, normQ, PAGE_SIZE, MAX_PAGE, type DirSort, type PlayersFilter } from "@/lib/directory-query-sql";

export type HubFilters = { q: string | null; players: PlayersFilter; sort: DirSort; page: number };

/** URL search params -> filters (unknown values fall back to the defaults). */
export function readFilters(p: Record<string, string | string[] | undefined>): HubFilters {
  const one = (k: string) => { const v = p[k]; return Array.isArray(v) ? v[0] : v; };
  const pl = one("players"), so = one("sort");
  const players: PlayersFilter = pl === "has" || pl === "notfull" ? pl : "any";
  const sort: DirSort = so === "newest" || so === "name" ? so : "players";
  return { q: normQ(one("q")), players, sort, page: clampPage(one("page")) };
}

export const isFiltered = (f: HubFilters) => !!f.q || f.players !== "any" || f.sort !== "players";

/** Query string for a list URL, keeping only non-default keys (stable order). */
export function qs(f: Partial<HubFilters>, extra: Record<string, string | null | undefined> = {}): string {
  const u = new URLSearchParams();
  for (const [k, v] of Object.entries(extra)) if (v) u.set(k, v);
  if (f.q) u.set("q", f.q);
  if (f.players && f.players !== "any") u.set("players", f.players);
  if (f.sort && f.sort !== "players") u.set("sort", f.sort);
  if (f.page && f.page > 1) u.set("page", String(f.page));
  const s = u.toString();
  return s ? `?${s}` : "";
}

const fmt = (n: number) => n.toLocaleString("en-US");
const gameName = (g: string) => GAME_DISPLAY[g as GameFamily]?.name ?? g;

/** The factual fallback "about" line: only stored fields, no adjectives or claims (spec section 4). */
export function factualLine(e: { game: string; country: string | null; map?: string | null; maxPlayers: number | null }): string {
  return `${gameName(e.game)} server${e.country ? ` in ${countryName(e.country)}` : ""}. ${e.map ? `Map: ${e.map}. ` : ""}${e.maxPlayers ? `${fmt(e.maxPlayers)} slots.` : ""}`.trim();
}

/** Total pages for a result count (capped at the deepest page the SQL layer serves). */
export const pageCount = (total: number, size = PAGE_SIZE) => Math.min(Math.ceil(Math.max(0, total) / size), MAX_PAGE);

/** Page numbers to render: first, last and two either side of the current one; 0 marks a gap ("…"). */
export function pageNumbers(cur: number, pages: number): number[] {
  if (pages <= 1) return [];
  const set = new Set([1, pages, cur - 2, cur - 1, cur, cur + 1, cur + 2].filter((n) => n >= 1 && n <= pages));
  const out: number[] = [];
  let last = 0;
  for (const n of [...set].sort((a, b) => a - b)) { if (n - last > 1) out.push(0); out.push(n); last = n; }
  return out;
}

/** "4 min ago" style age (never in the future). */
export function ago(t: number, now = Date.now()): string {
  const m = Math.max(0, Math.round((now - t) / 60_000));
  return m < 1 ? "just now" : m < 60 ? `${m} min ago` : m < 2880 ? `${Math.round(m / 60)} h ago` : `${Math.round(m / 1440)} d ago`;
}

