import "server-only";
import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";
import { gameSubdomainBase } from "@/lib/game-subdomain-dns";
import { GAME_ART_SLUG, GAME_FAMILIES, type GameFamily } from "@/lib/games";
import { PAID_LISTING_WHERE } from "@/lib/server-directory-data";
import { nxeonServerId, parseServerId } from "@/lib/directory-ids";
import { findServer } from "@/lib/directory-query";
import type { DirEntry } from "@/lib/server-directory";
import { gameArt, gameName } from "@/app/nxm/_data/games-lib";

/**
 * Customer-portal side of the server directory (/dashboard/directory/**). Every LIST and COUNT comes from the
 * same data layer as the public pages (lib/directory-query.ts: SQL paging, facets, Nxeon-hosted merge, blocklist,
 * liveness); this file only adds what a signed-in customer has and a marketing page does not:
 *   - the customer's OWN game servers and their listing state ("list your server")
 *   - favourites, stored per account (DirectoryFavourite), never localStorage
 * Every function takes the user id from the caller, which must come from requireUser() (never from input).
 */

export const MAX_FAVOURITES = 200;

/** Art paths the portal cards need for one game (static files under public/). */
export type GameArtView = { name: string; hero: string | null; cover: string | null; logo: string | null };
export function artFor(game: string): GameArtView {
  const a = gameArt(game);
  const slug = GAME_ART_SLUG[game as GameFamily];
  return { name: gameName(game), hero: a.hero, cover: a.cover, logo: slug ? `/games/art/${slug.hero}_logo.png` : null };
}
export function artMap(games: Iterable<string>): Record<string, GameArtView> {
  const out: Record<string, GameArtView> = {};
  for (const g of games) if (!out[g]) out[g] = artFor(g);
  return out;
}
export const allGames = (): string[] => [...GAME_FAMILIES];

// ── the customer's own servers ────────────────────────────────────────────
export type OwnServer = {
  /** Internal server id: only ever rendered back to its owner, for the listing controls. */
  id: string;
  kind: "paid" | "free";
  game: string;
  name: string;
  address: string | null;
  status: string;
  listed: boolean;
  /** Listed AND visible in the directory right now (running, has a play address, not hidden by moderation). */
  visible: boolean;
  hiddenByModeration: boolean;
  /** Directory id of the live listing, when visible. */
  publicId: string | null;
  /** Why a listed server is not showing, in plain words. */
  note: string | null;
};

export async function ownServers(userId: string): Promise<OwnServer[]> {
  const [base, freeDomain] = await Promise.all([gameSubdomainBase().catch(() => ""), getSetting("free_minecraft_domain", "play.nxeon.cloud").catch(() => "play.nxeon.cloud")]);
  const [paid, free] = await Promise.all([
    db.server.findMany({
      where: { userId, gamePlan: { isNot: null }, status: { notIn: ["DELETING"] } },
      select: {
        id: true, name: true, label: true, subdomain: true, status: true, publicListing: true,
        gamePlan: { select: { gameFamily: true } }, listingMeta: { select: { hidden: true } },
      },
      orderBy: { createdAt: "asc" },
    }).catch(() => []),
    db.freeMinecraftServer.findMany({ where: { userId }, select: { id: true, name: true, subdomain: true, status: true, isPublic: true } }).catch(() => []),
  ]);
  const out: OwnServer[] = paid.map((s) => {
    const game = s.gamePlan?.gameFamily ?? "minecraft";
    const hidden = !!s.listingMeta?.hidden;
    const visible = s.publicListing && s.status === "RUNNING" && !!s.subdomain && !hidden;
    const note = !s.publicListing ? null
      : hidden ? "Hidden by Nxeon moderation. Contact support to find out why."
      : !s.subdomain ? "Needs a play address before it can be listed."
      : s.status !== "RUNNING" ? "Listed, but only shows while the server is running."
      : null;
    return {
      id: s.id, kind: "paid", game, name: s.label || s.name, address: s.subdomain && base ? `${s.subdomain}.${base}` : null,
      status: s.status, listed: s.publicListing, visible, hiddenByModeration: hidden,
      // Same key the directory builds for a paid entry (lib/server-directory-data.ts paidEntries).
      publicId: visible ? nxeonServerId(game, `p-${s.id.slice(0, 8)}`) : null, note,
    };
  });
  for (const f of free) {
    out.push({
      id: f.id, kind: "free", game: "minecraft", name: f.name || f.subdomain, address: `${f.subdomain}.${freeDomain}`,
      status: f.status, listed: f.isPublic, visible: f.isPublic && f.status === "READY", hiddenByModeration: false,
      publicId: null, note: f.isPublic && f.status !== "READY" ? "Listed, but only shows while the server is ready." : null,
    });
  }
  return out;
}

/** True when this directory entry is one of the user's own servers (paid listings only carry a public id). */
export function ownsEntry(own: OwnServer[], e: Pick<DirEntry, "publicId" | "address">): OwnServer | null {
  return own.find((o) => (o.publicId && o.publicId === e.publicId) || (!!o.address && o.address === e.address)) ?? null;
}

// ── favourites ────────────────────────────────────────────────────────────
export type Favourite = { serverId: string; game: string; name: string; address: string; createdAt: Date };

export async function favouriteIds(userId: string): Promise<Set<string>> {
  const rows = await db.directoryFavourite.findMany({ where: { userId }, select: { serverId: true } }).catch(() => []);
  return new Set(rows.map((r) => r.serverId));
}

export async function listFavourites(userId: string, limit = MAX_FAVOURITES): Promise<Favourite[]> {
  return db.directoryFavourite.findMany({
    where: { userId }, orderBy: { createdAt: "desc" }, take: limit,
    select: { serverId: true, game: true, name: true, address: true, createdAt: true },
  }).catch(() => []);
}

/** Favourites resolved against the live directory: the current entry, or null when it is no longer listed. */
export async function resolveFavourites(favs: Favourite[]): Promise<{ fav: Favourite; entry: DirEntry | null }[]> {
  const out: { fav: Favourite; entry: DirEntry | null }[] = [];
  // Sequential in small groups: each lookup is one indexed query, and the list is capped at MAX_FAVOURITES.
  for (let i = 0; i < favs.length; i += 8) {
    const part = await Promise.all(favs.slice(i, i + 8).map(async (fav) => {
      const id = parseServerId(fav.serverId);
      const entry = id ? await findServer(id.game, id.hash).catch(() => null) : null;
      return { fav, entry };
    }));
    out.push(...part);
  }
  return out;
}

