/**
 * Customer actions for the portal server directory (/dashboard/directory). The acting user ALWAYS comes from
 * requireUser(); no action takes a user id. Favourites are keyed by the PUBLIC directory id, so a customer can
 * only ever add a server that is publicly listed right now, and can only see or remove their own rows.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { parseServerId } from "./directory-ids";
import { findServer } from "./directory-query";
import { MAX_FAVOURITES } from "./directory-portal-data";
import { PORTAL_DIR } from "./directory-view";

export type FavResult = { ok: true; saved: boolean } | { ok: false; error: string };

/** Save or un-save a listed server. `want` = the desired state (idempotent: double clicks are harmless). */
export async function setFavourite(serverId: string, want: boolean): Promise<FavResult> {
  const user = await requireUser();
  const rl = checkRateLimit(`dir:fav:${user.id}`, { max: 60, windowMs: 60_000 });
  if (!rl.ok) return { ok: false, error: `Too many changes. Try again in ${rl.retryAfterSec}s.` };
  const id = parseServerId(String(serverId ?? ""));
  if (!id) return { ok: false, error: "That server isn't in the directory." };
  const key = `${id.game}-${id.hash}`;
  try {
    if (!want) {
      await db.directoryFavourite.deleteMany({ where: { userId: user.id, serverId: key } });
      revalidatePath(PORTAL_DIR, "layout");
      return { ok: true, saved: false };
    }
    const existing = await db.directoryFavourite.findUnique({ where: { userId_serverId: { userId: user.id, serverId: key } }, select: { id: true } });
    if (existing) return { ok: true, saved: true };
    const count = await db.directoryFavourite.count({ where: { userId: user.id } });
    if (count >= MAX_FAVOURITES) return { ok: false, error: `You can save up to ${MAX_FAVOURITES} servers. Remove one first.` };
    const e = await findServer(id.game, id.hash);
    if (!e) return { ok: false, error: "That server isn't listed right now." };
    await db.directoryFavourite.create({ data: { userId: user.id, serverId: key, game: e.game, name: e.name.slice(0, 120), address: e.address.slice(0, 260) } });
    revalidatePath(PORTAL_DIR, "layout");
    return { ok: true, saved: true };
  } catch {
    return { ok: false, error: "Could not save. Please try again." };
  }
}

