"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { usePathname, useRouter } from "next/navigation";
import { Icon } from "@/components/nx/Icon";
import { setFavourite } from "@/lib/actions-directory";
import { qs, type HubFilters } from "@/lib/directory-view";

/* Client islands of the portal directory. Everything else on these pages is server-rendered from the URL, so
   the pages work (and are shareable) without JS; these add copy, favourites and live filter updates. */

/** Copy a connect address. Announces the result to screen readers. */
export function CopyButton({ text, label, big = false }: { text: string; label: string; big?: boolean }) {
  const [done, setDone] = useState(false);
  const copy = async () => {
    try { await navigator.clipboard?.writeText(text); setDone(true); setTimeout(() => setDone(false), 1600); } catch { /* clipboard denied: the address is still selectable */ }
  };
  return (
    <button type="button" onClick={copy} aria-label={done ? "Address copied" : label}
      className={"relative z-[2] inline-flex flex-none items-center gap-1.5 rounded-[9px] border border-rim-hi bg-well font-semibold text-tx-dim transition hover:border-brand-400/45 hover:text-white focus-visible:outline-2 focus-visible:outline-brand-400 " + (big ? "h-[40px] px-3.5 text-[13px]" : "h-[30px] px-2.5 text-[11.5px]")}>
      <Icon name={done ? "checkcircle" : "copy"} size={big ? 12 : 10} tone="inherit" className={done ? "text-emerald-400" : "opacity-70"} />
      <span aria-live="polite">{done ? "Copied" : big ? "Copy address" : "Copy"}</span>
    </button>
  );
}

/** Save / un-save a server to the account's favourites (DirectoryFavourite). Optimistic, rolls back on error. */
export function FavButton({ serverId, saved: initial, name, big = false }: { serverId: string; saved: boolean; name: string; big?: boolean }) {
  const [saved, setSaved] = useState(initial);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  useEffect(() => setSaved(initial), [initial]);
  const toggle = () => {
    const next = !saved;
    setSaved(next); setErr(null);
    start(async () => {
      const r = await setFavourite(serverId, next);
      if (!r.ok) { setSaved(!next); setErr(r.error); } else setSaved(r.saved);
    });
  };
  return (
    <span className="relative z-[2] inline-flex flex-none items-center gap-2">
      <button type="button" onClick={toggle} disabled={pending} aria-pressed={saved}
        aria-label={saved ? `Remove ${name} from favourites` : `Save ${name} to favourites`}
        title={saved ? "Saved to favourites" : "Save to favourites"}
        className={"inline-flex items-center justify-center gap-1.5 rounded-[9px] border font-semibold transition focus-visible:outline-2 focus-visible:outline-brand-400 disabled:opacity-60 " +
          (big ? "h-[40px] px-3.5 text-[13px] " : "h-[30px] w-[30px] ") +
          (saved ? "border-[#ff6fae]/50 bg-[#ff6fae]/12 text-[#ff9cc8]" : "border-rim-hi bg-well text-tx-dim hover:border-brand-400/45 hover:text-white")}>
        <svg width={big ? 15 : 14} height={big ? 15 : 14} viewBox="0 0 24 24" aria-hidden fill={saved ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" strokeLinejoin="round">
          <path d="M12 20.5s-7.5-4.6-9.3-9.2C1.4 8 3.4 4.5 7 4.5c2.1 0 3.6 1.2 5 3 1.4-1.8 2.9-3 5-3 3.6 0 5.6 3.5 4.3 6.8-1.8 4.6-9.3 9.2-9.3 9.2z" />
        </svg>
        {big && <span>{saved ? "Saved" : "Save"}</span>}
      </button>
      {err && <span role="alert" className="text-[11.5px] text-[#ff8ba6]">{err}</span>}
    </span>
  );
}

const field = "flex h-[40px] items-center rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3.5";

/**
 * Search + players + sort for one list page. Every change is a `router.replace` of the URL (no history spam,
 * no scroll jump); the server renders the result from the URL, so the same state is a plain GET form with JS off.
 */
export function FilterBar({ filters, placeholder, extra = {} }: { filters: HubFilters; placeholder: string; extra?: Record<string, string> }) {
  const router = useRouter();
  const path = usePathname();
  const [q, setQ] = useState(filters.q ?? "");
  const [pending, start] = useTransition();
  const t = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => setQ(filters.q ?? ""), [filters.q]);
  const go = (f: Partial<HubFilters>) => {
    const next = { ...filters, ...f, page: 1 };
    start(() => router.replace(path + qs(next, extra), { scroll: false }));
  };
  const onQ = (v: string) => {
    setQ(v);
    if (t.current) clearTimeout(t.current);
    t.current = setTimeout(() => { const s = v.trim(); if (s.length === 0 || s.length >= 2) go({ q: s || null }); }, 350);
  };
  const filtered = !!filters.q || filters.players !== "any" || filters.sort !== "players";
  return (
    <form role="search" method="get" action={path} onSubmit={(e) => { e.preventDefault(); go({ q: q.trim() || null }); }}
      className="flex flex-wrap items-center gap-2.5" aria-busy={pending}>
      {Object.entries(extra).map(([k, v]) => <input key={k} type="hidden" name={k} value={v} />)}
      <label className={field + " min-w-[220px] flex-1 gap-2.5"}>
        <Icon name="search" size={14} tone="inherit" className="flex-none text-tx-faint" />
        <span className="sr-only">Search servers</span>
        <input name="q" type="search" value={q} onChange={(e) => onQ(e.target.value)} placeholder={placeholder} maxLength={60} autoComplete="off"
          className="min-w-0 flex-1 bg-transparent text-[13px] text-white outline-none placeholder:text-tx-faint" />
        {pending && <span className="h-3 w-3 flex-none animate-spin rounded-full border-2 border-brand-300 border-t-transparent" aria-hidden />}
      </label>
      <label className={field}>
        <span className="sr-only">Players</span>
        <select name="players" value={filters.players} onChange={(e) => go({ players: e.target.value as HubFilters["players"] })}
          className="cursor-pointer bg-transparent pr-2 text-[12.5px] font-semibold text-tx-dim outline-none">
          <option value="any">Any players</option>
          <option value="has">Has players</option>
          <option value="notfull">Not full</option>
        </select>
      </label>
      <label className={field}>
        <span className="sr-only">Sort</span>
        <select name="sort" value={filters.sort} onChange={(e) => go({ sort: e.target.value as HubFilters["sort"] })}
          className="cursor-pointer bg-transparent pr-2 text-[12.5px] font-semibold text-tx-dim outline-none">
          <option value="players">Most players</option>
          <option value="newest">Newest</option>
          <option value="name">Name A to Z</option>
        </select>
      </label>
      <noscript><button type="submit" className="nx-cta h-[40px] px-4 text-[12.5px]">Search</button></noscript>
      {filtered && (
        <button type="button" onClick={() => { setQ(""); start(() => router.replace(path + qs({}, extra), { scroll: false })); }}
          className="h-[40px] rounded-[11px] px-3 text-[12.5px] font-semibold text-brand-300 hover:text-white">Clear</button>
      )}
    </form>
  );
}

