import Link from "next/link";
import { Icon } from "@/components/nx/Icon";
import { CountryFlag } from "@/components/ui/CountryFlag";
import type { DirEntry } from "@/lib/server-directory";
import type { Region } from "@/lib/directory-regions";
import { countryName } from "@/lib/directory-regions";
import type { Tally } from "@/lib/directory-seo";
import { attributionForKey } from "@/lib/directory-attribution";
import { ago, pageNumbers, pageCount, pServer, qs, type HubFilters } from "@/lib/directory-view";
import type { GameArtView } from "@/lib/directory-portal-data";
import { CopyButton, FavButton } from "./DirClient";

/* eslint-disable @next/next/no-img-element -- static key art under public/, outside the optimizer */

/*
 * Server-rendered pieces of the PORTAL directory. Same data and rules as the public pages (one data layer), drawn
 * in the dashboard's own language: rim borders, well surfaces, brand-300 links, emerald for "has players", the
 * nx-dark-island scrim over game art. Copy states only what the stored data says.
 */

const fmt = (n: number) => n.toLocaleString("en-US");
const plural = (n: number, one: string, many = one + "s") => `${fmt(n)} ${n === 1 ? one : many}`;
const hueOf = (s: string) => { let h = 0; for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h % 360; };
const initials = (name: string) => {
  const w = name.normalize("NFKC").replace(/[^\p{L}\p{N} ]+/gu, " ").trim().split(/\s+/).filter(Boolean);
  return (w.length ? (w.length > 1 ? w[0][0] + w[1][0] : w[0].slice(0, 2)) : "?").toUpperCase();
};

export type CardCtx = { art: Record<string, GameArtView>; favs: Set<string>; ownIds?: Set<string>; now?: number };

/** Where the row came from, as a short badge. Never claims Nxeon runs a third-party server. */
export function sourceBadge(e: DirEntry, own = false): { label: string; tone: "nx" | "own" | "list" | "owner" } {
  if (own) return { label: "Your server", tone: "own" };
  if (e.nxeon) return { label: e.source === "nxeon-community" ? "Nxeon community" : "Hosted on Nxeon", tone: "nx" };
  if (e.attribution === "owner") return { label: "Owner-submitted", tone: "owner" };
  return { label: e.attribution === "steam" ? "Steam list" : "Public list", tone: "list" };
}

export function Badge({ e, own }: { e: DirEntry; own?: boolean }) {
  const b = sourceBadge(e, own);
  const cls = b.tone === "nx" ? "border-cyan-400/45 bg-cyan-400/10 text-cyan-300"
    : b.tone === "own" ? "border-[#a86bff]/50 bg-[#a86bff]/14 text-[#d2b8ff]"
    : b.tone === "owner" ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-300"
    : "border-rim-hi bg-[rgba(6,14,36,.6)] text-tx-faint";
  return <span className={"inline-flex flex-none items-center gap-1 rounded-[6px] border px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide " + cls}>{b.tone === "nx" && <Icon name="shield" size={8} tone="inherit" />}{b.label}</span>;
}

/** "12 / 100 playing" only for a fresh count; otherwise the slot count, never a made-up zero. */
export function Players({ e, compact = false }: { e: DirEntry; compact?: boolean }) {
  if (e.players != null) {
    const on = e.players > 0;
    const pct = e.maxPlayers ? Math.max(3, Math.min(100, Math.round((e.players / e.maxPlayers) * 100))) : 0;
    return (
      <span className="inline-flex min-w-0 flex-col gap-1">
        <span className={"inline-flex items-center gap-1.5 text-[12px] font-semibold " + (on ? "text-emerald-300" : "text-tx-dim")}>
          <span className={"h-[6px] w-[6px] flex-none rounded-full " + (on ? "bg-emerald-400" : "bg-slate-500")} aria-hidden />
          <span className="num">{fmt(e.players)}</span>{e.maxPlayers ? <span className="text-tx-faint">/ {fmt(e.maxPlayers)}</span> : null} playing
        </span>
        {!compact && e.maxPlayers ? <span className="h-[3px] w-full overflow-hidden rounded-full bg-white/8" aria-hidden><span className="block h-full rounded-full bg-emerald-400/80" style={{ width: `${pct}%` }} /></span> : null}
      </span>
    );
  }
  return <span className="text-[12px] text-tx-faint">{e.maxPlayers ? `Up to ${fmt(e.maxPlayers)} players` : "Player count unknown"}</span>;
}

/** "Checked 4 min ago" only when Nxeon's own probe answered; otherwise when the source list last had it. */
export function Freshness({ e, now }: { e: DirEntry; now?: number }) {
  if (e.checkedAt) return <span className="text-[11.5px] text-emerald-300/90">Checked {ago(e.checkedAt, now)}</span>;
  if (!e.nxeon && e.seenAt) return <span className="text-[11.5px] text-tx-faint">Seen on the list {ago(e.seenAt, now)}</span>;
  return null;
}

export function Where({ e }: { e: DirEntry }) {
  if (e.country) return <span className="inline-flex min-w-0 items-center gap-1.5"><CountryFlag code={e.country} size={14} /><span className="truncate">{countryName(e.country)}</span></span>;
  if (e.region) return <span className="truncate">{e.region}</span>;
  return null;
}

/** Generated per-server art: the game's key art, tinted by a hue from the server's key, plus its initials. */
export function ServerArt({ e, art, tall = false }: { e: DirEntry; art?: GameArtView; tall?: boolean }) {
  const h = hueOf(e.key + e.name);
  return (
    <div aria-hidden className={"nx-dark-island relative overflow-hidden bg-[#050d20] " + (tall ? "h-[150px] sm:h-[180px]" : "h-[92px]")}>
      {e.imageUrl ? <img src={e.imageUrl} alt="" referrerPolicy="no-referrer" loading="lazy" className="h-full w-full object-cover" />
        : art?.hero ? <img src={art.hero} alt="" loading="lazy" decoding="async" className="h-full w-full object-cover opacity-45" style={{ objectPosition: "center 65%" }} /> : null}
      <span className="absolute inset-0" style={{ background: `linear-gradient(135deg, hsla(${h},85%,55%,.30), hsla(${(h + 60) % 360},85%,45%,.12) 55%, rgba(2,7,20,.85))` }} />
      {!e.imageUrl && <b className="absolute right-3 top-2 font-extrabold tracking-tight text-white/80" style={{ fontSize: tall ? 34 : 22, textShadow: "0 2px 12px rgba(0,0,0,.5)" }}>{initials(e.name)}</b>}
    </div>
  );
}

/** The list card. The name is the one link to the detail page (stretched over the card); Copy and Save sit above it. */
export function ServerCard({ e, ctx }: { e: DirEntry; ctx: CardCtx }) {
  const art = ctx.art[e.game];
  const own = !!(e.publicId && ctx.ownIds?.has(e.publicId));
  const href = e.publicId ? pServer(e.publicId) : null;
  return (
    <li className="group relative flex min-w-0 flex-col overflow-hidden rounded-[16px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))] transition hover:border-brand-400/45 focus-within:border-brand-400/60">
      <div className="relative">
        <ServerArt e={e} art={art} />
        <div className="nx-dark-island absolute inset-x-3 bottom-2 flex items-end gap-2">
          <span className="min-w-0 flex-1">
            <h3 className="truncate text-[14.5px] font-extrabold leading-tight text-white" title={e.name}>
              {href ? <Link href={href} className="outline-none after:absolute after:inset-0 after:z-[1] after:content-[''] focus-visible:underline">{e.name}</Link> : e.name}
            </h3>
            <span className="block truncate text-[11.5px] text-white/65">{art?.name ?? e.game}</span>
          </span>
          <Badge e={e} own={own} />
        </div>
      </div>
      <div className="flex flex-1 flex-col gap-2 p-3.5">
        <div className="flex items-start justify-between gap-3"><Players e={e} /></div>
        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-[11.5px] text-tx-dim">
          <Where e={e} />
          {e.map && <span className="max-w-[16ch] truncate rounded-[6px] bg-well px-1.5 py-0.5 text-tx-faint" title={`Map ${e.map}`}>{e.map}</span>}
          <Freshness e={e} now={ctx.now} />
        </div>
        <div className="mt-auto flex items-center gap-2 pt-1">
          <code className="min-w-0 flex-1 truncate rounded-[9px] border border-rim-hi bg-well px-2.5 py-1.5 font-mono text-[11.5px] text-tx-dim" title={e.address}>{e.address}</code>
          <CopyButton text={e.address} label={`Copy the address of ${e.name}`} />
          {e.publicId && <FavButton serverId={e.publicId} saved={ctx.favs.has(e.publicId)} name={e.name} />}
        </div>
      </div>
    </li>
  );
}

export function CardGrid({ rows, ctx }: { rows: DirEntry[]; ctx: CardCtx }) {
  return <ul className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4">{rows.map((e) => <ServerCard key={e.key} e={e} ctx={ctx} />)}</ul>;
}

/** Compact row for the home shelves: art chip, name, game · country, players. */
export function MiniRow({ e, ctx }: { e: DirEntry; ctx: CardCtx }) {
  const art = ctx.art[e.game];
  const href = e.publicId ? pServer(e.publicId) : null;
  return (
    <li className="relative flex min-w-0 items-center gap-3 rounded-[12px] border border-transparent px-2 py-2 transition hover:border-rim-hi hover:bg-well">
      <span aria-hidden className="nx-dark-island relative grid h-[42px] w-[42px] flex-none place-items-center overflow-hidden rounded-[10px] bg-[#050d20]">
        {art?.cover && <img src={art.cover} alt="" loading="lazy" className="absolute inset-0 h-full w-full object-cover opacity-60" />}
        <b className="relative text-[12px] font-extrabold text-white">{initials(e.name)}</b>
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-[13px] font-bold text-white" title={e.name}>
          {href ? <Link href={href} className="outline-none after:absolute after:inset-0 after:content-[''] focus-visible:underline">{e.name}</Link> : e.name}
        </span>
        <span className="flex min-w-0 items-center gap-2 text-[11.5px] text-tx-faint"><span className="truncate">{art?.name ?? e.game}</span>{(e.country || e.region) && <><span aria-hidden>·</span><Where e={e} /></>}</span>
      </span>
      <span className="flex-none text-right"><Players e={e} compact /></span>
    </li>
  );
}

export function MiniList({ rows, ctx }: { rows: DirEntry[]; ctx: CardCtx }) {
  return <ul className="flex flex-col gap-0.5">{rows.map((e) => <MiniRow key={e.key} e={e} ctx={ctx} />)}</ul>;
}

// ── layout pieces ───────────────────────────────────────────────────────────
export function Panel({ id, title, lede, more, children, className = "" }: { id: string; title: string; lede?: string; more?: React.ReactNode; children: React.ReactNode; className?: string }) {
  return (
    <section aria-labelledby={id} className={"rounded-[18px] border border-rim-hi bg-[rgba(6,14,36,.55)] p-4 sm:p-5 " + className}>
      <div className="mb-3.5 flex flex-wrap items-end justify-between gap-2">
        <div className="min-w-0">
          <h2 id={id} className="text-[17px] font-extrabold tracking-[-0.01em] text-white">{title}</h2>
          {lede && <p className="mt-0.5 text-[12.5px] text-tx-dim">{lede}</p>}
        </div>
        {more}
      </div>
      {children}
    </section>
  );
}

export function MoreLink({ href, children }: { href: string; children: React.ReactNode }) {
  return <Link href={href} className="text-[12.5px] font-semibold text-brand-300 transition hover:text-white">{children} <span aria-hidden>→</span></Link>;
}

export function Crumbs({ trail }: { trail: { name: string; href?: string }[] }) {
  return (
    <nav aria-label="Breadcrumb" className="text-[12px] text-tx-faint">
      <ol className="flex flex-wrap items-center gap-1.5">
        {trail.map((c, i) => (
          <li key={i} className="flex min-w-0 items-center gap-1.5">
            {i > 0 && <span aria-hidden>/</span>}
            {c.href && i < trail.length - 1 ? <Link href={c.href} className="hover:text-white">{c.name}</Link> : <span aria-current="page" className="truncate text-tx-dim">{c.name}</span>}
          </li>
        ))}
      </ol>
    </nav>
  );
}

/** Page hero in the dashboard language: eyebrow, H1, one line, real stats. */
export function DirHero({ eyebrow, title, accent, sub, stats, art, crumbs, action }: {
  eyebrow: string; title: string; accent?: string; sub: string; stats: [string, string][]; art?: string | null;
  crumbs?: { name: string; href?: string }[]; action?: React.ReactNode;
}) {
  return (
    <header className="nx-dark-island relative overflow-hidden rounded-[20px] border border-rim-hi bg-[#050d20]">
      {art && <img src={art} alt="" aria-hidden className="absolute inset-0 h-full w-full object-cover opacity-35" style={{ objectPosition: "center 40%" }} />}
      <span aria-hidden className="absolute inset-0" style={{ background: "linear-gradient(90deg, rgba(2,7,20,.96) 0%, rgba(2,7,20,.78) 48%, rgba(2,7,20,.35) 100%), radial-gradient(60% 120% at 80% 0%, rgba(168,60,255,.18), transparent 70%)" }} />
      <div className="relative flex flex-col gap-4 px-5 py-6 sm:px-7 sm:py-7">
        {crumbs && <Crumbs trail={crumbs} />}
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div className="min-w-0 max-w-[720px]">
            <span className="section-label text-[#7f9ad0]">{eyebrow}</span>
            <h1 className="mt-2 text-[30px] font-extrabold leading-[1.05] tracking-[-0.03em] text-white sm:text-[38px]">
              {title}{accent && <> <span className="grad-text">{accent}</span></>}
            </h1>
            <p className="mt-2 max-w-[64ch] text-[14px] leading-relaxed text-white/70">{sub}</p>
          </div>
          {action}
        </div>
        {stats.length > 0 && (
          <dl className="flex flex-wrap gap-x-6 gap-y-2">
            {stats.map(([v, l]) => <div key={l} className="flex items-baseline gap-1.5"><dt className="sr-only">{l}</dt><dd className="num text-[18px] font-extrabold text-white">{v}</dd><span className="text-[12px] text-white/60" aria-hidden>{l}</span></div>)}
          </dl>
        )}
      </div>
    </header>
  );
}

export function GameTile({ game, art, t, hosted, href }: { game: string; art: GameArtView; t?: Tally; hosted: boolean; href: string }) {
  const n = t?.n ?? 0;
  return (
    <li>
      <Link href={href} className={"nx-dark-island group relative flex aspect-[3/4] flex-col justify-end overflow-hidden rounded-[14px] border border-rim-hi bg-[#050d20] p-3 transition hover:border-brand-400/55 focus-visible:outline-2 focus-visible:outline-brand-400 " + (n ? "" : "opacity-75 hover:opacity-100")}>
        {art.cover && <img src={art.cover} alt="" loading="lazy" decoding="async" className="absolute inset-0 h-full w-full object-cover transition duration-300 group-hover:scale-[1.04]" />}
        <span aria-hidden className="absolute inset-0 bg-[linear-gradient(180deg,rgba(2,7,20,0)_35%,rgba(2,7,20,.92))]" />
        <span className="relative">
          <b className="block truncate text-[13.5px] font-extrabold text-white">{art.name}</b>
          <small className="block text-[11.5px] text-white/70">{n ? <>{plural(n, "server")}{t!.p ? <> · <span className="text-emerald-300">{fmt(t!.p)} playing</span></> : null}</> : "No servers listed yet"}</small>
          {!hosted && <small className="block text-[10.5px] text-white/50">Not hosted by Nxeon</small>}
        </span>
      </Link>
    </li>
  );
}

export function RegionTabs({ tabs, all, active, hrefFor }: { tabs: { region: Region; t: Tally }[]; all: number; active: Region | null; hrefFor: (r: Region | null) => string }) {
  if (!tabs.length) return null;
  const on = (r: Region | null) => (r?.slug ?? null) === (active?.slug ?? null) || (!!r && active?.kind === "country" && r.kind === "continent" && active.continent === r.code);
  const tab = (r: Region | null, label: string, n: number) => (
    <Link key={label} href={hrefFor(r)} scroll={false} aria-current={on(r) ? (r?.slug === active?.slug ? "page" : "true") : undefined}
      className={"chip h-[34px] flex-none gap-2 whitespace-nowrap " + (on(r) ? "chip-on" : "")}>
      {label}<span className={"rounded-full px-1.5 text-[10.5px] font-extrabold " + (on(r) ? "bg-white/22 text-white" : "bg-[rgba(72,148,255,0.16)] text-[#9dbdee]")}>{fmt(n)}</span>
    </Link>
  );
  return <nav aria-label="Regions" className="-mx-1 flex gap-2 overflow-x-auto px-1 pb-1">{tab(null, "All regions", all)}{tabs.map((x) => tab(x.region, x.region.label, x.t.n))}</nav>;
}

export function CountryChips({ list, active, hrefFor }: { list: { region: Region; t: Tally }[]; active: Region | null; hrefFor: (r: Region) => string }) {
  if (!list.length) return null;
  return (
    <ul aria-label="Countries" className="flex flex-wrap gap-1.5">
      {list.map((x) => {
        const on = active?.slug === x.region.slug;
        return (
          <li key={x.region.slug}>
            <Link href={hrefFor(x.region)} scroll={false} aria-current={on ? "page" : undefined}
              className={"inline-flex h-[30px] items-center gap-1.5 rounded-full border px-2.5 text-[12px] font-semibold transition " + (on ? "border-brand-400/60 bg-brand-500/20 text-white" : "border-rim-hi bg-well text-tx-dim hover:text-white")}>
              <CountryFlag code={x.region.code} size={14} />{x.region.label}<span className="num text-tx-faint">{fmt(x.t.n)}</span>
            </Link>
          </li>
        );
      })}
    </ul>
  );
}

export function Pager({ base, filters, total, extra = {} }: { base: string; filters: HubFilters; total: number; extra?: Record<string, string> }) {
  const pages = pageCount(total);
  const nums = pageNumbers(filters.page, pages);
  if (!nums.length) return null;
  const href = (n: number) => base + qs({ ...filters, page: n }, extra);
  const cls = "grid h-[36px] min-w-[36px] place-items-center rounded-[10px] border px-2.5 text-[12.5px] font-semibold transition ";
  return (
    <nav aria-label="Pages" className="flex flex-wrap items-center justify-center gap-1.5">
      {filters.page > 1 && <Link href={href(filters.page - 1)} rel="prev" className={cls + "border-rim-hi bg-well text-tx-dim hover:text-white"}>Previous</Link>}
      {nums.map((n, i) => n === 0 ? <span key={`g${i}`} aria-hidden className="px-1 text-tx-faint">…</span>
        : <Link key={n} href={href(n)} aria-current={n === filters.page ? "page" : undefined} className={cls + (n === filters.page ? "border-brand-400/60 bg-brand-500/25 text-white" : "border-rim-hi bg-well text-tx-dim hover:text-white")}>{n}</Link>)}
      {filters.page < pages && <Link href={href(filters.page + 1)} rel="next" className={cls + "border-rim-hi bg-well text-tx-dim hover:text-white"}>Next</Link>}
    </nav>
  );
}

export function EmptyState({ title, text, alts = [], cta }: { title: string; text: string; alts?: { label: string; href: string; n: number }[]; cta?: React.ReactNode }) {
  return (
    <div role="status" className="rounded-[16px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-6 py-12 text-center">
      <Icon name="globe" size={26} className="mx-auto" />
      <p className="mt-3 text-[15px] font-extrabold text-white">{title}</p>
      <p className="mx-auto mt-1.5 max-w-[56ch] text-[12.5px] leading-relaxed text-tx-dim">{text}</p>
      {alts.length > 0 && (
        <ul className="mt-4 flex flex-wrap justify-center gap-2">
          {alts.map((a) => <li key={a.href}><Link href={a.href} className="chip h-[32px] gap-2">{a.label}<span className="num text-tx-faint">{fmt(a.n)}</span></Link></li>)}
        </ul>
      )}
      {cta && <div className="mt-5">{cta}</div>}
    </div>
  );
}

/** One attribution line per source present on the page (Valve's terms: plain followed links, no nofollow). */
export function Attribution({ rows }: { rows: DirEntry[] }) {
  const keys = [...new Set(rows.map((r) => r.attribution).filter((k): k is string => !!k))].sort();
  const lines = keys.map((k) => attributionForKey(k)).filter((a): a is NonNullable<typeof a> => !!a);
  return (
    <div className="space-y-1 text-[11.5px] leading-relaxed text-tx-faint" data-attributions>
      {lines.map((a) => <p key={a.key} data-attrib={a.key}>{a.text} <a href={a.url} rel="noopener" target="_blank" className="font-semibold text-brand-300 hover:text-white">{a.linkLabel}</a></p>)}
      <p>Server details come from server owners or public server lists and may be out of date. Nxeon runs only the servers marked Hosted on Nxeon. To have a server removed, email <a href="mailto:abuse@nxeon.cloud" className="font-semibold text-brand-300 hover:text-white">abuse@nxeon.cloud</a>.</p>
    </div>
  );
}

export { fmt, plural };

