import Link from "next/link";
import { notFound, permanentRedirect } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { GAME_FAMILIES, GAME_GENRES, type GameFamily } from "@/lib/games";
import { directoryContext, directoryFacets, listExternal, nxeonFor } from "@/lib/directory-query";
import { regionCountries, resolveRegionSlug, type Region } from "@/lib/directory-regions";
import { continentTabs, gameIntro, nearestAlternatives, regionIntro, regionTally, topCountries, type Tally } from "@/lib/directory-seo";
import { isFiltered, pDir, pGame, pRegion, qs, readFilters } from "@/lib/directory-view";
import { deployHref } from "@/lib/deploy-intent";
import { sellable } from "@/app/nxm/_data/directory-hub";
import { artMap, favouriteIds, ownServers } from "@/lib/directory-portal-data";
import { Attribution, CardGrid, CountryChips, DirHero, EmptyState, GameTile, Pager, Panel, RegionTabs, fmt, plural } from "./DirBits";
import { FilterBar } from "./DirClient";

const isGame = (g: string) => (GAME_FAMILIES as readonly string[]).includes(g);

/**
 * One game (optionally one continent or country) in the portal directory: region tabs with counts, country chips,
 * URL-synced search/players/sort, Nxeon-hosted servers pinned on page 1, then the third-party set paged in SQL
 * (24 per page). Same queries as the public /game-servers/directory/<game>[/<region>] pages.
 */
export async function GameListView({ params, searchParams }: { params: { game: string; region?: string }; searchParams: Record<string, string | string[] | undefined> }) {
  const user = await requireUser();
  const game = String(params.game ?? "");
  if (!isGame(game)) {
    if (isGame(game.toLowerCase())) permanentRedirect(params.region ? pRegion(game.toLowerCase(), params.region) : pGame(game.toLowerCase()));
    notFound();
  }
  let region: Region | null = null;
  if (params.region !== undefined) {
    const r = resolveRegionSlug(String(params.region));
    if (!r) notFound();
    if ("redirect" in r) permanentRedirect(pRegion(game, r.redirect));
    region = r.region;
  }
  const filters = readFilters(searchParams);
  const countries = region ? regionCountries(region) : null;
  const [c, f, sell, ext, nxAll, favs, own] = await Promise.all([
    directoryContext(), directoryFacets(), sellable(),
    listExternal({ game, countries, q: filters.q, players: filters.players, sort: filters.sort, page: filters.page }),
    nxeonFor(game, countries), favouriteIds(user.id), ownServers(user.id),
  ]);
  const q = filters.q?.toLowerCase();
  const nx = q ? nxAll.filter((e) => `${e.name} ${e.address}`.toLowerCase().includes(q)) : nxAll;
  if (filters.page > 1 && !ext.rows.length) notFound();
  const rows = filters.page === 1 ? [...nx, ...ext.rows] : ext.rows;
  const total = ext.total + nx.length;
  const g = f.games.get(game);
  const t: Tally = region ? regionTally(f, game, region) : (g ?? { n: 0, p: 0, newest: 0 });
  const art = artMap([game, ...rows.map((r) => r.game)]);
  const name = art[game].name;
  const base = region ? pRegion(game, region.slug) : pGame(game);
  const keep = { q: filters.q, players: filters.players, sort: filters.sort };
  const hrefFor = (r: Region | null) => (r ? pRegion(game, r.slug) : pGame(game)) + qs(keep);
  const hosted = sell.has(game);
  const ownIds = new Set(own.map((o) => o.publicId).filter((x): x is string => !!x));
  const ctx = { art, favs, ownIds, now: Date.now() };
  const within = region?.kind === "continent" ? region.code : region?.kind === "country" ? region.continent : undefined;
  const ncountries = region?.kind === "country" ? 1 : region ? topCountries(f, game, 999, region.code).length : g?.countries.size ?? 0;
  const alts = region ? nearestAlternatives(f, game, region).map((x) => ({ label: x.region.label, href: pRegion(game, x.region.slug), n: x.t.n })) : [];
  const others = [...GAME_FAMILIES].filter((x) => x !== game && (f.games.get(x)?.n ?? 0) > 0 && (GAME_GENRES[x] ?? []).some((gg) => (GAME_GENRES[game as GameFamily] ?? []).includes(gg)))
    .sort((a, b) => f.games.get(b)!.n - f.games.get(a)!.n).slice(0, 6);
  const otherArt = artMap(others);
  const deploy = hosted ? <Link href={deployHref({ service: "game", gameFamily: game })} className="nx-cta inline-flex h-[42px] items-center px-5 text-[13px]">Deploy a {name} server</Link> : null;

  return (
    <>
      <DirHero
        eyebrow={hosted ? "Server directory" : "Server directory · not hosted by Nxeon"}
        title={region ? `${name} servers in` : name} accent={region ? region.label : "servers"}
        sub={region ? regionIntro(name, region, t, f, game) : gameIntro(name, f, game)}
        art={art[game].hero}
        crumbs={[{ name: "Directory", href: pDir() }, { name, href: pGame(game) }, ...(region ? [{ name: region.label }] : [])]}
        stats={[[fmt(t.n), t.n === 1 ? "server listed" : "servers listed"], [fmt(t.p), "playing at last refresh"],
          ...(region?.kind === "country" ? [] : [[fmt(ncountries), ncountries === 1 ? "country" : "countries"] as [string, string]]),
          ...(nxAll.length ? [[fmt(nxAll.length), "on Nxeon"] as [string, string]] : [])]}
        action={deploy}
      />

      <section aria-labelledby="results" className="flex flex-col gap-3.5">
        <RegionTabs tabs={continentTabs(f, game)} all={g?.n ?? 0} active={region} hrefFor={hrefFor} />
        <CountryChips list={topCountries(f, game, 16, within)} active={region} hrefFor={(r) => hrefFor(r)} />
        {(t.n > 0 || isFiltered(filters)) && <FilterBar filters={filters} placeholder={`Search ${name} servers by name, map or address`} />}
        <p id="results" aria-live="polite" className="text-[12.5px] text-tx-faint">
          <span className="num font-semibold text-white/85">{fmt(total)}</span> {total === 1 ? "server" : "servers"}{isFiltered(filters) ? " match these filters" : ""}
          {filters.page > 1 ? `, page ${filters.page}` : ""}
        </p>
        {ext.error && <p role="status" className="rounded-[10px] border border-amber-400/30 bg-amber-400/10 px-3 py-2 text-[12px] text-amber-200">Couldn&apos;t load the full list right now; showing what we could.</p>}
        {rows.length ? <CardGrid rows={rows} ctx={ctx} /> : (
          <EmptyState
            title={t.n ? "No servers match" : region ? `No ${name} servers in ${region.label}` : `No ${name} servers listed yet`}
            text={t.n ? "Nothing matches these filters. Clear them, or try a neighbouring region."
              : region ? `No public ${name} servers are listed in ${region.label} right now.`
              : `${name} has no public server list Nxeon can use, so its servers appear here when their owner hosts one on Nxeon and lists it, or submits and verifies their own server.`}
            alts={alts}
            cta={<div className="flex flex-wrap justify-center gap-2">{deploy}<Link href="/dashboard/directory/list" className="chip h-[42px] px-4">List your server</Link></div>}
          />
        )}
        <Pager base={base} filters={filters} total={ext.total} />
      </section>

      {others.length > 0 && (
        <Panel id="others" title={`More games like ${name}`} lede="Same genre, with servers listed.">
