export const dynamic = "force-dynamic";

import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { ToolsAurora } from "@/components/nx/ToolsAurora";
import { GAME_FAMILIES } from "@/lib/games";
import { pickFeatured, type DirEntry } from "@/lib/server-directory";
import { directoryContext, directoryFacets, listExternal, nxeonFor } from "@/lib/directory-query";
import { continentOf } from "@/lib/geo-continent";
import { continentRegion, countryRegion, regionCountries, resolveRegionSlug, type Region } from "@/lib/directory-regions";
import { continentTabs, topCountries } from "@/lib/directory-seo";
import { pDir, pFavourites, pGame, pGames, pList, pServer, qs, readFilters } from "@/lib/directory-view";
import { sellable, visitorCountry } from "@/app/nxm/_data/directory-hub";
import { artMap, listFavourites, ownServers, resolveFavourites, type OwnServer } from "@/lib/directory-portal-data";
import { Attribution, CardGrid, CountryChips, DirHero, EmptyState, GameTile, MiniList, MoreLink, Pager, Panel, RegionTabs, fmt, plural, type CardCtx } from "@/components/nx/directory/DirBits";
import { FilterBar } from "@/components/nx/directory/DirClient";

export const metadata = { title: "Server Directory", robots: { index: false } };

/**
 * The server directory inside the portal. Same data layer as the public /game-servers/directory pages
 * (lib/directory-query.ts: SQL paging + facets, Nxeon-hosted merge, blocklist, liveness), so the portal can never
 * show something the public page hides. On top: the customer's own servers and their listing state, and
 * favourites saved to the account. `?q=` / `?region=` turn the home into a cross-game result list.
 */
type P = { searchParams: Promise<Record<string, string | string[] | undefined>> };

export default async function DirectoryHome({ searchParams }: P) {
  const user = await requireUser();
  const sp = await searchParams;
  const filters = readFilters(sp);
  const rr = typeof sp.region === "string" ? resolveRegionSlug(sp.region) : null;
  const region: Region | null = rr && "region" in rr ? rr.region : null;
  const [c, f, sell, geo, own, favRows] = await Promise.all([directoryContext(), directoryFacets(), sellable(), visitorCountry(), ownServers(user.id), listFavourites(user.id, 200)]);
  const favs = new Set(favRows.map((x) => x.serverId));
  const ownIds = new Set(own.map((o) => o.publicId).filter((x): x is string => !!x));
  const art = artMap(GAME_FAMILIES);
  const ctx: CardCtx = { art, favs, ownIds, now: Date.now() };
  const gamesWith = [...f.games.values()].filter((g) => g.n > 0);

  const hero = (
    <DirHero eyebrow="Tools" title="Server" accent="Directory"
      sub="Public game servers from around the world: the ones hosted on Nxeon and others found on public server lists. Pick a game or a region, copy the address and join."
      stats={[[fmt(f.total.n), "servers listed"], [fmt(gamesWith.length), "games with servers"], [fmt(f.countries.size), "countries"], [fmt(f.total.p), "playing at last refresh"]]}
      action={<Link href={pList()} className="nx-cta inline-flex h-[42px] items-center px-5 text-[13px]">List your server</Link>} />
  );

  // ── cross-game results (search / region) ──
  if (filters.q || region) {
    const countries = region ? regionCountries(region) : null;
    const [ext, nx] = await Promise.all([listExternal({ q: filters.q, countries, players: filters.players, sort: filters.sort, page: filters.page }), nxeonFor(null, countries)]);
    const q = filters.q?.toLowerCase();
    const nxm = q ? nx.filter((e) => `${e.name} ${e.address}`.toLowerCase().includes(q)) : nx;
    const rows = filters.page === 1 ? [...nxm, ...ext.rows] : ext.rows;
    const total = ext.total + nxm.length;
    const extra: Record<string, string> = region ? { region: region.slug } : {};
    return (
      <Frame>
        {hero}
        <section aria-labelledby="results" className="flex flex-col gap-3.5">
          <h2 className="text-[18px] font-extrabold text-white">{filters.q ? `Servers matching "${filters.q}"${region ? ` in ${region.label}` : ""}` : `Servers in ${region!.label}`}</h2>
          <RegionTabs tabs={continentTabs(f, null)} all={f.total.n} active={region} hrefFor={(r) => pDir() + qs({ q: filters.q }, r ? { region: r.slug } : {})} />
          <FilterBar filters={filters} placeholder="Server name, map or address" extra={extra} />
          <p id="results" aria-live="polite" className="text-[12.5px] text-tx-faint"><span className="num font-semibold text-white/85">{fmt(total)}</span> {total === 1 ? "server" : "servers"} across every game. Open a game to filter by country.</p>
          {rows.length ? <CardGrid rows={rows} ctx={ctx} /> : <EmptyState title="No servers match" text="Try a shorter search, another region, or browse by game."
            alts={continentTabs(f, null).slice(0, 3).map((t) => ({ label: t.region.label, href: pDir() + qs({}, { region: t.region.slug }), n: t.t.n }))} />}
          <Pager base={pDir()} filters={filters} total={ext.total} extra={extra} />
        </section>
        <Attribution rows={rows} />
      </Frame>
    );
  }

  // ── home sections ──
  const near: Region | null = geo
    ? (f.countries.get(geo)?.n ? countryRegion(geo) : continentOf(geo) && f.continents.get(continentOf(geo)!)?.n ? continentRegion(continentOf(geo)!) : null)
    : null;
  const [nearRows, busy, fresh] = await Promise.all([
    near ? listExternal({ countries: regionCountries(near), sort: "players", page: 1 }) : Promise.resolve(null),
    listExternal({ sort: "players", page: 1 }),
    listExternal({ sort: "newest", page: 1 }),
  ]);
  const featured = (pickFeatured(c.nxeon, 8).length ? pickFeatured(c.nxeon, 8) : c.nxeon.slice(0, 8));
  const favResolved = await resolveFavourites(favRows.slice(0, 6));
  const order = [...GAME_FAMILIES].filter((g) => (f.games.get(g)?.n ?? 0) > 0).sort((a, b) => (f.games.get(b)!.p - f.games.get(a)!.p) || (f.games.get(b)!.n - f.games.get(a)!.n));
  const tiles = order.length ? order.slice(0, 16) : [...sell].slice(0, 16);
  const tabs = continentTabs(f, null);
