          more={favRows.length ? <MoreLink href={pFavourites()}>All favourites</MoreLink> : undefined}>
          {favResolved.length ? (
            <MiniList rows={favResolved.filter((x) => x.entry).map((x) => x.entry!)} ctx={ctx} />
          ) : <p className="rounded-[12px] border border-dashed border-rim-hi px-4 py-6 text-center text-[12.5px] text-tx-faint">No favourites yet.</p>}
          {favResolved.some((x) => !x.entry) && <p className="mt-2 text-[11.5px] text-tx-faint">{plural(favResolved.filter((x) => !x.entry).length, "saved server")} not listed right now. <Link href={pFavourites()} className="text-brand-300 hover:text-white">See all</Link></p>}
        </Panel>
