        <ul className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-6 2xl:grid-cols-8">{tiles.map((g) => <GameTile key={g} game={g} art={art[g]} t={f.games.get(g)} hosted={sell.has(g)} href={pGame(g)} />)}</ul>
      </Panel>

      {near && nearRows && nearRows.rows.length > 0 && (
        <Panel id="near" title={`Near you: ${near.label}`} lede="Based on the country your connection comes from. Closer servers usually mean lower ping."
          more={<MoreLink href={pDir() + qs({}, { region: near.slug })}>All {fmt(nearRows.total)} in {near.label}</MoreLink>}>
          <CardGrid rows={nearRows.rows.slice(0, 8)} ctx={ctx} />
        </Panel>
