export const dynamic = "force-dynamic";

import Link from "next/link";
import { notFound, permanentRedirect } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { ToolsAurora } from "@/components/nx/ToolsAurora";
import { CountryFlag } from "@/components/ui/CountryFlag";
import { GamePublicListing } from "@/components/customer/gamepanel/GamePublicListing";
import { parseServerId } from "@/lib/directory-ids";
import { findServer, listExternal } from "@/lib/directory-query";
import { countryName, countryRegion, regionCountries } from "@/lib/directory-regions";
import { factualLine, pDir, pGame, pList, pRegion, pServer } from "@/lib/directory-view";
import { deployHref } from "@/lib/deploy-intent";
import { sellable } from "@/app/nxm/_data/directory-hub";
import { artMap, favouriteIds, ownServers, ownsEntry } from "@/lib/directory-portal-data";
import { Attribution, Badge, CardGrid, Crumbs, Freshness, Panel, Players, ServerArt, fmt } from "@/components/nx/directory/DirBits";
import { CopyButton, FavButton } from "@/components/nx/directory/DirClient";

type P = { params: Promise<{ id: string }> };

export async function generateMetadata({ params }: P) {
  const id = parseServerId((await params).id);
  const e = id ? await findServer(id.game, id.hash).catch(() => null) : null;
  return { title: e ? `${e.name.slice(0, 60)} · Server Directory` : "Server · Server Directory", robots: { index: false } };
}

/**
 * One server inside the portal: connect (copy / Steam link), live players and freshness, map and version, the
 * owner's own text or a factual line built only from stored fields, similar servers nearby, and, when the server
 * is the signed-in customer's own, its listing controls (the same Public Directory card as the game panel).
 */
export default async function ServerDetail({ params }: P) {
  const user = await requireUser();
  const raw = (await params).id;
  const id = parseServerId(raw);
  if (!id) notFound();
  if (raw !== `${id.game}-${id.hash}`) permanentRedirect(pServer(`${id.game}-${id.hash}`));
  const e = await findServer(id.game, id.hash);
  if (!e) notFound();
  const near = e.country ? countryRegion(e.country) : null;
  const [favs, own, sell, simRes] = await Promise.all([
    favouriteIds(user.id), ownServers(user.id), sellable(),
    listExternal({ game: e.game, countries: near ? regionCountries(near) : null, page: 1 }),
  ]);
  const mine = ownsEntry(own, e);
  const sim = simRes.rows.filter((x) => x.publicId !== e.publicId).slice(0, 4);
  const art = artMap([e.game, ...sim.map((x) => x.game)]);
  const name = art[e.game].name;
  const about = e.description || e.tagline || factualLine(e);
  const steamLink = e.attribution === "steam" && /^\d{1,3}(\.\d{1,3}){3}:\d+$/.test(e.address) ? `steam://connect/${e.address}` : null;
  const facts: [string, React.ReactNode][] = [
    ["Game", <Link key="g" href={pGame(e.game)} className="text-brand-300 hover:text-white">{name}</Link>],
    ...(e.country ? [["Location", <span key="c" className="inline-flex items-center gap-1.5"><CountryFlag code={e.country} size={14} />{countryName(e.country)}</span>] as [string, React.ReactNode]]
      : e.region ? [["Location", e.region] as [string, React.ReactNode]] : []),
    ...(e.map ? [["Map", e.map] as [string, React.ReactNode]] : []),
    ...(e.version ? [["Version", e.version] as [string, React.ReactNode]] : []),
    ...(e.maxPlayers ? [["Slots", fmt(e.maxPlayers)] as [string, React.ReactNode]] : []),
    ["Listed by", e.nxeon ? "Its owner, hosted on Nxeon" : e.attribution === "owner" ? "Its owner (verified)" : e.attribution === "steam" ? "Found on the Steam server list" : "Found on a public server list"],
    ...(e.firstSeenAt ? [["In the directory since", new Date(e.firstSeenAt).toISOString().slice(0, 10)] as [string, React.ReactNode]] : []),
  ];

  return (
    <>
      <ToolsAurora />
      <div className="relative z-[1] mx-auto flex w-full max-w-[1280px] flex-col gap-5">
        <Crumbs trail={[{ name: "Directory", href: pDir() }, { name, href: pGame(e.game) }, ...(near ? [{ name: near.label, href: pRegion(e.game, near.slug) }] : []), { name: e.name }]} />

        <article aria-labelledby="srv-name" className="overflow-hidden rounded-[20px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.55),rgba(2,7,20,.7))]">
          <div className="relative">
            <ServerArt e={e} art={art[e.game]} tall />
            <div className="nx-dark-island absolute inset-x-5 bottom-4 flex flex-wrap items-end gap-3">
              <div className="min-w-0 flex-1">
                <div className="mb-1.5 flex flex-wrap gap-1.5"><Badge e={e} own={!!mine} /></div>
                <h1 id="srv-name" className="break-words text-[24px] font-extrabold leading-tight tracking-[-0.02em] text-white sm:text-[30px]">{e.name}</h1>
              </div>
            </div>
          </div>
          <div className="flex flex-col gap-4 p-5">
            <div className="flex flex-wrap items-center gap-2.5">
              <code className="min-w-0 max-w-full flex-1 truncate rounded-[11px] border border-rim-hi bg-well px-3.5 py-2.5 font-mono text-[14px] text-white sm:flex-none">{e.address}</code>
              <CopyButton text={e.address} label="Copy the server address" big />
              {steamLink && <a href={steamLink} rel="nofollow" className="nx-cta inline-flex h-[40px] items-center px-4 text-[13px]">Connect with Steam</a>}
              {e.publicId && <FavButton serverId={e.publicId} saved={favs.has(e.publicId)} name={e.name} big />}
            </div>
            <div className="flex flex-wrap items-center gap-x-5 gap-y-2">
              <span className="min-w-[180px]"><Players e={e} /></span>
              <Freshness e={e} />
            </div>
          </div>
        </article>

        <div className="grid gap-4 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]">
          <Panel id="about" title="About this server">
            <p className="whitespace-pre-line break-words text-[13.5px] leading-relaxed text-tx-body">{about}</p>
            <p className="mt-3 text-[11.5px] leading-relaxed text-tx-faint">
              {e.nxeon ? "This server is hosted on Nxeon and listed by its owner."
                : e.attribution === "owner" ? "Listed by its owner, who proved control of the server. Nxeon does not run it."
                : "Nxeon does not run this server; details may be out of date."}
            </p>
          </Panel>
          <Panel id="facts" title="Details">
            <dl className="grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-2 text-[12.5px]">
              {facts.map(([k, v]) => <div key={k} className="contents"><dt className="text-tx-faint">{k}</dt><dd className="min-w-0 break-words text-tx-body">{v}</dd></div>)}
            </dl>
            <div className="mt-4 flex flex-wrap gap-2">
              <Link href={pGame(e.game)} className="chip h-[34px]">All {name} servers</Link>
              {near && <Link href={pRegion(e.game, near.slug)} className="chip h-[34px]">{name} in {near.label}</Link>}
            </div>
          </Panel>
        </div>

        {mine && (
          <Panel id="manage" title="Your listing" lede="This is your server. Changes here show in the directory within a minute.">
            {mine.kind === "paid" ? <GamePublicListing serverId={mine.id} connectAddress={mine.address} />
              : <p className="text-[12.5px] text-tx-dim">Free Minecraft servers are listed from their own page. <Link href="/dashboard/free-minecraft" className="font-semibold text-brand-300 hover:text-white">Open the free server</Link></p>}
          </Panel>
        )}

        {sim.length > 0 && (
          <Panel id="similar" title={near ? `Similar servers in ${near.label}` : `More ${name} servers`} more={<Link href={near ? pRegion(e.game, near.slug) : pGame(e.game)} className="text-[12.5px] font-semibold text-brand-300 hover:text-white">See all →</Link>}>
            <CardGrid rows={sim} ctx={{ art, favs, now: Date.now() }} />
          </Panel>
        )}

        {!mine && (
          <div className="flex flex-wrap items-center gap-3 rounded-[16px] border border-rim-hi bg-well px-4 py-3.5">
            <p className="min-w-[200px] flex-1 text-[12.5px] text-tx-dim">{sell.has(e.game) ? `Want your own ${name} server? Deploy one on Nxeon and list it here.` : `Run a ${name} server? Submit it and verify you own it to list it here.`}</p>
            {sell.has(e.game) && <Link href={deployHref({ service: "game", gameFamily: e.game })} className="nx-cta inline-flex h-[38px] items-center px-4 text-[12.5px]">Deploy a {name} server</Link>}
            <Link href={pList()} className="chip h-[38px] px-4">List your server</Link>
          </div>
        )}
        <Attribution rows={[e, ...sim]} />
      </div>
    </>
  );
}

