export const dynamic = "force-dynamic";

import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { ToolsAurora } from "@/components/nx/ToolsAurora";
import { artMap, listFavourites, ownServers, resolveFavourites, MAX_FAVOURITES } from "@/lib/directory-portal-data";
import { pDir } from "@/lib/directory-view";
import { Attribution, CardGrid, DirHero, EmptyState, Panel, fmt } from "@/components/nx/directory/DirBits";
import { CopyButton, FavButton } from "@/components/nx/directory/DirClient";

export const metadata = { title: "Favourites · Server Directory", robots: { index: false } };

/** Saved servers, stored on the account (DirectoryFavourite), resolved against the live directory. */
export default async function Favourites() {
  const user = await requireUser();
  const [favs, own] = await Promise.all([listFavourites(user.id), ownServers(user.id)]);
  const resolved = await resolveFavourites(favs);
  const live = resolved.filter((x) => x.entry).map((x) => x.entry!);
  const gone = resolved.filter((x) => !x.entry);
  const art = artMap(live.map((e) => e.game));
  const ids = new Set(favs.map((f) => f.serverId));
  const ownIds = new Set(own.map((o) => o.publicId).filter((x): x is string => !!x));
  return (
    <>
      <ToolsAurora />
      <div className="relative z-[1] mx-auto flex w-full max-w-[1520px] flex-col gap-5">
