/**
 * Server-supplied text (Minecraft MOTDs, Bedrock MOTDs, A2S names) made safe to store and show. PURE, client-safe.
 *
 * Rendered only as plain text (React escaping), never as HTML or markdown, so this is about honesty and abuse, not
 * XSS: formatting codes and invisible characters out, links/addresses/invites out (we show our own join info, and
 * a MOTD is a classic place to advertise elsewhere or phish), whitespace collapsed, length bounded.
 */
const ZERO_WIDTH_BIDI = /[​-‏‪-‮⁠-⁤⁦-⁩﻿]/g;
const CONTROLS = /[\u0000-\u0008\u000B-\u001F\u007F-\u009F]/g;
const MC_CODES = /[§&][0-9a-fk-orx]/gi;
const URLS = /\b(?:https?:\/\/|www\.)\S+/gi;
const DISCORD = /\b(?:discord(?:app)?\.(?:gg|com|io|me)|dsc\.gg)\/\S+/gi;
const EMAILS = /\b[\w.+-]+@[\w-]+(?:\.[\w-]+)+\b/g;
const IPS = /\b\d{1,3}(?:\.\d{1,3}){3}(?::\d{1,5})?\b/g;
const DOMAINS = /\b(?:[a-z0-9-]+\.)+(?:com|net|org|gg|io|me|co|uk|de|fr|eu|us|xyz|club|fun|pro|online|site|store|shop|tv|cc|ru|br|pl|nl|es|it|ca|au)\b(?::\d{1,5})?/gi;

/** A Minecraft chat component (string | {text, extra, translate} | array) flattened to plain text. */
export function flattenChat(d: unknown, depth = 0): string {
  if (depth > 8 || d == null) return "";
  if (typeof d === "string") return d;
  if (Array.isArray(d)) return d.slice(0, 64).map((x) => flattenChat(x, depth + 1)).join("");
  if (typeof d === "object") {
    const o = d as { text?: unknown; translate?: unknown; extra?: unknown };
    const own = typeof o.text === "string" ? o.text : typeof o.translate === "string" ? o.translate : "";
    return own + (Array.isArray(o.extra) ? flattenChat(o.extra, depth + 1) : "");
  }
  return "";
}

/** Strip formatting/invisible characters only (for names, where links are rare and the full text matters). */
export function cleanServerText(raw: string, max = 120): string {
  return String(raw ?? "").normalize("NFC").replace(MC_CODES, "").replace(ZERO_WIDTH_BIDI, "").replace(CONTROLS, " ")
    .replace(/\s+/g, " ").trim().slice(0, max).trim();
}

/** A MOTD / description as a short plain-text paragraph, or null when nothing worth showing is left. */
export function sanitizeMotd(raw: unknown, max = 280): string | null {
  const flat = typeof raw === "string" ? raw : flattenChat(raw);
  let s = flat.normalize("NFC").replace(MC_CODES, "").replace(ZERO_WIDTH_BIDI, "")
    .replace(/<[^>]{0,200}>/g, " ").replace(/\[\/?[a-z]{1,10}(?:=[^\]]{0,40})?\]/gi, " ")
    .replace(CONTROLS, " ");
  s = s.replace(URLS, " ").replace(DISCORD, " ").replace(EMAILS, " ").replace(IPS, " ").replace(DOMAINS, " ");
  s = s.replace(/(\p{Extended_Pictographic}️?){4,}/gu, "").replace(/[ \t]+/g, " ").replace(/\s*\n\s*/g, "\n").replace(/\n{2,}/g, "\n").trim();
  if (s.replace(/[^\p{L}\p{N}]/gu, "").length < 3) return null;
  if (s.length > max) { const cut = s.slice(0, max); const sp = cut.lastIndexOf(" "); s = (sp > max * 0.6 ? cut.slice(0, sp) : cut).trim() + "…"; }
  return s;
}

/** Case-insensitive presence of a verification token in text the server reports (formatting codes ignored). */
export function containsToken(text: string | null | undefined, token: string): boolean {
  if (!text || !token) return false;
  const norm = (x: string) => x.replace(MC_CODES, "").replace(ZERO_WIDTH_BIDI, "").toLowerCase();
  return norm(text).includes(norm(token));
}

