import net from "node:net";
import dgram from "node:dgram";
import { promises as dnsp } from "node:dns";
import { isIpv4 } from "@/lib/server-directory";
import { isPublicIpv4, isProbeablePort } from "@/lib/directory-liveness";
import { flattenChat } from "@/lib/directory-text";

/**
 * Minecraft status queries for the DIRECTORY (enrichment + owner verification), hardened for addresses we did not
 * choose ourselves (owner submissions, third-party rows):
 *
 *   Java   Server List Ping: TCP handshake (next state = status) + status request. The reply is the JSON a vanilla
 *          client draws in its server list: MOTD, version name/protocol, player counts, optional 64x64 favicon.
 *          The `players.sample` list (player NAMES) is never read.
 *   Bedrock RakNet unconnected ping: one UDP datagram, a semicolon-separated pong (edition, MOTD, protocol, version,
 *          online, max, ...).
 *
 * Safety: hostnames are resolved HERE (Java honours the `_minecraft._tcp` SRV record, as the client does), and
 * EVERY resolved address must be public IPv4 or nothing is sent (no probing our own network or RFC1918 space via
 * a crafted DNS name). Ports < 1024 and service ports are refused. Each query is one exchange with a hard timeout
 * and a byte cap on the reply; nothing is retried. Callers rate-limit (the prober's per-IP chain and global rate,
 * or the per-user limit on "Verify").
 */
export const STATUS_TIMEOUT_MS = 2500;
/** Biggest SLP reply we buffer (a favicon is ~10-20 KB of base64; big modpacks list mods in `forgeData`). */
export const SLP_MAX_BYTES = 256 * 1024;

export type McStatus = { online: number; max: number | null; motd: string | null; version: string | null; protocol: number | null; hasFavicon: boolean; edition: "java" | "bedrock" };
export type Resolved = { ip: string; port: number } | { error: "not-public" | "unresolved" | "bad-port" };

type Resolver = { resolve4(h: string): Promise<string[]>; resolveSrv(h: string): Promise<{ name: string; port: number }[]> };
const sysResolver: Resolver = { resolve4: (h) => dnsp.resolve4(h), resolveSrv: (h) => dnsp.resolveSrv(h) };

/** Address -> one public IPv4 + port. `srv` = follow `_minecraft._tcp.<host>` first (Java only). */
export async function resolvePublic(host: string, port: number, opts: { srv?: boolean; resolver?: Resolver } = {}): Promise<Resolved> {
  const r = opts.resolver ?? sysResolver;
  let target = host, p = port;
  if (!isIpv4(host) && opts.srv) {
    try {
      const recs = await r.resolveSrv(`_minecraft._tcp.${host}`);
      if (recs[0]?.name && recs[0].port) { target = recs[0].name.replace(/\.$/, ""); p = recs[0].port; }
    } catch { /* no SRV record: connect to the host itself */ }
  }
  if (!isProbeablePort(p)) return { error: "bad-port" };
  if (isIpv4(target)) return isPublicIpv4(target) ? { ip: target, port: p } : { error: "not-public" };
  let ips: string[] = [];
  try { ips = await r.resolve4(target); } catch { return { error: "unresolved" }; }
  if (!ips.length) return { error: "unresolved" };
  if (!ips.every(isPublicIpv4)) return { error: "not-public" };
  return { ip: ips[0], port: p };
}

// ── Java SLP ───────────────────────────────────────────────────────────────
const varInt = (n: number) => { const out: number[] = []; let v = n >>> 0; do { let b = v & 0x7f; v >>>= 7; if (v) b |= 0x80; out.push(b); } while (v); return Buffer.from(out); };
export function readVarInt(buf: Buffer, at: number): { value: number; size: number } | null {
  let value = 0, size = 0;
  for (;;) {
    if (at + size >= buf.length || size >= 5) return null;
    const b = buf[at + size];
    value |= (b & 0x7f) << (7 * size); size++;
    if (!(b & 0x80)) return { value, size };
  }
}
const pkt = (id: number, body: Buffer) => { const p = Buffer.concat([varInt(id), body]); return Buffer.concat([varInt(p.length), p]); };

/** The two packets a client sends to ask for status. `host` goes in the handshake (virtual-hosted networks route on it). */
export function slpRequest(host: string, port: number): Buffer {
  const h = Buffer.from(host.slice(0, 255), "utf8");
  return Buffer.concat([pkt(0x00, Buffer.concat([varInt(767), varInt(h.length), h, Buffer.from([(port >> 8) & 0xff, port & 0xff]), varInt(1)])), pkt(0x00, Buffer.alloc(0))]);
}

/** Parse a complete status-response frame; "partial" while more bytes are needed, null when it is not one. */
export function parseSlpFrame(buf: Buffer): McStatus | "partial" | null {
  const len = readVarInt(buf, 0);
  if (!len) return buf.length >= 5 ? null : "partial";
  if (len.value <= 0 || len.value > SLP_MAX_BYTES) return null;
  if (buf.length < len.size + len.value) return "partial";
  let at = len.size;
  const id = readVarInt(buf, at); if (!id || id.value !== 0) return null; at += id.size;
  const sl = readVarInt(buf, at); if (!sl) return null; at += sl.size;
  if (at + sl.value > buf.length) return null;
  return parseSlpJson(buf.subarray(at, at + sl.value).toString("utf8"));
}

const int = (v: unknown, cap = 10_000_000): number | null => (typeof v === "number" && Number.isFinite(v) && v >= 0 && v <= cap ? Math.floor(v) : null);

/** The status JSON -> what the directory keeps. Player samples (names) are ignored on purpose. */
export function parseSlpJson(text: string): McStatus | null {
  let j: { version?: { name?: unknown; protocol?: unknown }; players?: { online?: unknown; max?: unknown }; description?: unknown; favicon?: unknown };
  try { j = JSON.parse(text); } catch { return null; }
  if (!j || typeof j !== "object") return null;
  const online = int(j.players?.online);
  if (online === null) return null;
  const motd = flattenChat(j.description).trim();
  const version = typeof j.version?.name === "string" ? j.version.name.replace(/§./g, "").trim().slice(0, 40) || null : null;
  return {
    online, max: int(j.players?.max), motd: motd || null, version, protocol: int(j.version?.protocol, 1_000_000),
    hasFavicon: typeof j.favicon === "string" && /^data:image\/png;base64,/.test(j.favicon), edition: "java",
  };
}

/** One SLP exchange with a public IP (connect) and the advertised hostname (handshake). */
export function slpStatus(ip: string, port: number, handshakeHost: string, timeoutMs = STATUS_TIMEOUT_MS): Promise<McStatus | null> {
  if (!isPublicIpv4(ip) || !isProbeablePort(port)) return Promise.resolve(null);
  return new Promise((resolve) => {
    const sock = net.createConnection({ host: ip, port });
    let buf = Buffer.alloc(0), settled = false;
    const done = (v: McStatus | null) => { if (settled) return; settled = true; clearTimeout(t); sock.destroy(); resolve(v); };
    const t = setTimeout(() => done(null), timeoutMs);
    t.unref?.();
    sock.on("error", () => done(null));
    sock.on("close", () => done(null));
    sock.on("connect", () => sock.write(slpRequest(handshakeHost, port)));
    sock.on("data", (d: Buffer) => {
      buf = Buffer.concat([buf, d]);
      if (buf.length > SLP_MAX_BYTES + 16) return done(null);
      const r = parseSlpFrame(buf);
      if (r !== "partial") done(r);
    });
  });
}

// ── Bedrock RakNet ─────────────────────────────────────────────────────────
const MAGIC = Buffer.from("00ffff00fefefefefdfdfdfd12345678", "hex");
export const raknetPing = () => Buffer.concat([Buffer.from([0x01]), Buffer.alloc(8), MAGIC, Buffer.alloc(8)]);

/** ID_UNCONNECTED_PONG -> status. Layout: id(1) time(8) guid(8) magic(16) len(2) "MCPE;motd;proto;version;online;max;..." */
export function parseRaknetPong(msg: Buffer): McStatus | null {
  if (msg.length < 35 || msg[0] !== 0x1c || !msg.subarray(17, 33).equals(MAGIC)) return null;
  const n = msg.readUInt16BE(33);
  const s = msg.subarray(35, 35 + Math.min(n, 2048)).toString("utf8");
  const f = s.split(";");
  if (f.length < 6 || !/^(MCPE|MCEE)$/.test(f[0])) return null;
  const online = Number(f[4]), max = Number(f[5]);
  if (!Number.isInteger(online) || online < 0 || online > 10_000_000) return null;
  return {
    online, max: Number.isInteger(max) && max >= 0 ? max : null,
    motd: [f[1], f[7]].filter((x) => x && x.trim()).join("\n").trim() || null,
    version: (f[3] || "").trim().slice(0, 40) || null, protocol: Number.isInteger(Number(f[2])) ? Number(f[2]) : null,
    hasFavicon: false, edition: "bedrock",
  };
}

export function raknetStatus(ip: string, port: number, timeoutMs = STATUS_TIMEOUT_MS): Promise<McStatus | null> {
  if (!isPublicIpv4(ip) || !isProbeablePort(port)) return Promise.resolve(null);
  return new Promise((resolve) => {
    const sock = dgram.createSocket("udp4");
    let settled = false;
    const done = (v: McStatus | null) => { if (settled) return; settled = true; clearTimeout(t); try { sock.close(); } catch { /* closed */ } resolve(v); };
    const t = setTimeout(() => done(null), timeoutMs);
    t.unref?.();
    sock.on("error", () => done(null));
    sock.on("message", (m, rinfo) => { if (rinfo.address !== ip) return; const r = parseRaknetPong(m); if (r) done(r); });
    sock.send(raknetPing(), port, ip, (e) => { if (e) done(null); });
  });
}

