    const sock = dgram.createSocket("udp4");
    let settled = false;
    const done = (v: McStatus | null) => { if (settled) return; settled = true; clearTimeout(t); try { sock.close(); } catch { /* closed */ } resolve(v); };
    const t = setTimeout(() => done(null), timeoutMs);
    t.unref?.();
    sock.on("error", () => done(null));
    sock.on("message", (m, rinfo) => { if (rinfo.address !== ip) return; const r = parseRaknetPong(m); if (r) done(r); });
    sock.send(raknetPing(), port, ip, (e) => { if (e) done(null); });
  });
}

