import { randomBytes } from "node:crypto";
import { promises as dnsp } from "node:dns";
import { GAME_FAMILIES, joinPortFor, type GameFamily } from "@/lib/games";
import { QUERY_PROTOCOL, a2sInfo } from "@/lib/server-query";
import { connKey, isIpv4, parseConnection } from "@/lib/server-directory";
import { isProbeablePort } from "@/lib/directory-liveness";
import { cleanServerText, containsToken } from "@/lib/directory-text";
import { raknetStatus, resolvePublic, slpStatus, type McStatus } from "@/lib/directory-ingest/mc-status";

/**
 * Owner-submitted listings for servers NOT hosted on Nxeon: the permitted discovery path for every game with no
 * public server list we may use (Minecraft above all; see /root/agent-notes/portal-directory/SOURCES.md). Pure-ish:
 * network calls are injectable, so verification is unit-tested with fakes.
 *
 * Proof of control, one of (the owner picks; any one is enough):
 *   motd      Minecraft Java / Bedrock: the token appears in the MOTD the server itself reports (SLP / RakNet ping)
 *   a2s-name  Steam-networking games: the token appears in the server NAME A2S_INFO reports
 *   dns       hostname addresses, any game: a TXT record `_nxeon-verify.<host>` containing the token
 * The token can be removed again once verified. Every check is ONE query to an address that resolves only to public
 * IPv4 (mc-status.ts resolvePublic), triggered by the owner's click and rate-limited per account.
 */
export type VerifyMethod = "motd" | "a2s-name" | "dns";
export const TOKEN_PREFIX = "nxeon-";
export const MAX_SUBMISSIONS_PER_USER = 10;
/** DNS-verified rows prove control of the NAME, not that a server answers: they must be re-verified this often. */
export const DNS_REVERIFY_DAYS = 30;

export const newToken = () => TOKEN_PREFIX + randomBytes(5).toString("hex");

/** Which proofs a game supports. Every game gets DNS (hostname addresses); status-query proofs need a protocol. */
export function methodsFor(game: string): VerifyMethod[] {
  const p = QUERY_PROTOCOL[game as GameFamily];
  const out: VerifyMethod[] = [];
  if (p === "mc-java" || p === "bedrock") out.push("motd");
  if (p === "a2s") out.push("a2s-name");
  out.push("dns");
  return out;
}

/** Liveness protocol for a submitted row (the prober's probeKind), or "listing" when the game has none. */
export function probeKindForSubmission(game: string): "slp" | "raknet" | "a2s" | "listing" {
  const p = QUERY_PROTOCOL[game as GameFamily];
  return p === "mc-java" ? "slp" : p === "bedrock" ? "raknet" : p === "a2s" ? "a2s" : "listing";
}

export type ParsedAddress = { game: string; host: string; port: number; connKey: string };

/** Validate what the owner typed. Port defaults to the game's own join port. */
export function parseSubmission(game: string, address: string): ParsedAddress | { error: string } {
  if (!(GAME_FAMILIES as readonly string[]).includes(game)) return { error: "Pick a game from the list." };
  const c = parseConnection(address);
  if (!c) return { error: "Enter an address like play.example.com or 203.0.113.10:25565." };
  const port = c.port ?? joinPortFor(game as GameFamily)?.port ?? 0;
  if (!isProbeablePort(port)) return { error: "That port can't be listed (use the port players join on, 1024 to 65535)." };
  if (/(^|\.)(localhost|local|internal|lan|home|corp)$/.test(c.host)) return { error: "Use the public address players join on." };
  return { game, host: c.host, port, connKey: connKey(game, c.host, port) };
}

export type VerifyDeps = {
  slp?: (ip: string, port: number, host: string) => Promise<McStatus | null>;
  raknet?: (ip: string, port: number) => Promise<McStatus | null>;
  a2s?: (ip: string, port: number) => Promise<{ motd: string | null; online: number; max: number | null } | null>;
  txt?: (name: string) => Promise<string[][]>;
  resolve?: typeof resolvePublic;
};

export type VerifyResult =
  | { ok: true; method: VerifyMethod; ip: string | null; name: string | null; players: number | null; maxPlayers: number | null; version: string | null }
  | { ok: false; error: string; reachable: boolean };

/** One verification attempt. Tries the status-query proof first (it also proves the server is up), then DNS. */
export async function verifyOnce(s: { game: string; host: string; port: number; token: string }, deps: VerifyDeps = {}): Promise<VerifyResult> {
  const methods = methodsFor(s.game);
  const resolve = deps.resolve ?? resolvePublic;
  const proto = QUERY_PROTOCOL[s.game as GameFamily];
  let reachable = false, lastError = "The server didn't answer. Check it is running and the address and port are right.";
  let ip: string | null = null;
  if (methods.includes("motd") || methods.includes("a2s-name")) {
    const r = await resolve(s.host, s.port, { srv: proto === "mc-java" });
    if ("error" in r) {
      lastError = r.error === "not-public" ? "That address points to a private or reserved network, so it can't be listed." : r.error === "bad-port" ? "That port can't be listed." : "That address doesn't resolve.";
      if (r.error === "not-public") return { ok: false, error: lastError, reachable: false };
    } else {
      ip = r.ip;
      if (proto === "mc-java" || proto === "bedrock") {
        const st = proto === "mc-java" ? await (deps.slp ?? slpStatus)(r.ip, r.port, s.host) : await (deps.raknet ?? raknetStatus)(r.ip, r.port);
        if (st) {
          reachable = true;
          if (containsToken(st.motd, s.token)) {
            return { ok: true, method: "motd", ip, name: firstLine(st.motd, s.token), players: st.online, maxPlayers: st.max, version: st.version };
          }
          lastError = `The server answered, but its MOTD doesn't contain ${s.token} yet. Server MOTDs can be cached for a minute: save, restart if needed, then verify again.`;
        }
      } else if (proto === "a2s") {
        const st = await (deps.a2s ?? a2sInfo)(r.ip, r.port);
        if (st) {
          reachable = true;
          if (containsToken(st.motd, s.token)) return { ok: true, method: "a2s-name", ip, name: firstLine(st.motd, s.token), players: st.online, maxPlayers: st.max, version: null };
          lastError = `The server answered, but its name doesn't contain ${s.token} yet.`;
        }
      }
    }
  }
  if (!isIpv4(s.host)) {
    try {
      const recs = await (deps.txt ?? ((n: string) => dnsp.resolveTxt(n)))(`_nxeon-verify.${s.host}`);
      if (recs.some((parts) => parts.join("").trim() === s.token)) {
        return { ok: true, method: "dns", ip, name: null, players: null, maxPlayers: null, version: null };
      }
      if (!reachable) lastError = `No TXT record _nxeon-verify.${s.host} with ${s.token} found yet. DNS changes can take a few minutes.`;
    } catch { /* no record */ }
  }
  return { ok: false, error: lastError, reachable };
}

/** A display name from the reported MOTD/name: first line, token removed, formatting stripped. */
export function firstLine(text: string | null, token: string): string | null {
  if (!text) return null;
  const line = text.split("\n").map((l) => l.replace(new RegExp(token.replace(/[^a-z0-9-]/gi, ""), "ig"), "")).map((l) => cleanServerText(l, 80)).find((l) => l.replace(/[^\p{L}\p{N}]/gu, "").length >= 3);
  return line ?? null;
}

