// ── owner-submitted listings (servers hosted elsewhere) ─────────────────────
import { getSetting, getSettingBool } from "./settings";
import { enableSettingFor, reviewedSettingFor } from "./directory-ingest/providers/types";
import { nxeonConnectionKeys } from "./server-directory-data";
import { MAX_SUBMISSIONS_PER_USER, newToken, parseSubmission, verifyOnce } from "./directory-submissions";
import { recordAudit } from "./audit";

export type SubmitResult = { ok: true; id: string; token: string } | { ok: false; error: string };

/** Submissions are open only when the owner switched the "submitted" source on AND recorded who approved it. */
export async function submissionsOpen(): Promise<boolean> {
  const [on, by] = await Promise.all([getSettingBool(enableSettingFor("submitted"), false).catch(() => false), getSetting(reviewedSettingFor("submitted"), "").catch(() => "")]);
  return on && !!by.trim();
}

export async function submitServer(game: string, address: string): Promise<SubmitResult> {
  const user = await requireUser();
  if (!(await submissionsOpen())) return { ok: false, error: "Listing servers hosted elsewhere isn't open yet." };
  const rl = checkRateLimit(`dir:submit:${user.id}`, { max: 10, windowMs: 3_600_000 });
  if (!rl.ok) return { ok: false, error: `Too many submissions. Try again in ${rl.retryAfterSec}s.` };
  const p = parseSubmission(String(game ?? ""), String(address ?? ""));
  if ("error" in p) return { ok: false, error: p.error };
  try {
    const nx = await nxeonConnectionKeys().catch(() => new Set<string>());
    if (nx.has(p.connKey)) return { ok: false, error: "That server is hosted on Nxeon: list it from its game panel's Settings tab instead." };
    const existing = await db.directorySubmission.findUnique({ where: { userId_connKey: { userId: user.id, connKey: p.connKey } } });
    if (existing && existing.status !== "REMOVED") return { ok: true, id: existing.id, token: existing.token };
    const count = await db.directorySubmission.count({ where: { userId: user.id, status: { not: "REMOVED" } } });
    if (count >= MAX_SUBMISSIONS_PER_USER) return { ok: false, error: `You can submit up to ${MAX_SUBMISSIONS_PER_USER} servers.` };
    const token = newToken();
    const row = existing
      ? await db.directorySubmission.update({ where: { id: existing.id }, data: { status: "PENDING", token, game: p.game, host: p.host, port: p.port, attempts: 0, lastError: null, verifiedAt: null, method: null } })
      : await db.directorySubmission.create({ data: { userId: user.id, game: p.game, host: p.host, port: p.port, connKey: p.connKey, token } });
    await recordAudit(user.id, "directory.submission.create", `submission=${row.id} game=${p.game}`);
    revalidatePath(`${PORTAL_DIR}/list`);
    return { ok: true, id: row.id, token };
  } catch {
    return { ok: false, error: "Could not save. Please try again." };
  }
}

export type VerifyActionResult = { ok: true; method: string } | { ok: false; error: string };

/** One verification attempt for the caller's OWN submission (one status query or one DNS lookup). */
export async function verifySubmission(id: string): Promise<VerifyActionResult> {
  const user = await requireUser();
  if (!(await submissionsOpen())) return { ok: false, error: "Listing servers hosted elsewhere isn't open yet." };
  const rl = checkRateLimit(`dir:verify:${user.id}`, { max: 6, windowMs: 60_000 });
  if (!rl.ok) return { ok: false, error: `Please wait ${rl.retryAfterSec}s before checking again.` };
  const s = await db.directorySubmission.findUnique({ where: { id: String(id ?? "") } });
  if (!s || s.userId !== user.id || s.status === "REMOVED") return { ok: false, error: "Submission not found." };
  const r = await verifyOnce({ game: s.game, host: s.host, port: s.port, token: s.token });
  const now = new Date();
  if (!r.ok) {
    await db.directorySubmission.update({ where: { id: s.id }, data: { attempts: { increment: 1 }, lastCheckAt: now, lastError: r.error.slice(0, 300) } });
    return { ok: false, error: r.error };
  }
  await db.$transaction([
    // Current proof of control wins: anyone else's verified claim on the same address stops listing it.
    db.directorySubmission.updateMany({ where: { connKey: s.connKey, status: "VERIFIED", NOT: { id: s.id } }, data: { status: "REMOVED", lastError: "Another account verified control of this address." } }),
    db.directorySubmission.update({ where: { id: s.id }, data: { status: "VERIFIED", method: r.method, ip: r.ip, name: r.name, verifiedAt: now, lastCheckAt: now, lastError: null, attempts: { increment: 1 } } }),
    db.directorySource.upsert({ where: { key: "submitted" }, create: { key: "submitted", runRequested: true }, update: { runRequested: true } }),
  ]);
  await recordAudit(user.id, "directory.submission.verify", `submission=${s.id} method=${r.method}`);
  revalidatePath(`${PORTAL_DIR}/list`);
  return { ok: true, method: r.method };
}

/** Withdraw the caller's own submission; its directory row is removed at once (not at the next prune). */
export async function removeSubmission(id: string): Promise<{ ok: boolean; error?: string }> {
  const user = await requireUser();
  const s = await db.directorySubmission.findUnique({ where: { id: String(id ?? "") } });
  if (!s || s.userId !== user.id) return { ok: false, error: "Submission not found." };
  await db.$transaction([
    db.directorySubmission.update({ where: { id: s.id }, data: { status: "REMOVED" } }),
    ...(s.status === "VERIFIED" ? [db.externalServer.deleteMany({ where: { source: "submitted", sourceKey: s.connKey } })] : []),
  ]);
  await recordAudit(user.id, "directory.submission.remove", `submission=${s.id}`);
  revalidatePath(`${PORTAL_DIR}/list`);
  return { ok: true };
}
EOF
