56	/** Submissions are open only when the owner switched the "submitted" source on AND recorded who approved it. */
57	export async function submissionsOpen(): Promise<boolean> {
58	  const [on, by] = await Promise.all([getSettingBool(enableSettingFor("submitted"), false).catch(() => false), getSetting(reviewedSettingFor("submitted"), "").catch(() => "")]);
59	  return on && !!by.trim();
60	}
61	
62	export async function submitServer(game: string, address: string): Promise<SubmitResult> {
63	  const user = await requireUser();
64	  if (!(await submissionsOpen())) return { ok: false, error: "Listing servers hosted elsewhere isn't open yet." };
65	  const rl = checkRateLimit(`dir:submit:${user.id}`, { max: 10, windowMs: 3_600_000 });
66	  if (!rl.ok) return { ok: false, error: `Too many submissions. Try again in ${rl.retryAfterSec}s.` };
67	  const p = parseSubmission(String(game ?? ""), String(address ?? ""));
68	  if ("error" in p) return { ok: false, error: p.error };
69	  try {
70	    const nx = await nxeonConnectionKeys().catch(() => new Set<string>());
71	    if (nx.has(p.connKey)) return { ok: false, error: "That server is hosted on Nxeon: list it from its game panel's Settings tab instead." };
72	    const existing = await db.directorySubmission.findUnique({ where: { userId_connKey: { userId: user.id, connKey: p.connKey } } });
73	    if (existing && existing.status !== "REMOVED") return { ok: true, id: existing.id, token: existing.token };
74	    const count = await db.directorySubmission.count({ where: { userId: user.id, status: { not: "REMOVED" } } });
75	    if (count >= MAX_SUBMISSIONS_PER_USER) return { ok: false, error: `You can submit up to ${MAX_SUBMISSIONS_PER_USER} servers.` };
76	    const token = newToken();
77	    const row = existing
78	      ? await db.directorySubmission.update({ where: { id: existing.id }, data: { status: "PENDING", token, game: p.game, host: p.host, port: p.port, attempts: 0, lastError: null, verifiedAt: null, method: null } })
79	      : await db.directorySubmission.create({ data: { userId: user.id, game: p.game, host: p.host, port: p.port, connKey: p.connKey, token } });
80	    await recordAudit(user.id, "directory.submission.create", `submission=${row.id} game=${p.game}`);
81	    revalidatePath(`${PORTAL_DIR}/list`);
82	    return { ok: true, id: row.id, token };
83	  } catch {
84	    return { ok: false, error: "Could not save. Please try again." };
85	  }
86	}
87	
88	export type VerifyActionResult = { ok: true; method: string } | { ok: false; error: string };
89	
90	/** One verification attempt for the caller's OWN submission (one status query or one DNS lookup). */
91	export async function verifySubmission(id: string): Promise<VerifyActionResult> {
92	  const user = await requireUser();
93	  if (!(await submissionsOpen())) return { ok: false, error: "Listing servers hosted elsewhere isn't open yet." };
94	  const rl = checkRateLimit(`dir:verify:${user.id}`, { max: 6, windowMs: 60_000 });
95	  if (!rl.ok) return { ok: false, error: `Please wait ${rl.retryAfterSec}s before checking again.` };
96	  const s = await db.directorySubmission.findUnique({ where: { id: String(id ?? "") } });
97	  if (!s || s.userId !== user.id || s.status === "REMOVED") return { ok: false, error: "Submission not found." };
98	  const r = await verifyOnce({ game: s.game, host: s.host, port: s.port, token: s.token });
99	  const now = new Date();
100	  if (!r.ok) {
101	    await db.directorySubmission.update({ where: { id: s.id }, data: { attempts: { increment: 1 }, lastCheckAt: now, lastError: r.error.slice(0, 300) } });
102	    return { ok: false, error: r.error };
103	  }
104	  await db.$transaction([
105	    // Current proof of control wins: anyone else's verified claim on the same address stops listing it.
106	    db.directorySubmission.updateMany({ where: { connKey: s.connKey, status: "VERIFIED", NOT: { id: s.id } }, data: { status: "REMOVED", lastError: "Another account verified control of this address." } }),
107	    db.directorySubmission.update({ where: { id: s.id }, data: { status: "VERIFIED", method: r.method, ip: r.ip, name: r.name, verifiedAt: now, lastCheckAt: now, lastError: null, attempts: { increment: 1 } } }),
108	    db.directorySource.upsert({ where: { key: "submitted" }, create: { key: "submitted", runRequested: true }, update: { runRequested: true } }),
109	  ]);
110	  await recordAudit(user.id, "directory.submission.verify", `submission=${s.id} method=${r.method}`);
111	  revalidatePath(`${PORTAL_DIR}/list`);
112	  return { ok: true, method: r.method };
113	}
114	
115	/** Withdraw the caller's own submission; its directory row is removed at once (not at the next prune). */
116	export async function removeSubmission(id: string): Promise<{ ok: boolean; error?: string }> {
117	  const user = await requireUser();
118	  const s = await db.directorySubmission.findUnique({ where: { id: String(id ?? "") } });
119	  if (!s || s.userId !== user.id) return { ok: false, error: "Submission not found." };
120	  await db.$transaction([
121	    db.directorySubmission.update({ where: { id: s.id }, data: { status: "REMOVED" } }),
122	    ...(s.status === "VERIFIED" ? [db.externalServer.deleteMany({ where: { source: "submitted", sourceKey: s.connKey } })] : []),
123	  ]);
124	  await recordAudit(user.id, "directory.submission.remove", `submission=${s.id}`);
125	  revalidatePath(`${PORTAL_DIR}/list`);
126	  return { ok: true };
127	}

