"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { removeSubmission, submitServer, verifySubmission } from "@/lib/actions-directory";
import { CopyButton } from "./DirClient";

const field = "h-[42px] rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3.5 text-[13px] text-white outline-none focus:border-brand-400/60";

/** "Submit a server hosted elsewhere": game + address in, a verification token out. */
export function SubmitForm({ games, open }: { games: { key: string; name: string }[]; open: boolean }) {
  const router = useRouter();
  const [game, setGame] = useState("minecraft");
  const [address, setAddress] = useState("");
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [pending, start] = useTransition();
  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    setMsg(null);
    start(async () => {
      const r = await submitServer(game, address);
      if (!r.ok) setMsg({ ok: false, text: r.error });
      else { setMsg({ ok: true, text: "Added. Follow the steps below to verify it." }); setAddress(""); router.refresh(); }
    });
  };
  return (
    <form onSubmit={submit} className="flex flex-col gap-3" aria-describedby="submit-help">
      <div className="flex flex-wrap gap-2.5">
        <label className="flex min-w-[180px] flex-col gap-1 text-[11.5px] font-semibold text-tx-faint">Game
          <select value={game} onChange={(e) => setGame(e.target.value)} className={field + " cursor-pointer"} disabled={!open}>
            {games.map((g) => <option key={g.key} value={g.key}>{g.name}</option>)}
          </select>
        </label>
        <label className="flex min-w-[240px] flex-1 flex-col gap-1 text-[11.5px] font-semibold text-tx-faint">Address players join on
          <input value={address} onChange={(e) => setAddress(e.target.value)} placeholder="play.example.com or 203.0.113.10:25565" maxLength={255} required disabled={!open}
            className={field + " font-mono placeholder:font-sans placeholder:text-tx-faint"} autoComplete="off" spellCheck={false} />
        </label>
        <button type="submit" disabled={!open || pending || !address.trim()} className="nx-cta h-[42px] self-end px-5 text-[13px] disabled:opacity-50">{pending ? "Adding…" : "Add server"}</button>
      </div>
      <p id="submit-help" className="text-[12px] leading-relaxed text-tx-dim">
        {open ? "You'll get a short code to put in your server's MOTD (Minecraft), its server name (Steam games) or a DNS TXT record, so we can confirm the server is yours. You can remove the code once it's verified."
          : "Listing servers hosted elsewhere isn't open yet. Servers you host on Nxeon can be listed right now, above."}
      </p>
      {msg && <p role={msg.ok ? "status" : "alert"} className={"text-[12.5px] " + (msg.ok ? "text-emerald-300" : "text-[#ff8ba6]")}>{msg.text}</p>}
    </form>
  );
}

export type SubmissionView = {
  id: string; game: string; gameName: string; address: string; host: string; status: string; token: string; methods: string[];
  lastError: string | null; verifiedAt: string | null; method: string | null; publicId: string | null; isIp: boolean;
};

/** One of the customer's submissions: how to prove control, Verify and Remove. */
export function SubmissionRow({ s, open }: { s: SubmissionView; open: boolean }) {
  const router = useRouter();
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(s.lastError && s.status !== "VERIFIED" ? { ok: false, text: s.lastError } : null);
  const [pending, start] = useTransition();
  const verified = s.status === "VERIFIED";
  const verify = () => start(async () => {
    setMsg(null);
    const r = await verifySubmission(s.id);
    setMsg(r.ok ? { ok: true, text: "Verified. It appears in the directory within a few minutes." } : { ok: false, text: r.error });
    if (r.ok) router.refresh();
  });
  const remove = () => start(async () => {
    if (!confirm(`Remove ${s.address} from the directory?`)) return;
    const r = await removeSubmission(s.id);
    if (r.ok) router.refresh(); else setMsg({ ok: false, text: r.error ?? "Could not remove." });
  });
  return (
    <li className="flex flex-col gap-3 rounded-[14px] border border-rim-hi bg-well p-4">
      <div className="flex flex-wrap items-center gap-3">
        <span className="min-w-0 flex-1">
          <span className="block truncate font-mono text-[13px] font-bold text-white">{s.address}</span>
          <span className="block text-[11.5px] text-tx-faint">{s.gameName}{verified && s.verifiedAt ? ` · verified ${s.verifiedAt.slice(0, 10)} by ${s.method === "dns" ? "DNS" : s.method === "a2s-name" ? "server name" : "MOTD"}` : ""}</span>
        </span>
        <span className={"rounded-[6px] border px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide " + (verified ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-300" : "border-amber-400/40 bg-amber-400/10 text-amber-200")}>{verified ? "Verified" : "Waiting for verification"}</span>
        {s.publicId && <a href={`/dashboard/directory/server/${s.publicId}`} className="text-[12px] font-semibold text-brand-300 hover:text-white">View listing</a>}
      </div>
      {!verified && (
        <div className="rounded-[11px] border border-dashed border-rim-hi px-3.5 py-3 text-[12.5px] leading-relaxed text-tx-dim">
          <p className="flex flex-wrap items-center gap-2">Your code: <code className="rounded-[7px] bg-[rgba(6,14,36,.8)] px-2 py-1 font-mono text-[13px] text-white">{s.token}</code><CopyButton text={s.token} label="Copy the verification code" /></p>
          <ol className="mt-2 list-decimal space-y-1 pl-5">
            {s.methods.includes("motd") && <li>Add the code anywhere in your server&apos;s <b className="text-tx-body">MOTD</b> (server.properties <code>motd=</code>, or your proxy&apos;s MOTD), then restart or reload.</li>}
            {s.methods.includes("a2s-name") && <li>Add the code to your server&apos;s <b className="text-tx-body">name</b> (hostname) as players see it in the server browser, then restart.</li>}
            {s.methods.includes("dns") && !s.isIp && <li>{s.methods.length > 1 ? "Or add" : "Add"} a DNS <b className="text-tx-body">TXT record</b> named <code>_nxeon-verify.{s.host}</code> with the code as its value.</li>}
            <li>Press Verify. We send one status request (or one DNS lookup) and look for the code.</li>
          </ol>
        </div>
      )}
      <div className="flex flex-wrap items-center gap-2">
        {!verified && <button type="button" onClick={verify} disabled={!open || pending} className="nx-cta h-[36px] px-4 text-[12.5px] disabled:opacity-50">{pending ? "Checking…" : "Verify"}</button>}
        {verified && <button type="button" onClick={verify} disabled={!open || pending} className="chip h-[36px] px-4" title="Re-check the code (DNS-verified listings must be re-checked every 30 days)">{pending ? "Checking…" : "Re-verify"}</button>}
        <button type="button" onClick={remove} disabled={pending} className="h-[36px] rounded-[10px] px-3 text-[12.5px] font-semibold text-[#ff8ba6] hover:text-white">Remove</button>
        {msg && <span role={msg.ok ? "status" : "alert"} className={"text-[12px] " + (msg.ok ? "text-emerald-300" : "text-[#ff8ba6]")}>{msg.text}</span>}
      </div>
    </li>
  );
}

