export const dynamic = "force-dynamic";

import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { ToolsAurora } from "@/components/nx/ToolsAurora";
import { GamePublicListing } from "@/components/customer/gamepanel/GamePublicListing";
import { GAME_FAMILIES, GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { externalServerId } from "@/lib/directory-ids";
import { isIpv4 } from "@/lib/server-directory";
import { methodsFor } from "@/lib/directory-submissions";
import { submissionsOpen } from "@/lib/actions-directory";
import { ownServers } from "@/lib/directory-portal-data";
import { pDir, pServer } from "@/lib/directory-view";
import { DirHero, Panel } from "@/components/nx/directory/DirBits";
import { SubmissionRow, SubmitForm, type SubmissionView } from "@/components/nx/directory/SubmitClient";

export const metadata = { title: "List your server · Server Directory", robots: { index: false } };

const gname = (g: string) => GAME_DISPLAY[g as GameFamily]?.name ?? g;

/**
 * "List your server": (1) the customer's Nxeon-hosted servers, each with the same Public Directory card as the
 * game panel (opt-in toggle, description, tagline/picture/website with moderation); (2) servers hosted elsewhere,
 * submitted and verified by the owner (default OFF until the owner opens the "submitted" source).
 */
export default async function ListYourServer() {
  const user = await requireUser();
  const [own, open, subs] = await Promise.all([
    ownServers(user.id), submissionsOpen(),
