const { chromium } = require("/opt/nxeon/node_modules/playwright");
const fs = require("fs");
const S = process.env.S, OUT = "/root/agent-notes/portal-directory/screens";
const token = fs.readFileSync(S + "/token.txt", "utf8").trim().replace("TOKEN=", "");
const BASE = "http://127.0.0.1:3471";
const pages = JSON.parse(process.env.PAGES);
(async () => {
  const b = await chromium.launch();
  for (const [w, h, tag, mobile] of [[1440, 900, "1440", false], [390, 844, "390", true]]) {
    const ctx = await b.newContext({ viewport: { width: w, height: h }, isMobile: mobile, hasTouch: mobile, extraHTTPHeaders: { "cf-ipcountry": "DE" } });
    await ctx.addCookies([{ name: "nxeon_session", value: token, domain: "127.0.0.1", path: "/" }]);
    const p = await ctx.newPage();
    const errs = [];
    p.on("pageerror", (e) => errs.push(String(e).slice(0, 200)));
    p.on("console", (m) => { if (m.type() === "error") errs.push(m.text().slice(0, 200)); });
    for (const [name, path] of pages) {
      errs.length = 0;
      const r = await p.goto(BASE + path, { waitUntil: "networkidle", timeout: 300000 });
      await p.waitForTimeout(800);
      const overflow = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      await p.screenshot({ path: `${OUT}/${name}-${tag}.png`, fullPage: true });
      console.log(tag, name, r.status(), "hscroll=" + overflow, errs.length ? "ERR " + errs.join(" | ") : "");
    }
    await ctx.close();
  }
  await b.close();
})();
EOF
