import "server-only";
import { db } from "@/lib/db";
import { getSetting, getSettingBool } from "@/lib/settings";
import { parseServerId } from "@/lib/directory-ids";
import { findServer } from "@/lib/directory-query";
import { nxeonConnectionKeys } from "@/lib/server-directory-data";
import { enableSettingFor, reviewedSettingFor } from "@/lib/directory-ingest/providers/types";
import { MAX_SUBMISSIONS_PER_USER, newToken, parseSubmission, verifyOnce, type VerifyDeps } from "@/lib/directory-submissions";
import { MAX_FAVOURITES } from "@/lib/directory-portal-data";

/**
 * The rules behind the portal directory's actions, with the acting user passed IN (lib/actions-directory.ts calls
 * these with requireUser()'s id; tests call them directly against a throwaway database). Every query is scoped by
 * that user id: a customer can only read, change or remove their own favourites and submissions.
 */
export type FavResult = { ok: true; saved: boolean } | { ok: false; error: string };

export async function setFavouriteFor(userId: string, serverId: string, want: boolean): Promise<FavResult> {
  const id = parseServerId(String(serverId ?? ""));
  if (!id) return { ok: false, error: "That server isn't in the directory." };
  const key = `${id.game}-${id.hash}`;
  try {
    if (!want) {
      await db.directoryFavourite.deleteMany({ where: { userId, serverId: key } });
      return { ok: true, saved: false };
    }
    const existing = await db.directoryFavourite.findUnique({ where: { userId_serverId: { userId, serverId: key } }, select: { id: true } });
    if (existing) return { ok: true, saved: true };
    if ((await db.directoryFavourite.count({ where: { userId } })) >= MAX_FAVOURITES) return { ok: false, error: `You can save up to ${MAX_FAVOURITES} servers. Remove one first.` };
    const e = await findServer(id.game, id.hash);
    if (!e) return { ok: false, error: "That server isn't listed right now." };
    await db.directoryFavourite.create({ data: { userId, serverId: key, game: e.game, name: e.name.slice(0, 120), address: e.address.slice(0, 260) } });
    return { ok: true, saved: true };
  } catch {
    return { ok: false, error: "Could not save. Please try again." };
  }
}

/** Submissions are open only when the owner switched the "submitted" source on AND recorded who approved it. */
export async function submissionsAreOpen(): Promise<boolean> {
  const [on, by] = await Promise.all([getSettingBool(enableSettingFor("submitted"), false).catch(() => false), getSetting(reviewedSettingFor("submitted"), "").catch(() => "")]);
  return on && !!by.trim();
}

export type SubmitResult = { ok: true; id: string; token: string } | { ok: false; error: string };
const CLOSED = "Listing servers hosted elsewhere isn't open yet.";

export async function submitFor(userId: string, game: string, address: string): Promise<SubmitResult> {
  if (!(await submissionsAreOpen())) return { ok: false, error: CLOSED };
  const p = parseSubmission(String(game ?? ""), String(address ?? ""));
  if ("error" in p) return { ok: false, error: p.error };
  try {
    const nx = await nxeonConnectionKeys().catch(() => new Set<string>());
    if (nx.has(p.connKey)) return { ok: false, error: "That server is hosted on Nxeon: list it from its game panel's Settings tab instead." };
    const existing = await db.directorySubmission.findUnique({ where: { userId_connKey: { userId, connKey: p.connKey } } });
    if (existing && existing.status !== "REMOVED") return { ok: true, id: existing.id, token: existing.token };
    if ((await db.directorySubmission.count({ where: { userId, status: { not: "REMOVED" } } })) >= MAX_SUBMISSIONS_PER_USER) return { ok: false, error: `You can submit up to ${MAX_SUBMISSIONS_PER_USER} servers.` };
    const token = newToken();
    const row = existing
      ? await db.directorySubmission.update({ where: { id: existing.id }, data: { status: "PENDING", token, game: p.game, host: p.host, port: p.port, attempts: 0, lastError: null, verifiedAt: null, method: null } })
      : await db.directorySubmission.create({ data: { userId, game: p.game, host: p.host, port: p.port, connKey: p.connKey, token } });
    return { ok: true, id: row.id, token };
  } catch {
    return { ok: false, error: "Could not save. Please try again." };
  }
}

export type VerifyActionResult = { ok: true; method: string } | { ok: false; error: string };

/** One verification attempt for the user's OWN submission (one status query or one DNS lookup). */
export async function verifyFor(userId: string, id: string, deps?: VerifyDeps, now = new Date()): Promise<VerifyActionResult> {
  if (!(await submissionsAreOpen())) return { ok: false, error: CLOSED };
  const s = await db.directorySubmission.findUnique({ where: { id: String(id ?? "") } });
  if (!s || s.userId !== userId || s.status === "REMOVED") return { ok: false, error: "Submission not found." };
  const r = await verifyOnce({ game: s.game, host: s.host, port: s.port, token: s.token }, deps);
  if (!r.ok) {
    await db.directorySubmission.update({ where: { id: s.id }, data: { attempts: { increment: 1 }, lastCheckAt: now, lastError: r.error.slice(0, 300) } });
    return { ok: false, error: r.error };
  }
  await db.$transaction([
    // Current proof of control wins: anyone else's verified claim on the same address stops listing it.
    db.directorySubmission.updateMany({ where: { connKey: s.connKey, status: "VERIFIED", NOT: { id: s.id } }, data: { status: "REMOVED", lastError: "Another account verified control of this address." } }),
    db.directorySubmission.update({ where: { id: s.id }, data: { status: "VERIFIED", method: r.method, ip: r.ip, name: r.name, verifiedAt: now, lastCheckAt: now, lastError: null, attempts: { increment: 1 } } }),
    db.directorySource.upsert({ where: { key: "submitted" }, create: { key: "submitted", runRequested: true }, update: { runRequested: true } }),
  ]);
  return { ok: true, method: r.method };
}

/** Withdraw the user's own submission; its directory row is removed at once (not at the next prune). */
export async function removeFor(userId: string, id: string): Promise<{ ok: boolean; error?: string }> {
  const s = await db.directorySubmission.findUnique({ where: { id: String(id ?? "") } });
  if (!s || s.userId !== userId) return { ok: false, error: "Submission not found." };
  await db.$transaction([
    db.directorySubmission.update({ where: { id: s.id }, data: { status: "REMOVED" } }),
    ...(s.status === "VERIFIED" ? [db.externalServer.deleteMany({ where: { source: "submitted", sourceKey: s.connKey } })] : []),
  ]);
  return { ok: true };
}

