import { revalidatePath } from "next/cache";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { recordAudit } from "./audit";
import { PORTAL_DIR } from "./directory-view";
import {
  removeFor, setFavouriteFor, submissionsAreOpen, submitFor, verifyFor,
  type FavResult, type SubmitResult, type VerifyActionResult,
} from "./directory-portal-core";

const LIST = `${PORTAL_DIR}/list`;

/** Save or un-save a listed server. `want` = the desired state (idempotent: double clicks are harmless). */
export async function setFavourite(serverId: string, want: boolean): Promise<FavResult> {
  const user = await requireUser();
  const rl = checkRateLimit(`dir:fav:${user.id}`, { max: 60, windowMs: 60_000 });
  if (!rl.ok) return { ok: false, error: `Too many changes. Try again in ${rl.retryAfterSec}s.` };
  const r = await setFavouriteFor(user.id, serverId, want);
  if (r.ok) revalidatePath(PORTAL_DIR, "layout");
  return r;
}

export async function submissionsOpen(): Promise<boolean> {
  return submissionsAreOpen();
}

export async function submitServer(game: string, address: string): Promise<SubmitResult> {
  const user = await requireUser();
  const rl = checkRateLimit(`dir:submit:${user.id}`, { max: 10, windowMs: 3_600_000 });
  if (!rl.ok) return { ok: false, error: `Too many submissions. Try again in ${rl.retryAfterSec}s.` };
  const r = await submitFor(user.id, game, address);
  if (r.ok) { await recordAudit(user.id, "directory.submission.create", `submission=${r.id}`); revalidatePath(LIST); }
  return r;
}

/** One verification attempt: one status query (or one DNS lookup) per click, at most 6 a minute per account. */
export async function verifySubmission(id: string): Promise<VerifyActionResult> {
  const user = await requireUser();
  const rl = checkRateLimit(`dir:verify:${user.id}`, { max: 6, windowMs: 60_000 });
  if (!rl.ok) return { ok: false, error: `Please wait ${rl.retryAfterSec}s before checking again.` };
  const r = await verifyFor(user.id, id);
  if (r.ok) { await recordAudit(user.id, "directory.submission.verify", `submission=${id} method=${r.method}`); revalidatePath(LIST); }
  return r;
}

export async function removeSubmission(id: string): Promise<{ ok: boolean; error?: string }> {
  const user = await requireUser();
  const r = await removeFor(user.id, id);
  if (r.ok) { await recordAudit(user.id, "directory.submission.remove", `submission=${id}`); revalidatePath(LIST); }
  return r;
}
