/** Portal directory v2 + owner submissions + Minecraft status parsing: PURE logic (no db, no network). */
import test from "node:test";
import assert from "node:assert/strict";
import { ago, factualLine, isFiltered, pageCount, pageNumbers, pGame, pRegion, pServer, qs, readFilters } from "../lib/directory-view";
import { containsToken, flattenChat, sanitizeMotd, cleanServerText } from "../lib/directory-text";
import { parseRaknetPong, parseSlpFrame, parseSlpJson, readVarInt, resolvePublic, slpRequest } from "../lib/directory-ingest/mc-status";
import { firstLine, methodsFor, parseSubmission, probeKindForSubmission, verifyOnce } from "../lib/directory-submissions";
import { submissionCandidates } from "../lib/directory-ingest/providers/submitted";
import { cleanVersion } from "../lib/directory-query-sql";
import { attributionForKey, steamAttributionText } from "../lib/directory-attribution";

// ── URL state / pager ───────────────────────────────────────────────────────
test("readFilters: defaults, arrays, bad values, clamps", () => {
  assert.deepEqual(readFilters({}), { q: null, players: "any", sort: "players", page: 1 });
  assert.deepEqual(readFilters({ q: ["  pvp  ", "x"], players: "has", sort: "newest", page: "3" }), { q: "pvp", players: "has", sort: "newest", page: 3 });
  assert.equal(readFilters({ players: "evil", sort: "drop table" }).players, "any");
  assert.equal(readFilters({ page: "99999" }).page, 200);
  assert.equal(readFilters({ q: "a" }).q, null, "1-char search ignored");
});

test("qs keeps only non-default keys in a stable order; isFiltered", () => {
  assert.equal(qs({ q: "a b", players: "any", sort: "players", page: 1 }), "?q=a+b");
  assert.equal(qs({ page: 2, sort: "name" }, { region: "europe" }), "?region=europe&sort=name&page=2");
  assert.equal(qs({}), "");
  assert.equal(isFiltered(readFilters({})), false);
  assert.equal(isFiltered(readFilters({ sort: "name" })), true);
});

test("pageNumbers: gaps marked 0, always first/last, nothing for one page", () => {
  assert.deepEqual(pageNumbers(1, 1), []);
  assert.deepEqual(pageNumbers(1, 5), [1, 2, 3, 5].length ? [1, 2, 3, 0, 5] : []);
