/**
 * Portal directory against a THROWAWAY Postgres (never the shared one). Skipped unless DIRECTORY_TEST_DATABASE_URL
 * is set (after `DATABASE_URL=<that url> npx prisma db push --skip-generate`). WIPES the directory tables, users'
 * servers fixtures and Settings in that DB. Focus: a customer only ever reads/changes their OWN favourites and
 * submissions, and the submitted source lists only verified rows.
 */
import test from "node:test";
import assert from "node:assert/strict";

const URL_ = process.env.DIRECTORY_TEST_DATABASE_URL;
const T = URL_ ? test : test.skip;
if (URL_) process.env.DATABASE_URL = URL_;

async function setup() {
  const { db } = await import("../lib/db");
  await db.directoryFavourite.deleteMany(); await db.directorySubmission.deleteMany();
  await db.externalServer.deleteMany(); await db.setting.deleteMany(); await db.directorySource.deleteMany();
  await db.server.deleteMany({ where: { hostname: { endsWith: ".dirtest" } } });
  await db.user.deleteMany({ where: { email: { endsWith: "@dirtest.example" } } });
  for (const [k, v] of [["directory_external_show", "true"], ["directory_src_submitted_enabled", "true"], ["directory_src_submitted_reviewed_by", "test"]]) await db.setting.create({ data: { key: k, value: v } });
  const a = await db.user.create({ data: { email: "a@dirtest.example", passwordHash: "x", name: "A" } });
  const b = await db.user.create({ data: { email: "b@dirtest.example", passwordHash: "x", name: "B" } });
  const now = new Date();
  const row = (i: number, o: Record<string, unknown> = {}) => ({
    source: "valve", sourceKey: `8.8.${i}.1:28015`, game: "rust", name: `Rust ${i}`, host: `8.8.${i}.1`, ip: `8.8.${i}.1`, port: 28015,
    country: "DE", players: i, maxPlayers: 50, connKey: `8.8.${i}.1:28015`, ipKey: `8.8.${i}.1:28015`, attribution: "steam", lastSeenAt: now, ...o,
  });
  await db.externalServer.createMany({ data: [row(1), row(2), row(3, { hidden: true })] as never });
  const q = await import("../lib/directory-query");
  q.resetDirectoryCaches();
  const ids = await import("../lib/directory-ids");
  return { db, a, b, core: await import("../lib/directory-portal-core"), data: await import("../lib/directory-portal-data"), ids, q };
}

T("favourites are per account, only for listed servers, and idempotent", async () => {
  const { a, b, core, data, ids } = await setup();
  const id1 = ids.externalServerId("rust", "8.8.1.1:28015");
  const hidden = ids.externalServerId("rust", "8.8.3.1:28015");
  assert.deepEqual(await core.setFavouriteFor(a.id, id1, true), { ok: true, saved: true });
  assert.deepEqual(await core.setFavouriteFor(a.id, id1, true), { ok: true, saved: true }, "double click is harmless");
  assert.equal((await core.setFavouriteFor(a.id, hidden, true)).ok, false, "a hidden row cannot be saved");
  assert.equal((await core.setFavouriteFor(a.id, "rust-zzzz", true)).ok, false, "malformed id");
  assert.equal((await data.favouriteIds(b.id)).size, 0, "B sees none of A's favourites");
  await core.setFavouriteFor(b.id, id1, false); // B "removing" A's favourite only touches B's rows
  assert.deepEqual([...(await data.favouriteIds(a.id))], [id1]);
  const resolved = await data.resolveFavourites(await data.listFavourites(a.id));
  assert.equal(resolved[0].entry?.name, "Rust 1");
  assert.deepEqual(await core.setFavouriteFor(a.id, id1, false), { ok: true, saved: false });
  assert.equal((await data.favouriteIds(a.id)).size, 0);
});

T("favourites of a server that later leaves the directory resolve to 'not listed'", async () => {
  const { db, a, core, data, ids, q } = await setup();
  const id2 = ids.externalServerId("rust", "8.8.2.1:28015");
  await core.setFavouriteFor(a.id, id2, true);
  await db.externalServer.updateMany({ where: { connKey: "8.8.2.1:28015" }, data: { hidden: true } });
  q.resetDirectoryCaches();
  const r = await data.resolveFavourites(await data.listFavourites(a.id));
  assert.equal(r.length, 1); assert.equal(r[0].entry, null); assert.equal(r[0].fav.name, "Rust 2", "snapshot kept for the 'not listed' state");
});

T("submissions: only the owner can verify or remove; verified rows feed the submitted source", async () => {
  const { db, a, b, core } = await setup();
  const s = await core.submitFor(a.id, "minecraft", "mc.example.org");
  assert.ok(s.ok);
  if (!s.ok) return;
  assert.match(s.token, /^nxeon-[0-9a-f]{10}$/);
  const again = await core.submitFor(a.id, "minecraft", "MC.example.org:25565");
  assert.equal(again.ok && again.id, s.id, "same address = same submission");
  const deps = { resolve: async () => ({ ip: "8.8.8.8", port: 25565 }), slp: async () => ({ online: 1, max: 10, motd: `SMP ${s.token}`, version: "1.21", protocol: 767, hasFavicon: false, edition: "java" as const }) };
  assert.deepEqual(await core.verifyFor(b.id, s.id, deps), { ok: false, error: "Submission not found." }, "B cannot verify A's submission");
  assert.deepEqual(await core.removeFor(b.id, s.id), { ok: false, error: "Submission not found." }, "B cannot remove it");
  assert.equal((await db.directorySubmission.findUnique({ where: { id: s.id } }))!.status, "PENDING");
  assert.deepEqual(await core.verifyFor(a.id, s.id, deps), { ok: true, method: "motd" });
  const row = await db.directorySubmission.findUnique({ where: { id: s.id } });
  assert.equal(row!.status, "VERIFIED"); assert.equal(row!.ip, "8.8.8.8"); assert.equal(row!.name, "SMP");
  assert.equal((await db.directorySource.findUnique({ where: { key: "submitted" } }))!.runRequested, true, "next worker tick lists it");
  const { submittedProvider } = await import("../lib/directory-ingest/providers/submitted");
  const f = await submittedProvider.fetch({});
  assert.deepEqual(f.candidates.map((c) => c.connKey), ["mc.example.org:25565"]);
  // B proving control of the same address later takes it over; A's claim stops listing
  const sb = await core.submitFor(b.id, "minecraft", "mc.example.org");
  if (!sb.ok) throw new Error("submit B");
  await core.verifyFor(b.id, sb.id, { ...deps, slp: async () => ({ ...(await deps.slp()), motd: sb.token }) });
  assert.equal((await db.directorySubmission.findUnique({ where: { id: s.id } }))!.status, "REMOVED");
  // removing a verified submission removes its directory row at once
  await db.externalServer.create({ data: { source: "submitted", sourceKey: "mc.example.org:25565", game: "minecraft", name: "SMP", host: "mc.example.org", port: 25565, connKey: "mc.example.org:25565", tags: [] } });
  assert.deepEqual(await core.removeFor(b.id, sb.id), { ok: true });
  assert.equal(await db.externalServer.count({ where: { source: "submitted" } }), 0);
});

T("submissions are closed until the source is switched on AND a reviewer is recorded", async () => {
  const { db, a, core } = await setup();
  await db.setting.update({ where: { key: "directory_src_submitted_reviewed_by" }, data: { value: " " } });
  assert.equal(await core.submissionsAreOpen(), false);
  assert.equal((await core.submitFor(a.id, "minecraft", "mc.example.org")).ok, false);
  await db.setting.update({ where: { key: "directory_src_submitted_reviewed_by" }, data: { value: "owner" } });
  await db.setting.update({ where: { key: "directory_src_submitted_enabled" }, data: { value: "false" } });
  assert.equal(await core.submissionsAreOpen(), false);
});

T("ownServers returns only the caller's servers, with public ids only when visible", async () => {
  const { db, a, b, data } = await setup();
  const plan = await db.plan.upsert({ where: { slug: "dirtest" }, create: { slug: "dirtest", name: "t", cpuCores: 1, ramMB: 1024, diskGB: 10, priceCents: 1 }, update: {} });
  const os = await db.osTemplate.upsert({ where: { slug: "dirtest" }, create: { slug: "dirtest", name: "t", vmid: 1 }, update: {} });
  const gp = await db.gamePlan.create({ data: { gameFamily: "rust", name: "t", ramMB: 1024, diskGB: 10, priceCents: 1, basePlanId: plan.id } as never });
  const mk = (userId: string, n: string, o: Record<string, unknown>) => db.server.create({ data: { name: n, hostname: `${n}.dirtest`, userId, planId: plan.id, osTemplateId: os.id, gamePlanId: gp.id, ...o } as never });
  await mk(a.id, "a1", { subdomain: "a1dirtest", status: "RUNNING", publicListing: true });
  await mk(a.id, "a2", { subdomain: "a2dirtest", status: "STOPPED", publicListing: true });
  await mk(b.id, "b1", { subdomain: "b1dirtest", status: "RUNNING", publicListing: true });
  const own = await data.ownServers(a.id);
  assert.deepEqual(own.map((o) => o.name).sort(), ["a1", "a2"]);
  assert.ok(own.find((o) => o.name === "a1")!.publicId);
  const stopped = own.find((o) => o.name === "a2")!;
  assert.equal(stopped.publicId, null); assert.match(stopped.note!, /running/);
  await db.server.deleteMany({ where: { hostname: { endsWith: ".dirtest" } } });
  await db.gamePlan.delete({ where: { id: gp.id } });
});

