import { connKey, isIpv4, normalizeHost } from "@/lib/server-directory";
import { cleanServerName } from "../valve";
import { isPublicIpv4, isProbeablePort } from "@/lib/directory-liveness";
import { politeGetJson } from "./http";
import { KLEI_ATTRIBUTION } from "@/lib/directory-attribution";
import type { DirectoryProvider, FetchContext, FetchResult, ProviderCandidate } from "./types";

/**
 * Don't Starve Together: Klei's public lobby list, the same static JSON files the game client reads
 * (https://lobby-v2-cdn.klei.com/<region>-Steam.json.gz, regions from regioncapabilities-v2.json). No key, no login.
 *
 * Terms: AMBER / NEEDS-OWNER-REVIEW. Klei publishes no API terms for these files; a Klei staff statement quoted
 * second-hand ("not an official API with guaranteed stability, third-party tools are welcome to use them") could
 * not be verified (their forum answered 403). Default OFF: the owner reads Klei's position (or asks Klei) and
 * records it in directory_src_klei_reviewed_by before enabling (see /root/agent-notes/portal-directory/SOURCES.md).
 *
 * Verified 2026-10-06 with ONE request per file: HTTP 200, gzip ~1.8 MB (~10 MB JSON) per region, ETag,
 * `{ GET: [ { __addr, port, name, connected, maxconnections, password, fo, clanonly, lanonly, dedicated,
 * allownewplayers, mode, season, pvp, v, ... } ] }`, ~10.8k rows in ap-southeast-1 of which ~3.1k are open.
 *
 * Only servers anyone can join are kept: dedicated, no password, not friends-only / clan-only / LAN-only, accepting
 * new players. Mod lists, descriptions, Steam ids and session ids are never stored.
 */
export const KLEI_BASE = "https://lobby-v2-cdn.klei.com";
export const KLEI_REGIONS = ["us-east-1", "eu-central-1", "ap-southeast-1", "ap-east-1"] as const;

export type KleiRaw = {
  __addr?: unknown; port?: unknown; name?: unknown; connected?: unknown; maxconnections?: unknown; password?: unknown;
  fo?: unknown; clanonly?: unknown; lanonly?: unknown; dedicated?: unknown; allownewplayers?: unknown;
  mode?: unknown; season?: unknown; pvp?: unknown; v?: unknown;
};

const int = (v: unknown, cap: number): number | null => (typeof v === "number" && Number.isInteger(v) && v >= 0 && v <= cap ? v : null);
const word = (v: unknown) => (typeof v === "string" && /^[a-z_]{2,20}$/i.test(v) ? v.toLowerCase() : null);

export function parseKleiRow(r: KleiRaw): ProviderCandidate | null {
  if (r.password !== false || r.fo === true || r.clanonly === true || r.lanonly === true || r.dedicated !== true || r.allownewplayers === false) return null;
  const ip = normalizeHost(String(r.__addr ?? ""));
  const port = int(r.port, 65535);
  if (!isIpv4(ip) || !isPublicIpv4(ip) || port === null || !isProbeablePort(port)) return null;
  const name = cleanServerName(r.name);
  if (!name) return null;
  const players = int(r.connected, 1000), max = int(r.maxconnections, 1000);
  if (max === null || max === 0 || (players !== null && players > max)) return null;
  const tags = [word(r.mode), word(r.season), r.pvp === true ? "pvp" : null].filter((x): x is string => !!x);
  const key = connKey("dst", ip, port);
  return {
    sourceKey: `${ip}:${port}`, game: "dst", name, host: ip, ip, port, queryPort: null, map: null,
    players, maxPlayers: max, version: typeof r.v === "number" && Number.isInteger(r.v) ? String(r.v) : null,
    tags, country: null, connKey: key, ipKey: key, alive: true, // on the lobby list = it heartbeated recently
  };
}

export function parseKleiResponse(json: unknown): ProviderCandidate[] {
  const rows = (json as { GET?: KleiRaw[] } | null)?.GET;
  return Array.isArray(rows) ? rows.map(parseKleiRow).filter((c): c is ProviderCandidate => !!c) : [];
}

export const kleiProvider: DirectoryProvider = {
  key: "klei", label: "Don't Starve Together lobby list (Klei)", games: ["dst"],
  // 4 files per run, each ~1.8 MB compressed: hourly keeps us near 175 MB/day, well inside a CDN's comfort.
  intervalMin: 60, pruneAfterDays: 1, dailyCallCap: 4 * 26,
  termsUrl: "https://www.klei.com/terms-of-service",
  attribution: KLEI_ATTRIBUTION,
  probeKindFor: () => "listing",
  async fetch(ctx: FetchContext): Promise<FetchResult> {
    const seen = new Set<string>();
    const out: ProviderCandidate[] = [];
    let requests = 0;
    for (const region of KLEI_REGIONS) {
      // Sequential, never parallel: one file at a time from their CDN. (No ETag reuse: a run must return every
      // region's rows, or the shared prune would delete the unchanged ones.)
      requests++;
      const r = await politeGetJson(`${KLEI_BASE}/${region}-Steam.json.gz`, { fetchImpl: ctx.fetchImpl, timeoutMs: 90_000, maxBytes: 40_000_000 });
      for (const c of parseKleiResponse(r.json)) if (!seen.has(c.sourceKey)) { seen.add(c.sourceKey); out.push(c); }
    }
    return { candidates: out, requests };
  },
};
