// ── Klei DST lobby adapter (rows shaped like the real 2026-10-06 response; addresses are documentation-style) ──
test("Klei: only open dedicated servers, public IPv4, plausible counts; no mods/steam ids kept", async () => {
  const { parseKleiResponse, kleiProvider, KLEI_REGIONS } = await import("../lib/directory-ingest/providers/klei");
  const ok = { __addr: "8.8.8.8", port: 10999, name: "Cozy Survival", connected: 2, maxconnections: 6, password: false, fo: false, clanonly: false, lanonly: false, dedicated: true, allownewplayers: true, mode: "survival", season: "summer", pvp: false, v: 756039, mods: true, steamid: "9029" };
  const rows = parseKleiResponse({ GET: [
    ok,
    { ...ok, __addr: "8.8.4.4", password: true },
    { ...ok, __addr: "8.8.4.5", fo: true },
    { ...ok, __addr: "8.8.4.6", dedicated: false },
    { ...ok, __addr: "10.0.0.1" },
    { ...ok, __addr: "8.8.4.7", connected: 9 },
    { ...ok, __addr: "8.8.4.8", pvp: true, mode: "endless" },
  ] });
  assert.deepEqual(rows.map((r) => r.ip), ["8.8.8.8", "8.8.4.8"]);
  assert.deepEqual(rows[0].tags, ["survival", "summer"]);
  assert.deepEqual(rows[1].tags, ["endless", "summer", "pvp"]);
  assert.equal(rows[0].version, "756039");
  assert.ok(!JSON.stringify(rows).includes("9029"), "no Steam ids");
  assert.deepEqual(parseKleiResponse(null), []);
  // one sequential request per region file, de-duplicated across regions
  const urls: string[] = [];
  const fake = (async (u: string) => { urls.push(u); return new Response(JSON.stringify({ GET: [ok] }), { status: 200 }); }) as unknown as typeof fetch;
  const r = await kleiProvider.fetch({ fetchImpl: fake });
  assert.equal(r.requests, KLEI_REGIONS.length);
  assert.equal(urls.length, 4); assert.ok(urls.every((u) => u.startsWith("https://lobby-v2-cdn.klei.com/") && u.endsWith("-Steam.json.gz")));
  assert.equal(r.candidates.length, 1);
});
EOF
